/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140609-8","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"建設委員会","time":"午後１時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"防災のところは、都市防災不燃化の事業、防災生活圏促進の事業、密集住宅市街地整備の事業、木密地域不燃化１０年プロジェクト、防災街区とたくさんの事業をされていますし、この間、まちにもかなり入ってアンケートをしたり、対話がされていますけれども、さまざまな取り組みの中の現時点の到達の評価、事業の評価をお伺いしたいのと、今後の課題をどう捉えていらっしゃるのか。","respondent":"中村都市計画課長、品川木密整備担当課長","answer":"国家戦略特区につきまして、マスタープランは平成２５年２月策定ということで、国家戦略特区は、今年度に入ってから品川区全域にわたりまして指定をされたということになりますと、まず、国家戦略特区。今後の課題につきましては、今まさに東京都と連携してやっている木密地域不燃化１０年プロジェクト、こういった事業を中心としまして、木密事業のほうをより一層進めていきたいというふうに考えております。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国家戦略特区のほうなんですけれども、インターネットを引くと、もうたくさんザーッと出てきて、いろいろな情報が載っているんですが、一つは、国家戦略特区の一番の目標というか、経済的な部分と、それに基づくまちづくりのところが大きく影響しているんですが、安倍首相は、世界で一番ビジネスのしやすい環境、国際的ビジネス拠点をつくっていくんだということで指定をしているんですけれども。","respondent":"中村都市計画課長、品川木密整備担当課長","answer":"いずれにしましても、これから検討していくという中で、国益も非常に大切ではあるとは思いますけれども、これは区のまちづくりの指針に沿ったものであるのかどうかというのは、しっかりと見定めていく必要があると考えております。全体的なまちづくりとしましても、ソフト面では消火器の対策とか、スタンドパイプとか、もろもろそういった対策も行っておりますし、そういう対策。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補助２９号線の事業認可の取り消しを求める国土交通省への異議申し立て、１０１名の方、初めてのことであるというふうに新聞に載っていますけれども、こういった状況を受けとめて、私、やっぱり区のやるべきことと言ったら、その地域に住んでいらっしゃる方々の最も望む方法をとっていただきたいなと思うんですけれども、この記事を読まれて、どういうふうに受けとめられているのか。","respondent":"中村都市計画課長","answer":"事業認可が取り消されるかどうかというところは、これはちょっと私ども区のほうでは、今のところ判断がまだできませんので、注視をしていきたいと考えています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"他区においては、住民の意見を受けて、取り下げるというか、東京都の求めに対して、うちはやりませんときっぱり言っている区が幾つもあると聞きましたので、ぜひ地域住民を第一にする考え方にぜひ切り替えていっていただきたいと、これはもう申し上げておくしか今日はないなと思っていますが、今後ともよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"」を聴取いたします。 初めに、(1)の「区営住宅入居者募集","agenda":"」を聴取いたします。 初めに、(1)の「区営住宅入居者募集","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"同居者が必要と書いてあったので、そこの要件がどうなのかということを一つお聞きしたいのと、あと、お知らせの掲載が平成２６年７月１日の広報「しながわ」とあるんですが、もうちょっと早くお知らせをするということはできないのかどうか、もうちょっと早くしていただけたらなと思うんですが、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"これは年に２回、７月と１月に募集するということの中で、私どもといたしましても、なるべく利用が終了したと申しましょうか、退室された方につきましては、即荷物の退去であるとか、原状回復工事などを迅速に行いまして、なるべく皆さんの有効な、希少な住宅ストックですので。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都営住宅、区営住宅の募集のときにあれなんですが、私の周りには、低所得者でおひとり暮らしの方が結構いらっしゃって、本当に住宅の申し込みにすがるような思いで申し込みをされるわけですけれども、低所得者、ひとり暮らしの住宅困窮をされている区民の方の展望というか、この募集要綱からすると、本当に展望が見出せないんですけれども、その辺に対してどう考えていらっしゃるのか。","respondent":"矢木住宅担当課長","answer":"実際上、これからまた実態調査をいたしまして、また、あき家であった場合、所有者への意思確認等をやっていきますので、こういった民間のまだ十分に活用されていないストックを利用していければいいなというふうに私は考えてあります。","id":"exchange-006"}]},{"id":"topic-03","title":"の「「木密地域不燃化１０年プロジェクト」新規地区申請について」","agenda":"の「「木密地域不燃化１０年プロジェクト」新規地区申請について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"そういった意味で、地域を歩いていると、こういう指定の話をすると、一体誰がどこの話を聞いてこうやって決めるのかというような声が幾つか上がっているんですけれども、資料２のところで、これまでの取り組みが進まない理由というところが書いてありますけれども、アンケートをされたんですか。そこのところを、この地域の住民の意向をどう把握したのか、その辺を教えてください。","respondent":"品川木密整備担当課長","answer":"この地域の住民の意向ということなんですけれども、この地域は、以前からまちづくり協議会というものを立ち上げて、この地区の防災性についていろいろ議論のほうをしてまいりました。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不燃領域率が低い、私、このまちづくり協議会に参加している方から、一方的に決めないでほしいという意見を伺ってきたので、だんだん参加者が減っているということでは、なかなか周りの方を巻き込んで、地域の安全を考えるような協議会には、なかなかどこの地域もですけれども、どこの地域と言ったら怒られてしまうかもしれない、なかなか広がっていないというところにおいてだと思うんですが。","respondent":"品川木密整備担当課長","answer":"以前、先行実施地区、東中延一・二丁目、中延二・三丁目地区では、戸別訪問を行っております。その中で、突然訪問して、もう建て替えてくださいとか、そういうようなことを言うことはできませんので、まずは訪問しまして、我々の制度、この制度の内容のご説明をします。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"そういうのとセットにするとか、そうやって進めていくとか、そういう手立て、除却はなくなると燃えないという、この間、説明をいただいたので、燃えない地域になるのかもしれないけれども、そこに住み続けていただくために、不燃化の助成も加えていくとか、そういうことができないのか、ぜひそういうふうにしていただけたら、少しでもいいのではないかなと思っているんですが、いかがでしょうか。","respondent":"品川木密整備担当課長","answer":"建て替えについては、専門家等も派遣していろいろなアドバイスをするだとか、そういう建て替えに向けての対応策というのも、このメニューの中には入ってあります。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この地域を新たに不燃化特区に申請をするわけですけれども、その目的のところに、建物の用途と容積率を緩和していくという、そういった思いがあるというか、目指しているのかどうかを一つ聞きたいのと、あと、この地域、若干、補助３１号線道路計画がありますけれども、ここの沿道開発も含めて見越しているのかどうか、その辺もお答えいただきたい。","respondent":"品川木密整備担当課長","answer":"補助３１号線の沿道というようなお話がありますが、現状、補助３１号線については、現在のところ、やっていくという意向のほうはございません。ここを不燃化特区にしまして、とにかく現行の制度を入れて対応して不燃化を進めていくです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"現行においては、現在は緩和は考えていないということなので、ぜひ、考えを変えるようなときは、事前に十分住民の方の意向を聞いて、拙速にやらないようにお願いしておきます。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"西品川二丁目・三丁目地区、私も昔から木密整備事業の網をかけてほしいということを何回か質問してきたんですけれども、今回こういう形で網がかけられるようになって喜んでいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"済みません、ちょっと忘れていましたけれども、ここの大井五・七丁目と西大井二・三・四丁目の、ここの地域の方々に対しての説明というか、途中経過も含めて、説明はどのようにされる見通しなのか教えてください。","respondent":"品川木密整備担当課長","answer":"説明のほうは、今までの特区の指定の経緯をなぞりますと、特区に指定されてから住民の方の説明会というものを開いているような形をとってあります。ここにつきましても同様な形で進めていこうかというふうに考えております。","id":"exchange-013"}]},{"id":"topic-04","title":"武蔵小山パルム駅前地区再開発事業について","agenda":"武蔵小山パルム駅前地区再開発事業について","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"全般に上から伺っていきますけれども、平成２６年５月に組合設立認可ということで、認可の要件を雑駁ながら教えていただきたいのと、地権者が前に８５人とおっしゃっていましたか、権利変換にかかわる方々が何人なのか。","respondent":"溝口都市開発課長","answer":"この数に間借りしているものをさらに転貸というか、貸し出している方が７名いるというふうに聞いております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"今後の予定のところに、平成２７年３月に権利変換計画認可、その後、平成２８年１月から工事着工とありますけれども、実際にあそこで住まわれている方々、あと、営業されている方々が、今後、いつまでに立ち退いてほしいという、そういった方向が出ているのかどうか、それがわかっていたら教えてください。","respondent":"溝口都市開発課長","answer":"ですから、目安としましては、平成２７年３月の権利変換認可後が一応立ち退きの時期という形になるものと考えております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人優先なんですか。その辺、幾つか道路があるんですが、説明をしていただきたいのと、この区画道路３－２は一番通りなんですが、これは変化するんですか。３－２のところが拡幅と書いてあるんですけれども、これは今のままだと思うんですが、これはどういう意味なのか教えてください。","respondent":"溝口都市開発課長","answer":"最後になりますが、３－２の拡幅ということになりますが、これは交差点部分が拡幅されるということで、表記上、拡幅というふうに都の指導で書いている形になりますので、あくまでも一番通りの道路の幅が広がるという形ではなくて、一部。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"今まで人がやっと通れていたところが車が通るということにおいては、地域に与える影響がものすごく大きいですよね。車が通る。生活支援施設の中に、公共的な駐輪場という書き方がされていたんですが、かなり駐輪場、この駅前は駐輪場が足りなくて困ってはいるんですが、どこが管理をする駐輪場になるのかどうか、その辺をお伺いしたいのと、まずはそこをお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一つは、地域の方にいろいろ情報を知らせていただきたいなとかねがね機会あるごとに発言していたんですけれども、武蔵小山駅周辺地区開発連絡ニュースというのがつくられているんですけれども、平成２６年３月現在で第４になっているんですけれども、このニュース、誰がつくられているのか、財源的にはどういうふうになっていて、どの範囲で配布をされているのかということを教えてください。","respondent":"溝口都市開発課長","answer":"住民等への周知につきましては、今後、当然、事業が入ってくる段階で事業説明、また工事説明、そういったものが入ってきますので、そういった中を通じてしっかりと周知していきたいと考えていますし、もう一つのニュースの中でも道路をつくっていく、または。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"今最後の連絡会ニュースなんですけれども、４者でつくっているということで、こういうものは財源はどこから出るのかというのと、今、新聞折り込みということですけれども、新聞折り込みだけですか。ほかで地域の方が欲しいと言ったら、ここにありますというふうな置き方はしていないのか。財源的にどのぐらいかかっていて、どこが負担しているのか教えてください。","respondent":"溝口都市開発課長","answer":"ですから、大体２５万円から３０万円ぐらいをそれぞれの地区が負担して新聞折り込みについての費用というのはまかなっているという形になると思います。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"こういうことは、ほかの地域の再開発事業においても、品川区が、このニュースに関する連絡先が品川区都市開発課になっているんですけれども、よその再開発でも、こうやって区がこのくらいかかわって、役割的にも、財政的にも負担をしているのかどうか、その辺を教えてください。最後にします。","respondent":"溝口都市開発課長","answer":"例えば、大崎でありますと、コーディネートという形で、それぞれ毎年委託して、大崎６０ヘクタールの全体の再開発事業を円滑に進めるために、それぞれ事業展開をしたり、事業者間調整、そういったものを、また、開発事業者を集めて会議等を開いてやっているところです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"びっくりされて、いろいろ質問責めに遭うんですけれども、ぜひこれだけニュースを出しているんですから、もっと目につくところに配布をするとか、あと、掲示をして、今後この地域はこういう計画があるんですよというのを早め早めに周知するのが大事かと思います。工事後のことも考えると。なので、ぜひ目に見えるような周知方法をぜひ工夫していただきたいんですが、最後、しつこいですが、お願いします。","respondent":"溝口都市開発課長","answer":"そういった中で、さらなる周知、ＰＲの仕方を引き続き検討していきたいと考えていますので、今後どのようになるかというのは、ちょっとまた連絡会の中で十分協議していきたいというふうに考えています。","id":"exchange-021"}]},{"id":"topic-05","title":"平成２６年度電力節減方針について","agenda":"平成２６年度電力節減方針について","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今年も電力節減に取り組まれるということで、必要な判断とは思います。中には、これも予算の問題等あるんですけれども、ミストのようなものを、今、つけているような施設もあるんですけれども、これは何かそういったような工夫というか、何かそういったお考えがあるのか、また、こういったなかなか涼しくないよというようなご意見があるのかどうか伺いたいと思います。","respondent":"三ツ橋環境課長","answer":"その中でのご意見というのが、ちょっと具体的にはございませんが、比較的避暑シェルターは利用されているというのが現実としています。ただ、ミストなどの考えというのは、今現在のところは考えておりませんので、またいずれ研究してまいりたいと考えています。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、２２万人ですか、すごい数だということで、やっぱり、私が想像していた以上に利用者の方がいらっしゃったんだなということで、今年もぜひ続けていただきたいですし、また、そういったお声があるということをここでお伝えさせていただきたいと思いますので、できること、できないことあると思いますけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大前提のところで、１のところに、「電力供給量は２６年８月期において前年比約１５０万ｋｗの供給減が予測されているうえ」、ここに「電力の供給不足に陥る恐れが依然としてるため」と、ここの前提のところの中身をもうちょっと、不足をするというあたりの中身を教えていただきたいのと、２番目の「平成２２年度と比較しマイナス１５％を目標」ということなんですが。","respondent":"三ツ橋環境課長","answer":"これは最終的には平成２５年度が１２.６％の節減結果が報告されております。したがいまして、今年は昨年より電力供給量の大幅減が予定されておりますため、１５％の節減率達成を目標としております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"平成２５年度よりもちょっと頑張って削減をしていくというところでは、具体的にどこをという、頑張るところというのが決まっているのか。前には、ここに昼の時間を中心にということなので大丈夫だろうなと思うんですが、公園が暗くて危ないとか、そういった声が聞かれたんですけれども、その辺は大丈夫でしょうか。","respondent":"三ツ橋環境課長","answer":"どこの部分を頑張るところですが、全体におきましてマイナス１５％と考えております。しかしながら、昼の時間帯について中心に行っておりまして、また、公園など施設が暗くなってしまうというのは極力避けてまいりたいと考えています。","id":"exchange-025"}]},{"id":"topic-06","title":"の４「所管事務調査について」","agenda":"の４「所管事務調査について」","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"うちのほうは、防災対策に関すること、まちづくりに関すること、ちょっとこれに対する補足の説明ということで、まず、防災対策については、党では、所管が今年から建設委員会に移ってきたことと、３・１１以降に特別委員会をつくり、それが今、成果物として条例もでき上がったこと、今後のその部分に関しての検討検証をさらに引き続き当委員会で扱っていくべきではないかということと同時に、また。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"区議会公明党としては、災害対策についてということと、空き家対策についてと、２点を挙げさせていただきました。もちろん東日本大震災から３年ということで、全般にわたって、これは不断の我々の調査研究が必要だということで挙げさせていただきました。これが１点です。５００ですか、上がってきているという注目すべき空き家ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉副委員長","kind":"意見","question":"地域の交通政策ということですが、これも今後さまざま開発が進んでいく中で、どのように安全な道、また、安全な交通ができるようにするかとか、その辺を考えていければなというところで出させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"意見","question":"ペーパーは提出していないんですが、説明の機会をありがとうあります。なかなかいろいろできないので、それが一つでいいかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]},{"id":"topic-07","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"大沢委員","kind":"提案","question":"恐らく皆さん重複する、いろいろと行事もあろうかと。９月８日の週のほうが皆さんいいんじゃないかと思います。９月８日の週のほうを自民党は提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"内容が決まる前に２泊３日というところで決めてしまうのでしょうか。なかなか厳しいスケジュールの中で、９月の初めというのは大変厳しい中なので、皆さんの一致で、どうしてもここに行くという中身が決まってから２泊３日なのか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"意見","question":"その週で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"私は、この時期はすごくタイトだなと思っているので、これ以外はないのでしょうか。もっと後というのは難しいんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"提案","question":"かなりタイトであるので、皆さんがぜひというのでしたら、委員長に逆らって行かないということにはならないと思うので、行き先も決まらないうちからここで委員長提案が２泊３日ということだったので、ちょっとそれはどうかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"もう一つは、調査項目として空き家対策ということを我が会派としては提案いたしましたので、この４月に名古屋市で空き家対策条例というものを施行いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"意見","question":"この間、本当に被災地のところは、なかなか受け入れ態勢が厳しいという、かなり声が上がっていたけれどもなかなか実現をしなかったというところがあるので、受け入れてくださるところがあるんだったら、委員会で行くというのは有意義かなと思って、一つは、東日本大震災の地震とか津波の関係のまちづくりの部分で、いろいろ実態とか、その後のご苦労とか、問題点とか、知りたいなと思うんですが、一つは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-08","title":"の６「その他」","agenda":"の６「その他」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今ざっとご説明を受けただけで、よくわからないというのが実態で、しっかり見て、どう影響するのかなということをお聞きしなくてはいけないなと思っているのと、特に八潮地域とか影響が大きいところで、後で質問責めにあってしまうことになるので、今日は資料をいただいたばかりなので、ぜひまた改めてお話を聞ける時間をとっていただきたいなと思うのが一つと、あと、この情報提供ということですけれども。","respondent":"中村都市計画課長","answer":"その５００ｍ上空、あるいは１,０００ｍあるいは１,５００ｍと上昇するに従って、騒音がどのぐらいになってくるのかという、こういったところは国に改めて情報提供を求めてまいりたいというふうに考えております。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問","question":"とにかくこの件に関しては、知識もないので、調べてみたいなと思っていますので、ぜひ次回なり、またその後なり、お時間をとっていただければと思いますので、そういう方向でよろしいでしょうか。","respondent":"中村都市計画課長","answer":"今委員申されました疑問点等につきまして、お気づきの点がございましたら、私のほうでお調べをしたいと思いますので、随時お問い合わせをいただければと思います。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817105?Template=document&Id=4106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":53424,"voices":155}},{"id":"h26-20140609-9","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"文教委員会","time":"午後１時００分～午後３時３７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、４６ページの体罰の根絶を図るための取り組みということで、いろいろな事業をされているということなのですけれども、この間２回の実態調査をしてみて、残念ながらケースとしてはゼロではなかったという実態があるという報告をこの間いただいているわけですけれども、前回の委員会のときにもそういう報告があったとき、やはり教員の方々の人権感覚というのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"もちろんそのつもりで、だから深く関わらないで、しかしこれを事前に読んできたとき、ちょっと見えない部分を質問しているつもりなので、そういうふうに受けとめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それからもう一点、５７ページに学校職員の数が出ているのですけれど、栄養士をそれぞれこの学校に配置していますよというふうに出ていて、私としてはわかりやすくてよかったなと思って見たのですけれども、この学校に配置している基準というのですか、考え方というのか、それはどういうふうになってこの学校に配置されているか、ちょっと教えていただきたいと思います。","respondent":"野呂瀬学務課長、田村教育次長","answer":"就学援助の単価表ですけれど、先ほど私が申し上げたのは平成２５年度の分で、２６年度の新たな分についてはまだ決まっていないということです。ですから給食業務調理代行をしている業者とはまた違う民間の人を、なぜかというと、ご存じのとおり食物アレルギーとか、やはり専門的な意識を持った人が。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"もう１学期が始まって２カ月たっていますので、学校に通学している子どもに対して一定の支援という形で心配しておられると思いますので、私はやはり消費税増税分も含めてきちんと対応していただきたいということを、検討の中に入れていただきたいということを強く要求しておきたいと思うのですけれど、考え方としてどうなのかというところをさっきから聞きたいと思って質問しているので。","respondent":"田村教育次長、野呂瀬学務課長","answer":"南委員がおっしゃっているとおりで、栄養士は２校に１校配置、給食業務を基本的には全部、栄養士のいない学校に配置していたのですけれど、そろそろ退職の人が出たので、その学校については、ここに空白がある学校は。考え方としては、冒頭もありましたとおり就学援助費をほかの区では変えているとかいろいろありますけれども、品川区の考え方としては、国のほうの対策が変わったとしても、受けている方が不利にならないように。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つだけ確認させていただきたいのですけれども、最近、厚木のお子様の放置についてニュースになりましたけれど、我が品川区では、こういうお子さんに対しての把握をなさっていらっしゃるのでしょうか。していないわけはないと思いますが、ちょっと確認だけさせていただきたいと思います。お願いします。","respondent":"伊崎子育て支援課長、野呂瀬学務課長","answer":"その結果につきましては、ご報告できる時点でまたご説明したいと考えています。いずれにしましても、書類だけのやりとりだけではなくて、こういう事件が起こったからではないです、以前からですけれども、私ども学務課のほうで、いわゆる潰しといいますか、ちゃんと。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"今年４月に認可保育園に入園したいという申請をしたけれども、結果的に入れなかった方が品川区の発表では１２６人になっているのですが、前回のこの文教委員会でも内訳を教えてくださいと聞いたのですけれど、この１２６人という状況が今までになく、昨年度の倍になっているという状況について、品川区の認識と、４園の私立認可保育園をつくったということで今年度はよしとしているのかという。","respondent":"伊崎子育て支援課長、今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"は習い事等への送迎になってあります。最後に待機児童数ですけれども、平成２６年度はこちらの２４ページの資料にありますとおり１２８人ということでございまして。この考え方につきましては、区としても今後協議してまいりたいと考えております。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、やはり品川区がそういう期待に応えて、時代は変わっても保育や子どもの対策、福祉はさらに需要にきちんと対応できるように充実させる、そういう視点が私は大事かなと思っているので、それは区民の声も含めてしっかり受けとめていただきたいということで、ちょっと取り上げたのですけれども、そういうことでどういうふうに考えていらっしゃるかを、予測も含めてお話を伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現在、子ども・子育て支援事業計画の中でも、保育のいわゆる必要性というものが十分反映された計画を今後策定していくというふうに考えておりまして、幼稚園そして保育施設、在宅子育てのバランスをとりながら。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点でやはりきちんとした対策を、バランスとおっしゃったそのバランスの背景には、在宅ということも入ったバランスというふうにおっしゃっていたので、ちょっと保育需要との関係では違うかなと、私はそういう印象を持って伺ったのですけれども、必要な方にしっかり提供できるように、しかも今、国では女性の社会進出ということを非常に重要視しているわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋委員","kind":"質問","question":"１つだけ、４ページの職員の配置なのですけれど、児童相談所に区の職員の方が行かれているのは、この中に入っているのですか。","respondent":"伊崎子育て支援課長","answer":"この中には入っておりません。数字としては人事課付になっております。","id":"exchange-009"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"こちらは簡単にいいますと、これまでもさまざまな角度でそれぞれ細部に当たる事業、類似事業等あるかと思いますが、総じていうならば、やはり区民ニーズの中でも都市部、核家族化が進む中で、需要というのを肌で感じている中で、次なる展開、これまでの展開をまず基礎とすれば応用的に、拠点となるセンターの検討を含めた提案が自民党の中でも根強くあったものですから、項目として上げさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"提案","question":"私は一点だけなのですけれども、先ほどの質疑の中でも待機児童対策、来年新しく制度ができるので、この委員会としても、これから品川区としても条例を提案されたりすると思っているのですけれども、昨年度からいろいろと品川区の中の行政としての保育の体制について、検討、研究されておられると思うのですけれど、議会側からも一緒になっていろいろな意見が出していけるように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"一つが、出ましたけれどもスポーツ教育です。関連して体力向上で、あとあわせて体をつくるというところで食育、これは国のモデル事業でしょうか、スーパー食育スクールとかこの辺を含めて、品川区としての取り組みをどうしていくかというところです。は世代間交流です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"意見","question":"我が会派で話をした中で、項目は４点。１つはＩＣＴ活用について、さまざまな運用をされる中で、その活用について調査研究をできたらなと。それと、いじめについて。もう一つが体罰について。そしてもう一つがコミュニティスクール導入について。以上、４点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"吉田委員","kind":"意見","question":"我が会派では、先ほどからこの事務事業にも入っておりましたけれど、教育の情報化の課題と適応力の推進についてをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"高橋委員","kind":"意見","question":"それとともに、就学前だと巡回支援などを中学校はやっていますけれども、今後さらに巡回して指導ができるような形の仕組みづくりなどについて、調査するのはどうかと思いました。これは大きな話になってしまうんですが、幼稚園、保育園の公設民営化についての調査、研究というのも、自治体の中では行っているところもあるので、課題や成果が出ていると思いますので、その点について。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"意見","question":"前回、正副委員長からお話がありました所管事務調査との関連が深いのと、きょうお見受けしている中でもかなり調査の希望が多岐にわたっていましたので、正副委員長にお任せをしたいと思います。場所あるいは調査項目も、関連が深いかと思いますので、私も先ほどのあれを踏まえているという認識でいますので、お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"吉田委員","kind":"意見","question":"我が会派でも、視察についてですけれど、やはり品川区と同じ土俵というふうに考えまして、経費もかけずになるべく東京近郊の近いところになるような、視察をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"つる委員","kind":"意見","question":"今、渡辺委員からありましたけれど、基本は正副委員長にお願いしたいと思いますけれど、一応公明党としての案を、ペーパーでも、紙ベースでもつくりましたので、それを改めて提出させていただいて、それを含めて正副委員長で最終的には決めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"ただ、ちょっとあるけれどもなかなか、遠いし、遠隔地だし、ちょっとあれかなと思って場所については言い出しにくくて、そこはとめておきたいと思うのですけれど、そういう角度でやっている行政があったらぜひ入れていただけないかと考えていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/974009?Template=document&Id=4824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":45811,"voices":91}},{"id":"h26-20140609-5","meetingId":"h26-cm06","date":"2014年6月9日","dateIso":"2014-06-09","committee":"総務委員会","time":"午後１時００分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ概要を伺ったのですけれども、今年の特徴や重要課題は品川区としてはどんなふうにお考えなのかを伺いたいと思いました。会計管理室、企画部、総務部、総務委員会ですので、選挙管理委員会事務局、監査委員事務局と、そういう部署がありますけれども、今年の特徴、重点課題また重要課題と言えばよろしいのでしょうか、そこをご説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"事務事業の説明ですので、今年の特徴は何かという質問はそのままの質問だと思います。今、説明があったのは、今年の１年間こういう仕事がありますよという説明があったと思いますけれども、その中で今年の特徴だったり、重点課題だったり、重要課題だったり、いわば今年ここが大事なところですよというところを聞くのはまさに概要説明そのものだと私は思いますので、質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"つまり基金が７２７億円で、現金など２１０億円あって、合計９４０億円という概要説明でしたけれども、この２１０億円という金額は、一般会計予算とは別にそこの会計管理室にあるわけですけれども、その金額というのはどういう根拠があるのか、１年間のやりとりの中で必要な金額ということなのか、そこの考え方を伺いたいと思います。具体的に何か代表的な事例などがありましたら、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"しつこいようですが、逆に伺いますが、どこが個別なのか伺いたい。私が聞いたのは概要についての考え方を聞いたのです。例えば２１０億円の歳計現金というのか、これはどういう考え方ですかということを聞いたのです。委員長が個別というのは一体何を指すのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"概要と個別の違いは何ですか。先ほど言った例えば２１０億円の歳計現金高、これがどういうふうに積み上げられているのかと聞いているのではなくて、この考え方は何ですかと聞いているのですね。委員長の言う概要と個別というのは何ですか。今、区の一つの事業が個別だというのだったら、本日の概要説明は個別説明ですか。委員長の概要と個別というのは何が違うのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"ですから、概要と個別の違いは何ですか。一つひとつの事業の説明が本日なわけでしょう。その事業についての考え方を聞いて何が悪いのですか。そんなこといったら何も聞けないし、逆に何も説明できないではないですか。その選挙というのは個別ですから説明できません。では、一体何を言うのですか。概要に対して、平たく言えばもっと詳しく聞きたいという質問の何が悪いのですか。だから、質問をしたのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"数字の細かいとか言われると、数字自体もざっくり聞いたつもりだった。では、気持ち改めて。いわゆるやりとりの事情でこれぐらいの規模が必要だという考え方なのか、状況を伺いたいと思います。それと、８月にもご報告があると説明がありましたが、財政調整交付金について最近の傾向や変更点、見通しも含めて、現在ある変更点や傾向、また今後の見通しも含めてご説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"あわせて伺いますけれども、広報広聴課ですけれども、今年の長期基本計画で広報と広聴の役割を明確にするというのがありましたけれども、今年から具体的にどんなふうに変わっているのか、その趣旨とあわせて伺いたいのと、本日の資料にも広聴会の開催とありますけれども、最近あまり聞かないですけれども、これは施設建設の計画に限るものなのか、どういう実形なのか伺いたいと思います。","respondent":"本城企画財政課長、小林施設整備課長、荒井広報広聴課長","answer":"財政調整交付金につきましては平成２６年度予算ということでご説明して、今の時点の傾向というのは特にその時点から変化している部分はありません。施設整備課のほうでは、今、不調関係のお話だと考えていますが、去年から大分右肩上がりで基本単価等が上がっているのは現実的にあります。ただ、実際には今般、それぞれの所管が積極的に説明会等々を実施しておりますので、公聴会という形で開催しているのは。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"経理課で、財産価格審議会、昨年の実績ということで１３件、５回の審議会ということがありましたけれども、今年はどういうスケジューリングなのか、どういう対象物というか、事業物というか、回数、件数なのか、今年の状況を伺いたいと思います。","respondent":"江部総務課長、立川経理課長","answer":"区長と教育委員の懇談のお尋ねですが、これはあくまで懇談ですので、ざっくばらんに意見交換をしてお互いに情報を共有するというところにありますので、特に要請するものではございません。第２回目以降につきましては、今のところスケジュール的には確定はしておりません。","id":"exchange-009"},{"speaker":"西本委員","kind":"確認","question":"これからの議論の流れというか、役割分担を確認したいのですが、まず、企画部のほうでオリンピック・パラリンピック調整担当というのがあります。地域シンポジウムのほうにもあると思いますけれども、その役割をどういうふうに考えていったらいいのかと、すみ分けが、どういうところですみ分けをするのでしょうか。これは委員長にも関係あるのかもしれませんけれども、確認したいと思います。お願いします。","respondent":"柏原オリンピック・パラリンピック調整担当課長、荒井広報広聴課長、江部総務課長","answer":"組織ということで連携関係の、担当の部分について回答します。今後とも引き続きできるだけ載せていけるように周知を徹底していきたいと考えているところです。これにつきましては各課の、メーンとしてはその課が所管しておりまして、連携をとるほうと事業協力をしているものですので。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"オリンピック・パラリンピックの件は、内部的な調整の案件はこちらで報告をしていただけるという理解でよろしいですか。内部的な調整ということでこの部署があるよという認識でよろしいでしょうか。その辺をもう一度、確認させてください。これは要望にしておきます。オリンピック・パラリンピックのところだけお願いしたいと思います。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"今みたいなことでちょっと確認させてください。すみません、議会のほうなので委員長が判断される。その仕切りの中でやる範囲の中で確認だけさせてください。そうするとこちらで判断できるかという気もあるので、そこら辺のところをちょっと教えていただきたい。","respondent":"荒井広報広聴課長","answer":"これから広報広聴課としてのスタンスをどこに置くか、それから全庁的に取り組んでいくものだというふうにそれは捉えているところですので、それぞれ個別の事業になりますと、あるいは観光であると区民委員会であるとか、例えば教育であるとか。","id":"exchange-012"},{"speaker":"石田委員","kind":"確認","question":"大枠の話で確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の３「その他」","agenda":"の３「その他」","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"１点だけ。建設委員会所管なので要望にとどめておきますが、本当はこういうシェルターを設置するというのが地域のご高齢者の方、子供たちとかが暑さをしのぐとかで水分を補給する、すごくいい取り組みだと思います。そうなると、全く目に触れないところで立っていたので、「あれ、何でだろう。これは要望にとどめておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"ここで質問する内容なのか、答えられなかったらその旨でおっしゃってください。２の(3)ですが、区民サービスの低下を極力招かないということですが、これはどういう、具体的にあるのですか、どういう状況だと区民サービスの低下を招くだろうという、そういう基準というのはあるのでしょうか。お答えできたらお願いいたします。","respondent":"江部総務課長","answer":"施設によりますけれども、基本的に例えばスポーツ施設とかで照明等がなければできないことになりますので、そういう機能に応じた必要なものというのは最低限守ると。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"というのは、そこをお使いになっている方々には扇風機をもう１台増やすとか、いろいろな工夫ができるといいとは思いますけれども、そういうのを細かく施設ごとの環境については把握した上でのこういう方向づけなのか、もう少し、一律ではなくてきめ細やかな対応をすることによって区民サービスの低下を招かず、ご理解を求められるようなことができるのではないかと思いますがいかがでしょうか。","respondent":"江部総務課長","answer":"直接所管は違いますけれども、きめ細かな対応を区民に対してしていけるように所管に伝えてまいります。","id":"exchange-016"},{"speaker":"石田委員","kind":"確認","question":"１点だけ確認をさせてください。確認だけさせてください。そういうところについては去年同様やってくれるということで、その確認だけ。ですから、それはそれで今年もそれと同じ考えで、公園なんかもそういう同じにやってくださったのだけれども、そういう感覚でいいのですよねという確認だけ。","respondent":"江部総務課長","answer":"委員おっしゃる中身で大丈夫だと思いますが、念のため確認はいたします。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"先ほどコンビニ収納とかいろいろな話が出てきたけれども、昨今、公金の収納で例えばクレジットカードで支払えるとか、いろいろそういうのが始まって、我々も耳にする、目にすることが、公金収納の扱いがあって、これは今の時代、私はこれはチャンスありというか、品川区としても取り組むべきかというところで、今すぐにどうというのはいいですけれども、それは所管事務調査として１回しっかり議会もあわせて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"改めて。あまり質問はしませんけれども、本来東京都がやるべき事業なのにいまだに対象となっていなかったり、逆に対象となっていたのを要するに２階に上げてはしごをとったような形になっていたり、一つひとつの事業に財政調整交付金の算定のものがあるわけですけれども、そこにある特徴や課題を明らかにすることができたらと思いますので、基準財政需要額と、需要額の中身、ひとつよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"これは今ここで言うべきかどうかわからないですが、前回の総務委員会のときにナンバー制度というのですか、個人制度で説明する側も、質問する側もなんかちょっと、あまりよくかみ合っていないというか、わからない部分が多いので、それは所管事務調査なのか、改めて勉強会なのかわからないですけれども、それはやってもいいのかという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう一つは、大都市問題というのは、これはやはり品川区、２３区、横浜もそうですけれども、ますます、先ほどの高齢化も含めて、人口が流入すればさまざまな問題がこれから出てくると思いますので、その辺を私は行政視察で、遠方に行ってほとんど人がいない、また税収が入らない、人が流入してこないようなところではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"西本委員","kind":"意見","question":"当然、財政調整交付金はしっかりとどういう積み上げ方になっているのとか、学んでいく、その上で現状どうなっているのか、今後どうあるべきなのかというのは当然やっていかなければいけない部分ではありますが、多分学ぶということであると所管事務調査という項目にはなり得ないので、それをまたどうしていくのか、そうなると都区制度のあり方というふうに大きく捉えたほうがいいのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田委員","kind":"意見","question":"今せっかくたくさん意見が出たので、あとは副委員長が公明党でもという意味を含めれば、全会派のほうが意見を言えるのだし、正副でやっていただければ全会派意見を言えるということだったら、今５点ぐらい出たのであれば、それは一任するので決めていただいて、すぐスタートしていくというほうが、そんな、出してどうとかではなくてスタートしていったほうがよっぽどいいし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田委員","kind":"意見","question":"違うのは違うけれどもそれはそれで、それなりのことも含めながらというのであれば、そういうのも含めてぜひその中で、一任をしますので、相手のあることも含めて決めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"繰り返しますけれども、せっかく行くならば、視察も、我々も勉強したい。するならばやはり品川区、これだけの、本日いろいろ概要説明がありましたけれども、これだけの事業をやっている。これだけの予算規模で動いているということを考えていただいて、それに匹敵する、準ずるような都市をぜひ参考に、我々、どうせ行くなら、視察先としてやっていただきたいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問","question":"もう１点、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997792?Template=document&Id=1984#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":36954,"voices":120}},{"id":"h26-20140610-14","meetingId":"h26-cm06","date":"2014年6月10日","dateIso":"2014-06-10","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それぞれの報告から一つ程度、伺いたいと思います。それから、契約事務のほうはすごく細かい話ですけれども、議会の議決を要する契約の中で、「１件４,０００万円以上の不動産」とありますが、これは細かい話ですが、４,０００万円の一部、中古物件に施工の行使がそこそこ乗っかってくるみたいなものは、これも議決が必要になるのでしょうか、教えてください。","respondent":"柏原行財政改革担当課長、立川経理課長、本城企画財政課長","answer":"昨年来、一部の報道では、都の未利用地については高齢化に対応していく等との話も出ているのですけれども、我々も、都の財務局。取得する場合という、いわゆる取得価格が４,０００万円以上であれば議決案件ということになりますので、三千数百万円にリフォームをして。ただ、かなり規模の大きくなっているという意味で、量的にかなり大きくなっていることもありますので、今後どのような形で基金を活用していくかについては。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。そういう意味では、ぜひ検討のスピードを上げるように要望もしていただきたいと思いますので、これは要望にしておきます。それから、基金ですけれども、おっしゃるように額が大きいものですから、今後検討ということですけれども、検討のスケジュールですとか、どういう組織といいますかチームで検討するかというようなことは考えていらっしゃるかどうか、あれば教えてください。","respondent":"本城企画財政課長","answer":"現在もまだ具体的にどういう形というわけではなくて、例えばここから生ずる、かなり規模が大きくなって、運用益も含めて既存の目的の中に使っていくということで、ただ、規模が大きくなったこともありますので、基本的な考え方としては。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問・要望","question":"この最後の基金ですけれども、これまで９６０万円ぐらいですよね。で、今期になって、ただ６億円増えてずっと放置されているような状態は、決して好ましくないと思います。これまでに使ってきたものも、やはり意味があって、目的がある中でやってきているわけですから、これはぜひ早急に検討していただきたいと思います。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"南委員","kind":"提案","question":"先ほどの説明では、今後、見込み額ということで示したということですけれども、１０億円から２０億円ぐらい増えるのではないか、そういう説明でしたけれども、これは平成２５年度末のそういう説明ですけれども、ここ５年程度でいいと思いますけれども、年度ごとの出と入り、推移がどういうふうになっているのかもつかみたいし、あと、１年を通して例えば財政調整基金などは。","respondent":"柏原行財政改革担当課長、立川経理課長、本城企画財政課長","answer":"今回お出しした国有地の資料といいますか、全体、昨年度の中で議論になって一定程度方向性が出たものと。具体的には予定価格の適切な設定であるとか、予定価格の事前公表、それから現在見積もりをしております最低制限価格制度、また。ただ、今後、こちらでご報告する中で基金の変化につきましては、先ほど委員からのご指摘がございましたように、取崩し型であれば幾ら積み立て。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"公契約ですけれども、よく「人間らしい労働」とか「人間らしい生活のできる」という、そういう賃金、「ディーセント・ワーク」とか「ディーセント・ライフ」とか、そういう言葉で言われている賃金の保障、そういうものがやはり必要だし、公が発注する事業についてなかなか、財政効率をよくというところは、それはそれで理解できるところですけれども。","respondent":"立川経理課長","answer":"そういった常に最新のものを利用して工事の予定価格を積み上げていく、そういった中で事業者の方に入札に参加していただくことになっておりますので、区としましては、適切な価格による入札をしていただきまして、それがまた二次下請。","id":"exchange-005"},{"speaker":"南委員","kind":"意見","question":"最後に、昨年度も保育士の単価、あるいは介護士の単価ということで、年度途中に補正予算が組まれたと思っていますが、それは、そういう必要性があって国の段階で指導があって単価の改定というふうになってきていると私は理解しているのですけれども、その改定そのもの、そういう措置は否定するものではなく、むしろ遅きに失したとはいっても是正されるべきだと思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"提案","question":"むしろ基金については、これまで余り行財政改革特別委員会でも扱って大分あいたのでしょうか、最近やっていなかったと思うので、まずは基金について少し理解を深め、さまざまな意見交換をし、その後、契約事務という形でもいいのかと思っていますが、いかがでしょうか。一つの提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"南委員","kind":"提案","question":"それこそ私が議員になったあたりから、それからもうちょっとしてからかしら、大井町の新地区の開発が昔のイトーヨーカ堂のところに開発種地ということでそれなりの土地を区が持っていて、今、駐輪場に開放しているようですけれども、そこの活用方をどういうふうにしようとしているのかとか、そういう区が持っている土地を全部つまびらかにしていただいて、そして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"先ほど、ほかの委員から出ました基金のことについては、初めてここで出ましたので、これはぜひ勉強していきたいと思います。それから、契約事務のところで、私がすごく気になって質問した記憶がありますけれども、平成２５年度の決算特別委員会の中で、たしか３億３,０００万円の契約落差があった記憶があるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員長","kind":"質問","question":"今、基金について、それぞれご意見がありまして、この委員会でも基金について取り上げるのは初めてなのか、久しぶりなのか、ちょっとあれですけれども、久々だということで、この基金について深めたい論点だとか、問題意識であったり、また、方向であったり、議会的に言えば迫り方と言えばいいのでしょうか、あるいは、そういう問題意識があれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林委員","kind":"提案","question":"これは、区側のそういう考え方とともに、議会、私たちとしても、私たちの目線での例えば公共施設整備基金や財政調整基金のところの残高の、議会・議員目線や区民目線から見た基金のあり方は、私たちのほうからもしっかりと逆に、提案というのですか、アイデアを出し合っていきたいという思いもありますので、そういった観点での資料はしっかり見ていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問","question":"先ほどの委員長の基金のことでしたので、そうすると、例えば一つの案ですけれども、基金の目的が明確になっているわけですから、目的に対する具体的な基金の投入金額と、それから実績と成果、例えばこれは過去５年間ぐらいでいいとは思うのだけれども、それが資料のお願いができるのかどうかということが１点と、それから、それに基づく品川区の基金運用計画があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"基金についてですが、果実運用型基金が実際に果実だけで関連の目的の事業が行われるとは、昨今、厳しいのですが、果実運用型基金の中で果実と関連する事業との対比がどうなっているかということ、もっと言えば、その基金の額が適正なのかどうか、目的に照らし合わせて、「適正」と言ってはいけないですね、妥当なのかどうかといったことを考えたいと思いますし、取崩し型、先ほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"私も、基金のことを１点だけ申し上げたいと思いますけれども、とりわけ果実、先ほどは取崩し型のほうで、数年の間の推移を見たいというので情報を出していただきたいとお願いしたのですけれども、果実運用型でも、果実運用型ですから、どのくらいの利子がついたのかで、そこの利子で使っていくわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須藤委員","kind":"提案","question":"そうすると、我々自民党は、前から文化・スポーツの振興基金みたいなものを行政側でつくって、そういう支援を、違った形で支援できる体制をつくったらどうだろうということは前から私どもは言ってきているので、もし委員会で時間があって皆様の議論ができれば、そういうことも行政側に提案の中に、みんなの意見が一致すれば声を出して、今まであるものももちろん勉強していくことも必要だけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/711220?Template=document&Id=5968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":20183,"voices":55}},{"id":"h26-20140611-18","meetingId":"h26-cm06","date":"2014年6月11日","dateIso":"2014-06-11","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時１７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"木村副委員長","kind":"意見","question":"副委員長の木村けんごです。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"ちょうど昨日なんですが、都知事からオリンピックのいろいろな見直しを行っていくというお話があったかと思うんですけれども、全く聞いていなかったことかと思うんですが、区のほうでは、どういうふうな捉え方をされているのか。もし何かお考え等、ちょっとこういう感じで話が来ているとかありましたら教えていただければと思います。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"昨日の知事の発言につきましては、区としても承知はいたしていますが、詳細にどこの会場をどうのということは全く聞いてございません。これから慎重に情報収集してまいりたいと考えています。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"大幅な変更等はないかとは思うんですけれども、会場に関しては、やはり今品川区で２会場ということになっていますし、正直、予算の問題等都のほうでいろいろな話が起きているということはわかっているんですけれども、もし場合によっては、品川区でも会場、競技数が増えるということはあってくれればよりいいかなと思っているんですが、そういった形で、まだ詳細はわからないですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-03","title":"視察の前に、予定表４のその他","agenda":"視察の前に、予定表４のその他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ちょっとオリンピックが東京オリンピックから既に５０年が経って、これから６年後というと５６年ぶりの日本で言えばオリンピックの開催というふうなことになるわけですけれども、オリンピックの原点というか、そういうところに立ち返ったところをしっかりと確認し合うというか、その上で取組みを進めていくということができるといいなというふうに思いましたので、ご検討いただけたらと思います。","respondent":"渡辺委員長","answer":"今後の運営の中で正副で調整させていただき、検討させていただきたいと思います。","id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"提案","question":"ご提案の趣旨がわかって、委員長もご了解だと思うんですけど、ちょっと障害者のまちづくりというと、会派の中に副委員長もいらっしゃいますし、厚生委員会との絡みという問題も出てくると思います。その辺を十分発言の中でもご注意いただければと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"いながわ委員","kind":"確認","question":"委員長に確認だけなんですが、２０２０年オリンピック・パラリンピックに向けてどういう競技場のあり方とかという形でこの特定事件調査の１から９まであると思うんですけど、この議論の中で、むしろオリンピック・パラリンピックまでどういうことをするべきか、どんなまちづくりをするのかというのはすごく大切なことだと思いますし、ただ、それだけではなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員長","kind":"提案","question":"それによって、質疑、提案、特に最初のこの委員会は、質疑というより、各委員からいろいろな提案を受けて、品川区の立場で東京都や国への要望というのも一つの目安になるかと思います。ただ、形にする際、まとめですとか、要望を形にする際には、その辺は十分加味しながらやっていきたいと思いますので、またこれも適時、進行上相互にご指摘いただければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、品川区の軟式野球と少年野球の連盟、それから東京都の軟式、硬式野球の連盟の方々から、都に対しての要望書も出されているというところでは、やはり区内の競技場になる場所の今現在使われている皆さんの要望も強く受けとめていかなければいけないと思いますし、都知事も先ほどほかの委員からもありましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"質問なんですが、７番のところの隣に、特区構想と書いてあるんですけども、関連のある項目となっていて、この特区構想というのは、今の時点でどんなものが想定されるのかというところがわかるものがあれば教えてください。","respondent":"渡辺委員長","answer":"今予定表の中に公式な見解等が出た場合には正副で検討しましょうという、委員長と副委員長の間での検討課題という形になっています。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"提案","question":"先ほど野球場という話が出たので、当然検討していくというよりも、要望事項が出てくると思うので、逆に言うと、早い時点で委員会として都に対しての意見書ですとか要望書みたいなものを出してもいいんじゃないかと思う、委員会提案で。これも考えておいてもらえれば、全員で検討していきたいと思いますので、委員長のほうで、ご配慮をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/920985?Template=document&Id=6454#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":12732,"voices":49}},{"id":"h26-20140630-6","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"区民委員会","time":"午前１０時００分～午後０時２７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","topics":[{"id":"topic-01","title":"第５１号議案、指定管理者の指定","agenda":"第５１号議案、指定管理者の指定","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"それとあと、品川ビジネスクラブとマグネットスタジオは、設立もそんなに、若い事業体じゃないですか。大きいところばかりじゃなくて、経験も浅く、規模も比較的小さいところに期待を寄せるというのは、すごくいいなという印象がありますけども、ただ協定書を締結するときに、その役割というんでしょうか、甲乙とか、責任の所在とか、実務的なこととか、その辺のところを教えていただきたい。","respondent":"山崎ものづくり・経営支援課長","answer":"ただ、中身としましては、今ご説明申し上げたとおり、大きな広いイベントホールの運営と、それから４階のほうでは、産業支援の活性化に資するソフト事業を考えていただいて、交流を創出していただくようなことがありましたので、４月の指定管理者の募集の要項で。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"最後に、細かいことなんですけど、施設のＰＲ用ホームページの開設をやるというのは、どこがやるんですか。","respondent":"山崎ものづくり・経営支援課長","answer":"今回議決をいただきましたら、それを理由に指定管理者のこの共同事業体のほうと随意契約をさせていただきまして、事務の中でこの共同事業体のほうがホームページを作成してというようなことで考えてあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"基本方針の的確さも判断をした、収支計画の妥当性、現実性も判断をした、そういうふうなところでさまざまこういう基準に基づいて区が判断しているというところになると思うんですけど、そういうのが、どういう提案があってこういう判断になったかというあたりを、もうちょっと私たちが判断できるような形での資料というのをぜひいただきたいなと思うんですけど、その点を１点お聞かせいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"議会でありますとか委員会に関しての資料の部分でございまして、区におきましては、指定管理者制度の活用に係る基本方針ということがございまして、指定の議決をいただく際の議決すべき事項としまして、公の施設の名称でありますとか、指定管理者の団体の名称。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"それと、その料金のところについては、基本的に条例に書かれている使用料ということでの提案だったということなのでしょうか、それよりももっと下げた提案というふうなことでされてきているのか、最終的には多分区と協定を結んで、料金というのが決まるということになっていくのかと思うのですけど、向こうからの提案と今後の見通しというあたりはどうなのかということも教えていただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"区民割引につきましても、今回の事業者の提案の中では、一部区民利用の割引が提案されていたり、あるいはイベントホールに限って言いますと、いろんな稼働の時期、稼働が高い時期だとか、そうじゃない時期というのがありますので、閑散期については大胆な割引を提案したりとか。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、これよりも安くなる可能性が結構あるということですよね。そうですよね。そうすると、その利用料というのは、この条例ではなくて、どういうところに、条例の使用料と、それから何で決まるのですかね。そうすると、指定管理者の利益というのは、どこから出てくるということになるのか、そしてまた、それはどれくらい見込まれているのか、そこら辺についてもお聞かせいただきたいと思います。","respondent":"あべ委員長、山崎ものづくり・経営支援課長","answer":"料金体系について、もう少しわかりやすくイメージをお伝えしたほうがいいのではないかなと思います。先ほどの説明だと、ちょっとわかりにくいかもしれません。利用料金につきましては、本年の第１回定例会で施設条例をご審議いただいた際に、区としての条例上の諸室の使用料を設定させていただいて、その段階で一つ一つの施設特性を踏まえた利用料金の設定について説明を申し上げました。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民割引というところでは、どんな形で出されてきたのか、きゅりあんと同じようなことで使えるような割引まで下げられるのかというあたりをさっきお聞きしたのと、さっきの指定管理料のところで、どういうふうにして指定管理者の利益が出てくるのかというあたりのところを先ほどちょっと質問したので、その点についてもお聞かせいただきたいと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"指定管理者の利益につきましては、もちろんその施設の料金設定、それから稼働率というものを計算して収支計画を出しておりますので、そこのところでそうした団体としての運営ですとか、そういうものを見込んでいただいて提案をいただいてやりとりしていますので。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、どの程度になるかというのは、この次の委員会にでも報告がされるんでしょうか。そういうことではないんですか。あっ、その超過分の一部か。一部なんですね。そして、独立採算制ということができれば、区としては基本指定管理料などは払わずに、この指定管理者が利用料金の中でやりくりをしていくと、基本的にはそういう考え方ということになるのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"やっぱり指定管理者の施設運営に、指定管理者がいろいろ頑張って稼働を上げたり、産業交流でさまざまな人を呼び込んで、その結果歳入が増えていくという一定程度のインセンティブの考え方も、指定管理者の導入のときに。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"料金設定もいろいろ協議をして、最終的には協定を結ぶということですけど、協定を結んで、じゃあこの料金になりましたというものについては、またこの委員会でご報告をいただくということで確認をさせていただきたいのと、最後にもう一つ、産業振興事業に関する提案書というのも出されているということなのですけど、ここのところの基本指針と事業内容を具体的に示してください。","respondent":"山崎ものづくり・経営支援課長","answer":"８月に予約が開始されますので、その前、７月の本委員会にもその内容について報告をする予定になっております。","id":"exchange-008"},{"speaker":"井上委員","kind":"確認","question":"それで、まずちょっとお聞きしたい、１個だけちょっと確認をしますけれども、この基準の中で、稼働率やそういう計算をして事業計画などを算定して、そのことによって区はシミュレーションができるんだというお話を今答弁されたので、この施設はどのぐらいの規模の指定管理料をもって運営をしようとしているのか、そこが今までの指定管理の福祉施設とか現状あったものとは全然違うし。","respondent":"山崎ものづくり・経営支援課長","answer":"平成２７年度につきましては、１０カ月ということですので、平準的な年度ではございませんので、例えば平成２８年度、平成２９年度というような平準化した年度で言いますと、歳入歳出で１億３,５００万円というようなところでシミュレーションをしています。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問","question":"指定管理料の委託料ということで、その金額なのか、利用料金制なので、区の負担ということでお答えいただいた金額ということでよろしいんでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"それで、収支がとれると。それと、区の指定管理料といいますのは、そこを補完する、例えば小破修繕の部分だとか、それをどっちが持つんだということにもよりますけれども、今のところのシミュレーションですと、区の指定管理料は４００万円です。","id":"exchange-010"},{"speaker":"井上委員","kind":"提案","question":"１５日は何曜日で、１９日は何曜日になっているのかちょっとお伺いしたいということと、あと品川ビジネスクラブについて少し情報をいただきたいというふうに思っているんですけれども、先ほど各事業者の概要のところで、現在は大崎一丁目６番４号ということでしたけれども、指定管理者になると、拠点が北品川五丁目のほうに移るということなのか、そういったところはどのように、その後。","respondent":"山崎ものづくり・経営支援課長","answer":"ですから、そういうところで支援の関係にあったのはもちろん事実ですけれども、指定管理者としての指定ということになりますと、施設の効率的な運営だとかということとは、そこは分けて今回はやってきていますので、経費の部分も団体としての財務諸表上のまとめと。","id":"exchange-011"},{"speaker":"井上委員","kind":"確認","question":"それからもう一つ、品川ビジネスクラブに関連して確認をしておきたいなというふうに思ったのは、今回議会に報告書として地方自治法第２４３条のということで、事業計画および収支予算書の資料をいただいているんですけれども、その中で、収支予算書のところで、平成２６年度の予算のところで、品川ビジネスクラブで事業活動収入、3)受取補助金、品川区という欄がありまして、区の当初予算書では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"先ほど１億３,５００万円というような規模のということで、そういったところを判断する上で不明なところということで質問させていただいたのですけれども、指定管理者の選定についての議論の中で、先ほど１５日、１９日、週末を挟むと本当にヒアリングをして選定するのに、どういう議論がされたのかという時間だけの問題ではないと、もちろん集中的にとおっしゃるかもしれないのですけれども。","respondent":"山崎ものづくり・経営支援課長","answer":"本施設の指定管理者の選定から議会に議決を諮る一番基本的なところが、区の指定管理者制度の活用に係る基本方針というものがありまして、そこでルールが明確化されております。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"なかなか見えにくいところでは、やはりなぜその３者が稼働率とか事業計画に対して区がシミュレーションできるので、それを出していただいて決めましたという答弁であるならば、そこがなぜそういうふうに、本当に稼働率の計算というのは事業ごとに違って、どこでイベントを打つかということが問われてきて、それを区が選定したんだろうというふうに思いますので、そこはやはり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"指定管理者ということで、議会が認めたということになるわけですから、その指定管理者がやっぱり適切なものであるのかどうなのかというところを議会が判断するわけですよ。だから、なぜこの指定管理者として判断したのかという、そこのところをしっかりと私は判断できるような、そういう資料というのは議会の中からも、ぜひ委員長のほうからも求めていただきたいなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回の選定で、ちょっとやっぱり気になるのが、両者の事業の継続性というものが、大丈夫だから判断をされたと思うんですけれども、先ほど説明の中で、解散、破産についての協定を両者でしているというふうに伺ったんですが、もし差し支えなければ、どのような協定になっているのかというのを教えていただきたいのと、あと、もし万一そういう事態が発生した場合には。","respondent":"山崎ものづくり・経営支援課長","answer":"協定書をそのまま読み上げるような形でよろしいでしょうか。管理者業務遂行中における構成員の破産、または解散に対する措置というところでございまして、協定で言いますと、第１６条ということになってあります。","id":"exchange-016"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、片方が単独でその事業を継続させるというのが基本という考え方だと思います。そして、もしこれが途中で１回途絶えてしまって、事業が途絶えてしまって、今答弁いただいた他の事業者を公募するとか、そういうようなことになるとすると、ブランクがあいてしまうということは、ある程度いたし方ないという考え方でおられるのか教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"共同事業体それぞれ、今言ったような事態にならない事業体について、まず選定をさせていただいたというのが前提ですけれども、そうした危機管理の状況ですとか対応につきましては。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"サービスの継続性というのが一番大切ですので、経営状況については当然いつも監視をされていると思いますけれども、ぜひともお願いしたいと思います。旗の台三丁目にあるというふうに出ているんですけれども、ここは場所としては知っているのですけれども、どうなっているのかなと気になったものですから教えていただければと思います。","respondent":"山崎ものづくり・経営支援課長","answer":"その後、区との関係もあって、区が５０％相当額を、昨年協定を結びまして、区としても支援を開始しているというような流れです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"私個人の意見なんですけれども、隣の大田区と比べて、個人の意見ですよ、大田区は商業よりもものづくり・工業に力を入れている。品川区は、ものづくり・工業よりも、商業に力を入れていると私は思っていました。今回、長年の夢であるこういう施設ができるということで、まず品川区のものづくりの担当課長としての意気込みを改めてお願いします。","respondent":"山崎ものづくり・経営支援課長","answer":"まちづくりの進捗に合わせてこういった拠点施設が双方で検討されてきた経緯もありまして、産業分野としますと、もう少し早く拠点が欲しいなということで、私の先輩課長あるいは先々代も含めて、そういう思いでずっと来ていました。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"負けないで品川区は頑張ってほしいというふうに期待して、これで終わるんじゃなくて、今日は指定管理者の指定の議案ですので、この共同事業体に決めたのは、品川区が求めたものというのがある。ここの６番に選考基準で四つ出ていますけれども、改めて品川区は選考で何を求めたのか。そして、求めた中で、一番高いのがこの共同事業体だったわけですよね。そこを具体的に、明確に答えていただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"先ほどの大田区もしかりですけれども、しっかり財団と組んで、行政としての部分とそれから財団法人としての立ち位置でもって、双方のそうした役割分担を適切に行うことで、もっと効果的に今までできなかった領域に対しての支援ができたり。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"代表者の石島氏という方がいらっしゃいますよね。私は共同体でいろんな方に接すると思うんですけれども、特にこの石島氏に私は期待をしているんですけれども、その辺に関しては、審査といいますか、そのときに個人のあれはあまり関係ないかもしれないんですけれども、氏に対しての思いといいますか、その辺はいかがでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"そうしたところの品川区内に立地するそういう資源、パートナーというところと、そこの学長として、あるいはクラブの理事長として公的な産業機関が担うべき責務ですとか、そうしたところに知見のある理事長ということで、区としても認識をしているということです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど収支のところで、平成２８年度、平成２９年度というところだと、１億３,５００万円ということでありましたけれども、これは稼働率としてはどの程度ということなのか、稼働率がどれくらいでペイできるという状況になっているのかということを一つお聞かせいただきたいのと、あとこの施設そのものが前の議事録を見ると、先ほど課長のほうからもお話がありましたけど。","respondent":"山崎ものづくり・経営支援課長","answer":"４階のインキュベーション施設につきましては、今回大小あわせて１６室ありまして、インキュベーションの施設はもう少し、現在の武蔵小山なり、西大井のインキュベーション施設は入れ替えで空くだけで、ほとんど１００％の稼働を誇っておりますので。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど委員長にぜひ資料をということで、それはご意見としてということでしたので、それが出ない、請求が今回できないということであれば、少し先ほど優位性の理由についてということでソフト面ということだったんですが、四つの事業体で何が違っていたのでこういうふうに選考しましたという比較を示していただく、口頭でやりとりをするしかありませんので、それを示していただいて。","respondent":"山崎ものづくり・経営支援課長","answer":"こちらのほうは、一定の実績はありますけれども、やっぱり収支が、運営経費が全体に高いというようなところ、それから、(1)の株式会社キャリアライズの共同事業体については、共同事業体だからこそ、それぞれ３社が連携していますので。","id":"exchange-023"},{"speaker":"井上委員","kind":"提案","question":"今そういう理由を伺った中で、徹底的に総事業費、先ほどの１億３,５００万円で区の負担がどのくらいかというところも多分比較の検討にはあったと思うので、そこについて数字をお示しいただければ、もう少し具体的に、なるほどというふうに思うんですけれども、2)、1)、3)の順に今答弁いただいたと思うんですけれども、そこを教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"2)の株式会社コンベンションリンケージにつきましては、年２,５００万円程度。それから、3)シグマアテンドサービス株式会社が年８,０００万円程度、品川ビジネスクラブのほうが４００万円程度です。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"反対です。この施設そのものの設置の条例のときにも共産党としては反対をしているのですけれども、大崎のこの地域に大企業ですとか、それから開発型中小企業、外資系企業、情報通信企業、これらの企業のために本当に高額な料金での施設をつくるということで、今回の指定管理者の提案の中でも、そこのところが区民のために使えるというふうな施設ではないということが改めて明らかになったと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"井上委員","kind":"意見","question":"しかし、意見として述べしますけれども、再三言っていますように、指定管理者を指定する情報提供は、今最後にお知らせいただいた、そういったものについてもう少し資料提供していただいて、余計な議論をするよりも、そういったところで判断しておく、議論ができるようにということで、そういう資料に基づいて正確に議論ができるということになれば、もっと違う発展的な審議ができると思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-02","title":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"２番の事業目的なんですけれども、周知拡大なんですけど、主語というか、何の周知拡大なのか教えていただけますか。","respondent":"米田商業・観光課長","answer":"周知拡大ですけれども、こちらについては、消費者センターの存在を知らない方もいらっしゃいますので消費者センターということと、それから悪質商法を中心とすると思いますけれども、今こういう消費者被害の情報があるんだよということについても。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"周知拡大していただくことは区民にとっていいことだと思うんですけど、その受け皿ですよね。消費者センターは。受け皿となる消費者センターが、周知拡大でこれ以上相談者が来たときの受け皿が区としてちゃんと整っているかということなんですけれども、その辺についてはいかがでしょうか。","respondent":"米田商業・観光課長","answer":"昨年度の消費生活相談は、件数としては少し上がってきてはおるんですけれども、現状のところ、対応がしきれないということではなく、むしろ体制によっては研修等に相談員を送り出すというような余地も、今のところはあるというふうに考えてあります。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"具体的に一つ教えていただきたいんですけれども、たしか２０代、３０代、４０代とかで、件数の内容といいますか、出ていると思ったんですけど、たしか２０代、３０代、４０代、５０代も入っていたかな、一番はアダルト関係でしたよね。その辺の対策等に関して、傾向に関して、傾向が先ですね。何でそれが全年代においてトップに来るのか、その辺についても今区がつかんでいるところを教えてください。","respondent":"米田商業・観光課長","answer":"特にお年を召した方は、いわゆるデジタルの関係に弱いということと、あと年の若い方はなかなか親御さんにも相談できないというような事態もありますので、比較的この分野はそういう年代の方からのお問い合わせが多く見られるということになっております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"周知拡大していただいて、多分来る方は、わらをもつかむ思いで来ると思いますので、相談員等を含めて、万全の体制でやっていただきたいと思いますけれども、最後にその辺について。","respondent":"米田商業・観光課長","answer":"それだけの今体制は整っていると思いますので、こういう活性化交付金等を通じてさらなる充実を図っていく、このように考えてあります。","id":"exchange-030"},{"speaker":"木村委員","kind":"質問","question":"歳入で４２９万１,０００円となっていますけど、これは品川区のほうが歳出などで金額を請求するわけですか。ちょっとわからないので教えてください。","respondent":"米田商業・観光課長","answer":"その都道府県の内示に対して都道府県が各区市町村からの要望を踏まえた上で、区市町村のほうに配分するというようなことになっておりまして、品川区のほうで今年度はこの金額を要求したところ、丸々認めていただいた、そういうようなことです。","id":"exchange-031"},{"speaker":"木村委員","kind":"意見","question":"そんなにしょっちゅう壊れるようなものではないと思うんですけれども、何年に１回かとかということでやっているのかどうか、まさか毎年同じようなものを出しているわけじゃないですよね。","respondent":"米田商業・観光課長","answer":"消費者行政活性化交付金自体が平成２１年度から実施されておりまして、当初３年で終わるというようなことでお話をいただいています。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この消費者行政活性化というのがなぜこういうふうな形で取り組まれたのかというのを、国のほうを見ますと、消費生活相談の複雑化、高度化が進む中で、相談の増加が見込まれる、そこに対して強化が必要だというふうなことで、幾らというふうなことで国のほうとしても予算が組まれているというふうなことで書かれているんですけど、品川区としては、ここら辺のところの相談の状況というのが。","respondent":"米田商業・観光課長","answer":"その後、一応終わるという予定だったので、数億円というような積み上げがあった中では、平成２４年度の補正では約６０億円の、最終的にですが、それもいろいろ数字が動いていたんですが、最終的には６０億円の交付があるというようなことでした。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"国全体の何百億円というのは、この資料にも書かれているのでわかるんですけど、品川区に今までどれぐらい来ていたのかということと、相談員の体制、人数がどれぐらいの体制でやっているのか、その２点だけお願いします。","respondent":"米田商業・観光課長","answer":"これも年によって異なりますが、累計で言いますと、今回お認めいただくとすると、４２９万円を含めまして、２,３０４万円余の交付をいただけることになってあります。相談員といたしましては、現状６名体制で月１２日というようなことで、交代で勤務ということになってあります。","id":"exchange-034"},{"speaker":"本多委員","kind":"質問","question":"消費者センターの充実というところでお聞きするんですけども、例えば、こういう都の補助金とかがこの先もレベルアップというか充実していった場合、区の消費者センターは今１カ所じゃないですか。それをもっと、拠点を細やかに、出張所を配備したり、そういう発想というのはないのでしょうか。","respondent":"米田商業・観光課長","answer":"現状、１カ所でやらせていただいておりますが、実際、消費者センターの職員が出かけていって相談に乗るということはほとんどできませんので、逆に言うと現場に出向く、ヘルパーとかあるいは町会の方々、こういう方々に変わった兆候なり、これは危ないなという兆候があれば。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほどの相談員の体制なんですけど、６名で月１２日というのは、１カ月につき１２日勤務の方が６名いるという考え方なんですか。１日体制というのは、大体３名程度と、そういう感じでしょうか。","respondent":"米田商業・観光課長","answer":"今大体ですが、１日に２人から３人の体制ということになっています。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"もう一つは、予算の歳出の1)、2)ですが、やっぱりハード的なものよりも、こういったものが、金額的にも少ないんですが、研修の充実とか、あまりそういう研修に出ると、そこにいる人が少なくなっちゃって難しい部分はあるのですけど、ちょっとバランス的に、本当はこういった研修をもっと強化してほしいなというふうに、この数字だけを見れば思うのですけど、その辺の検討というか。","respondent":"米田商業・観光課長","answer":"自分もいろいろと関係している人間に、「これを見て、どう思うか」というようなことは聞いておりますが、今後、区市町村の消費者センターの会議の中で、今議題として学生向けのパンフレットについて相互に比較し合おうというような議題が出ていると聞いておりますので。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"井上委員","kind":"提案","question":"正副でまとめていただきまして、ありがとうあります。ここのところで二つ提案をさせていただいたんですけれども、町会とか、この間も相談員とかありまして、その他の部分でもこちらの提案とか、そういったもので柔軟に入れていただければというふうに思っていますので、そこら辺の委員会の進行のほうはお願いしたいということで、少し事前にお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"前年度、この辺を軽くというか、やっていなかったかな。観光とか商業、中小企業、やっていなかったかなという思いが、やっていないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"じゃあ改めて、やっていて、この辺を選んだあれを、委員長、副委員長、教えていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところで言えば、時間も案外ゆとりが、ちょっと私、建設委員会とか厚生委員会とか時間がかなり長く、４時過ぎまでかかるということが多かったんですけど、そういうところで言うと、ちょっと時間的なゆとりがあるということであれば、私はやっぱり町会の支援というところも入れていただいて、もう１項目増やしていただけないか、いただけたらうれしいなと思うんですけど、無理ですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/209022?Template=document&Id=2698#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":41329,"voices":135}},{"id":"h26-20140630-7","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"厚生委員会","time":"午前１０時００分～午後０時２８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)の第４１号議案、品川区立特別養護老人ホーム施設使用条例の一部を改正する条例","agenda":"はじめに、(1)の第４１号議案、品川区立特別養護老人ホーム施設使用条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"１点だけですけれども、屋外運動場の夜間使用はここに載っていないので、多分やらないということになると思うのですけれども、以前の杜松小学校のときは、夜間の時間もグラウンドを使っていたグループがいたかと思うのですけれど、その辺の方たちにももちろん納得していただいた上でのことだと思うのですけれど、その辺の経緯をちょっと教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"ですので、基本的に夜間使用という概念はこちらには適用しないのですけれども、運用として、そういった暗くなった中でもある程度防犯灯の光が届く中での使用ということは、これまでもやっておりましたので。","id":"exchange-001"},{"speaker":"たけうち委員","kind":"質問","question":"その上で時間帯なのですけれど、前はたしか９時ぐらいまで使っていたと思うのですが、中に一部、やはり高齢者施設を併設なので、ちょっと時間帯を８時ぐらいに前倒しするような、だから正式なここに出てこない、今の運用の面だと思うのですけれども、その辺はもしわかればで結構ですけれど、ちょっと時間帯は、所管が違うかもしれないですけれど、前倒しとかされているのかどうか、わかれば教えてください。","respondent":"大串福祉計画課長","answer":"９時、９時半というお声も確かにあるのですけれども、なかなかその時間帯までになってしまいますと、高齢者の方の生活時間帯とどうしてもかぶってしまうところもありますので、その辺は運用の範囲内ということにはなるのですけれども、利用される皆さんとお話をしながら。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"所管が違うのかもしれませんけれども、わかるところで結構なのですが、交流拠点の運営、できることはわかっているのですけれど、例えば八潮は違う団体でたしか運営していた記憶があるのだけれども、この地域交流拠点をこれからどういうふうに運営していくのかという構想なり、わかっていることがあれば教えてください。","respondent":"大串福祉計画課長","answer":"基本的には今までの杜松小学校と変わらない、杜松小学校時代におきましては、副校長先生が大体窓口になって、施設の運営の調整をされていたかと思うのですが、今回それにつきましては、こちらの特別養護老人ホームを運営する事業者。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"だから、それを今おっしゃったような組織でうまく吸収して、対処していただく仕組みをつくってくださいますかという確認ですが、答弁をお願いします。","respondent":"大串福祉計画課長","answer":"そうした声を受けとめながら、今のところ懇談会という名称になっておりますけれども、地域の皆様の声を聞く場を設けて、区あるいは運営事業者、この三者で、この施設がよりよい形で地域の皆様に親しまれるような、こういったものを考えながらやっていきたいと考えております。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"学校が新たな施設にリニューアルされていくということですけれども、ここでちょっと気になってくるのが利用料のところですけれども、これも今までどおりという形で考えていいのでしょうか。","respondent":"大串福祉計画課長","answer":"新しくできます地域交流拠点については、以前教室だったところを改修して、先ほど申し上げたような会議あるいは趣味のサークル活動に使っていただく、もしくは防音設備を整えた形でカラオケのしつらえも行う予定ですので、そういった形で。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この新たな施設のところの、会合や趣味活動とか、各種会議、介護予防事業とか、カラオケなどということも出ていましたけれども、今まである施設で考えると、地域センターとかシルバーセンターみたいな感じで考えていいのでしょうか。","respondent":"大串福祉計画課長","answer":"はい、使用料に関しましては既存の施設と同じ考え方を踏まえて、こういった金額を算定しています。","id":"exchange-006"}]},{"id":"topic-02","title":"の第４２号議案、品川区立高齢者住宅条例の一部を改正する条例","agenda":"の第４２号議案、品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"今回引き下げになって、利用者にとっては非常にありがたいことだと思うのですけれど、この引き下げていく考え方といいますか、この裏面にほかの高齢者住宅もあるのですけれど、ほかのところも満期が来た場合、やはり経年劣化とかそういうのを踏まえて、区としては引き下げを一応求めていくという姿勢でいいのかどうか、そこをちょっと教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして今後の考え方につきましても、同様のことで進めさせていただきたいと考えています。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"単純に、ここだけが今回の改定で下がっていますよね、グレースマンションだけ月額が下がっています。その理由は、今、経年劣化ということがあったのですけれども、そのほかに何か理由があると思うのですけれど、教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"経年劣化という耐用年数等につきましても、いろいろ考えた中で、やはり入居者にとって住みやすいかどうかという部分、小規模な改修につきましては、区のほうといたしましても家主さんのほうにお願いいたしまして、住みやすさ、快適性。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"その理由はわかるところですが、そうするとなぜここだけなのかと、ほかのところもありますよね、近傍家賃との差というならば。ことさらグレースマンションの地域だけ近傍家賃が下がったとは考えにくいんですね。だからそこには何らかの理由があったのかと推測するのですけれど、改めて近傍家賃だけの理由ではないと思うので、この場で教えていただけるようでありましたら、ご答弁をお願いいたします。","respondent":"白鳥高齢者いきがい課長","answer":"これから、賃貸借契約で２０年間ということで今後満了となる借上型の住宅につきましては、やはり大きな差がない限り、これは２年に一度、協議する機会も設けてありますので、その中で大きな変動がある、社会経済ですとか、不動産価格の下落等。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今回のこのグレースマンションは、前回の報告があったとき、個人の管理者から株式会社カーマトラストに変更したということで、この中でほかに株式会社でやられているところはあるのか。株式会社だから引き下げることができたということが背景にあるのかというのを、ちょっとお聞かせください。","respondent":"白鳥高齢者いきがい課長","answer":"他の借上型住宅で法人、株式会社を有している貸主はございません。株式会社であるから引き下げたということではございませんので、先ほども申し上げましたとおり、これからその時々によりまして、考え方、不動産の動向も見ながら、きちんと精査をしていきたいと考えています。","id":"exchange-010"},{"speaker":"向委員","kind":"質問","question":"１点だけ。先ほど小規模改修は家主の方に依頼をされているというお話だったのですけれども、例えば水回りをちょっと、経年劣化とか年々いろいろな、最近、高齢者の方だとＩＨに改修されたりとかも多いですし、具体的にどういう小規模改修を家主の方と適宜されているのか、それだけ簡単に教えていただけますか。","respondent":"白鳥高齢者いきがい課長","answer":"例えばトイレの詰まりですとか、その原因が何かということをきちんと貸主と、あるいは入居者の方と相談させていただき、当初のリフォーム等につきましては区のほうで行いますけれども、それ以外のものにつきましては、貸主の責任において改修をしていただいているところです。","id":"exchange-011"},{"speaker":"向委員","kind":"意見","question":"高齢者住宅ということでもあるので、家賃は下がったけれども古いままの設備がそのまま残っていて、だから家賃が下がったということになると、住みにくいままになっていって、こういう契約はたしか２０年ごとに、前回のパレスガルとかメゾン琴秋もそういうので見直しをされていると思うので、リフォーム等は適宜してくださっているということだったので、今後もそのあたりは、家賃改定もしつつ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]},{"id":"topic-03","title":"の第４３号議案、品川区立児童学園条例の一部を改正する条例","agenda":"の第４３号議案、品川区立児童学園条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"分室は旧戸越ひまわり保育園のところにできて、新たな相談窓口が増えるのだなというのがイメージできるのですけれど、放課後等デイサービス事業と保育所等訪問支援事業というのが、どこでどんなふうに、どんな中身で行われるものなのか、ちょっとわからないので教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"あわせまして、保育所等訪問支援事業につきましては、昨年度１２月ごろからモデル実施をいたしました。モデル実施の結果、今年度から本格的に事業展開しようということで、こちらの条例に載せさせていただければと考えています。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この保育所等訪問支援事業のほうの中身を、もうちょっと詳しく教えていただきたいのですが。","respondent":"中山障害者福祉課長","answer":"そこで国のほうの新しい児童福祉法の中では、放課後等デイサービスという新しい事業形態を設けまして、例えば保育園にいながらにして、そのお子さんに対して、心理職ですとか児童福祉司のような専門職が、大体月に２回程度訪問して、そのお子さんの療育環境を。","id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"このモデル事業としてやられていたというのは、全保育園で行ったのか、何カ所かモデルで決めてやったのか。それで今回実施ということになったときは、全部の保育園でやるのでしょうか。","respondent":"中山障害者福祉課長","answer":"そのお子さんの保育所等訪問支援事業をやりながら、この間その効果検証と、ＰＲにも努めているところですので、本格実施に当たりましては、もちろん全障害児のお子さんが対象ということになってきますので、保育園あるいは幼稚園を固定するものではございません。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけれども、現況やっている品川区の子供発達相談室とCompass事業が、それぞれ本園のほうでは子供発達相談室が定員２０名で、時間が１０時から午後２時３０分、集団指導、個別指導、それからCompassも定員１０名とそれぞれ報告があるのですけれども、分園についてはこういう時間なり定員なり、規模はどうなのでしょうか。お願いします。","respondent":"中山障害者福祉課長","answer":"今回旧戸越ひまわり保育園の跡施設につくるサテライトルームにつきましては、相談を行う施設になります。ですので、特段時間帯が、例えば１０時からというふうな形で決まっているものではありません。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"確認","question":"気になったのは、定員が決まっていないというのは、それから時間も９時から夕方と雑駁な感じがしますので、９時から何時までなのでしょうかということの確認と、１００名とか来ることはないでしょうけれども、本園がどうも２０名と決まっているものですから、サテライトのほうでもやはり、品川区ではこのぐらいの人数と多分把握していると思うので、その数字を教えてください。","respondent":"中山障害者福祉課長","answer":"現在本園のほうで全て相談を受けているのですけれども、やはり荏原地区に相談の拠点をもう１カ所増やしたほうが、地域で身近なところで相談ができるのではないかということで、今回サテライトルームとして開設するものです。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"１点だけ。９時から１７時までは月曜日から金曜日までだと思うのですけれど、相談する方がそれだけいらっしゃるのかなと。来る方が。それから月曜日から金曜日までなのでしょうか。その確認もあわせてお願いします。","respondent":"中山障害者福祉課長","answer":"残りの２日間というのをどういう活用をするかというところになりますが、この間いろいろともう少し、例えばダウン症の勉強会をしたいとか、親のかかわり方をどうしたらいいんだろうかといったようなご相談をいただいていますので、区の単独事業としてそういったお声を聞きながら。","id":"exchange-018"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと確認方々教えてほしいのですが、運営方法のところに分室の相談事業について業務委託をするということで、最初の前提のところで、大変そういう相談がとても多いというお話でありましたけれども、具体的に業務委託というのはどういう方たちというか、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ですので相談の業務委託ということでは、本園の受付から、現場での実際の相談にかかわっていただく、それから個別相談だけではなく、ある程度のグループの相談というのもやっていこうと考えていますので、そういった中での事業委託ということになってまいります。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"確認","question":"確認ですけれども、若竹大寿会のパンフレットを開いていただくと、法人組織図というのがあって、そこに横浜市、東京都品川区に２１拠点を展開する社会福祉法人とあるのですけれども、その中に品川区立杜松小学校跡高齢者福祉施設とあるのですけれども、これは今、現状で若竹大寿会がやっているのでしょうか、という確認をお願いします。","respondent":"永尾高齢者福祉課長","answer":"ただ、これまでの経過からすると、区とともに設計の段階から、また運営の方法等もこれまで協議をしているところであり、また地元での説明会についても同席をしているという状況を踏まえ、このパンフレットに書いてあることにつきましては。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"提案","question":"選定した経過とか内容については、当然皆さんが選定されたわけですから、そのことについて意見するつもりはないのですけれども、正式には今回の区議会に条例が提案されて、それでここに書いてあるように１０月にその文書を打って、正式に指定管理が成立すると私は判断するのです。","respondent":"永尾高齢者福祉課長","answer":"若竹大寿会につきましては、その辺の行政の仕組みとかそういうところがまだ十分理解されていなかったのかと思いますので、こういうことのないように、こちらのほうでも注意をしていきたいと考えています。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"あまりこのことでいろいろ言うつもりはないのですけれども、ただ、これから条例を審査するという前から、既に若竹大寿会が受託されているかのような、受託するのだろうけれども、やはりそういうことについては、品川区はちょっと気を使ってほしいと思います。この選考に当たっては、内部で審査したというのですけれど、参考までに、若竹大寿会のほか、幾つか法人があった中で選んだのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"平成２３年度に公募を行いました。そのときには、若竹大寿会を含めて３者が応募に出てきておりまして、ヒアリングを行い、選定委員会を行い、運営予定事業者を決定したという経緯です。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"今回は、そうすると３者の中から選んだということでよろしいですか。","respondent":"永尾高齢者福祉課長","answer":"平成２３年度は３者でございましたけれども、今回につきましては、そのときに選定し、その後の状況の変化等で、この若竹大寿会に問題がないかというところを含めた審査を行い、決定したというところで、今回の指定管理に当たって公募は特にしてございません。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問","question":"平成２３年度に３者をヒアリングした、これはわかりました。それが今回どうつながっていくのですか。そういうことではなくて、平成２３年度にヒアリングしたのは、どういう事業者に対してヒアリングされたのでしょうかということが１点。その中で若竹大寿会が選ばれたと思うのですけれども、それが今回の指定管理者とどうつながっていくのでしょうかということの説明を、改めてお願いします。","respondent":"永尾高齢者福祉課長","answer":"高齢者の福祉施設につきましては、事業者と実際の建物の設計というのは非常に密接な関係になってございまして、建物だけ先につくり、そこから事業者を選定するということになりますと、運営の内容の部分を考えたところで、いろいろな不備が出てきてしまうということがありまして。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"確認","question":"今の伊藤委員のご質問と関連しているのですけれど、今、ご説明いただいた流れは理解しているのですけれど、そうすると確認ですが、この平成２３年の公募３者で、運営予定事業者が選定されたときは、僕は厚生委員でなかったのであれですけれど、委員会でご報告という形なのですよね、恐らく。","respondent":"永尾高齢者福祉課長","answer":"平成２３年度には、公募を始める前、公募をした結果、選定をした結果、全て厚生委員会のほうでご報告しています。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"反対ありきでない、もちろん賛成なのですけれども。そこが今後、恐らく今、平塚橋の特養ホームも公募中ですか、もう締め切ったのかどうか、あれですけれど、そうするとそれも同じような流れですよね。そこをちょっと、ここと直接関係ないですけれど、ちょっとご説明いただいておいたほうがいいかなと。","respondent":"永尾高齢者福祉課長","answer":"過去でいえば、例えば八潮南も同じ方法でやっております。それで今、こちらの杜松小学校跡のほかに、平塚橋会館跡、上大崎の旧みやこ荘跡、それと現在、北品川に予定されているところ、それにつきましても同じような方法で進んでいるところです。","id":"exchange-026"},{"speaker":"たけうち委員","kind":"意見","question":"そうすると、我々はその都度厚生委員会等で報告いただいたときに、例えば何かこれはということがあれば、そこで意見を言わせていただくということになるわけですね。そこで議会が関与していくということで理解すればいいということですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"何度もすみません。ただ、確認したいところがありましたので。先ほどの若竹大寿会のパンフレットの中で、品川区立杜松小学校跡高齢者福祉施設、開所予定という表があります。これはこれでいいんですけれども、でも、そこに人数も、例えば地域密着型特別養護老人ホーム２９名、認知症対応型共同生活介護１８名等々書いていますよね。ところが、議会には設計図もまだ示されていないですよね。","respondent":"永尾高齢者福祉課長","answer":"そのほか、実は６月補正がございまして、工事費の上昇ということで補正をかけていたり、あと厚生委員会でもやっていたりというところで、その中で委員の皆様については、図面等もお見せしながら説明してきたような経過があります。","id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この地域密着型多機能ホームと特別養護老人ホームと一緒になっているのですけれど、この中に戸越台第二在宅介護支援センター、ヘルパーステーションも入ってくるという、以前の資料で見たのですけれども、ここは現在、三徳会が、中小企業センターの中でやられているところだと思うのですけれども、特別養護老人ホームで指定管理というか、母体が違う在支が入っているということって、今までありましたか。","respondent":"永尾高齢者福祉課長","answer":"同じ建物の中というところは、現在はないのですけれども、ただこちらの移転に当たっては、もう既に若竹大寿会と戸越台第二在宅介護支援センターと一緒に協議をしながら、ずっと進めてきているところがあり、お互いに十分な連携がとれるかと考えております。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"新たな指定管理者、今まで品川区でやってきていなかったというところでもちょっと不安だなと思ったのでお伺いしたのですけれども、十分連携はとれると。この間も協議をしてきているということですので、見守っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問","question":"今、社会福祉法人がいわゆる地域貢献みたいなことが新聞等にも大分取り上げられていまして、いろいろ今、品川区内で既にある社会福祉法人もいろいろと取り組まれていると思うのですけれど、この新しい今度の若竹大寿会は、そういうことも今、区との間で何かお話しされているのかどうか。何かもしあれば、教えてほしいと思います。","respondent":"永尾高齢者福祉課長","answer":"品川区のいろいろな施設の状況、地域の民生委員との交流、それももう既に少しずつ始めているところもありますので、これから区もその間に立ちながら、適切な運営になるよう取り組んでいきたいと考えております。","id":"exchange-031"}]},{"id":"topic-04","title":"の第３５号議案、平成２６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の第３５号議案、平成２６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"１４ページ、１５ページの平塚橋シルバーセンターと、平塚橋会館跡高齢者福祉施設整備費の中で、増えた中の内訳で、先ほど賃金・物価水準上昇ということだったので、賃金の部分といわゆる材料費の部分の金額が、もしわかれば教えてもらえますか。","respondent":"大串福祉計画課長","answer":"その中では、例えば骨材、いわゆる砂利等といったものが１０.２％増、また普通鋼材、鉄です、こちらについては１０.５％増、それから生コンクリートについても２.５％増、架設関係の整備品についても５.９％増といったところで。","id":"exchange-032"},{"speaker":"向委員","kind":"確認","question":"私からは、風しんのほうでちょっとお尋ねしたいのですけれども、抗体検査、そしてそこからの予防接種ということに形態が変わりましたが、４月と５月、もう多分医師会のほうからも数が来ていると思うのですが、品川区医師会のほうと荏原医師会のほうで、それぞれ抗体検査を受けた人の数と、そこから予防接種に移った数を確認させていただければと思うのですけれども、数字は出ますでしょうか。","respondent":"佐藤品川区保健所保健予防課長","answer":"品川区医師会は、４月、５月の抗体検査の数が１２２です。荏原医師会のほうで抗体検査を行いました数が７３です。予防接種のほうは、品川区医師会で５７、荏原医師会で２３です。","id":"exchange-033"},{"speaker":"向委員","kind":"質問","question":"この中の抗体検査は、品川区医師会のほうは１２２件中、予防接種に進んだ人は５７ということで、約半数は何かしら、抗体値が不十分だったとか、まだ２ヶ月ですけれども、今見るとちょっと驚いてはいるんですけれども、そのあたりについてのお考えを教えていただけますか。","respondent":"佐藤品川区保健所保健予防課長","answer":"３０代、４０代を中心の国の統計でも、およそ１５％ぐらいの方が抗体を持たないということが言われておりますので、その中ではかなり高い数字というふうに認識しております。","id":"exchange-034"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の質問の続きなのですけれども、まず風しんの抗体の検査と、ＭＲワクチンをするときの費用と、風しんの抗体を省いてＭＲワクチンだけをやったときの費用と、そのコストはどうなっているのでしょうか。要するに品川区のほうで出すコストは、１回につきどのぐらいなのでしょうか。","respondent":"佐藤品川区保健所保健予防課長","answer":"抗体検査のほうは、契約単価ですが、およそ６,０００円程度、予防接種のほうは１万円程度となっております。合わせますと、抗体検査から予防接種に進んだ方については、１万６,０００円ぐらいということになります。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、ワクチンだけの場合は１万円ということでよろしいですね。そうすると、抗体検査をしてワクチンをすると、費用が大体１.６倍か１.７倍ぐらいかかるわけですよね。ワクチンだけの場合は、その費用のほうが少ないにもかかわらず、厚生労働省は３月から４月にかけて、抗体検査をしてからワクチンという形で方針を決めたみたいなのですけれど、それはどういう理由なのでしょうか。","respondent":"佐藤品川区保健所保健予防課長","answer":"昨年度は緊急対策ということでアウトブレークでございましたので、まずは抗体検査をせずに、雑な言い方ですがみんな打ってしまえということで、積極的に予防接種を進めたところです。","id":"exchange-036"},{"speaker":"鈴木（博）委員","kind":"質問","question":"要するに、利用者というか希望者の利便性が非常に悪くなった。それなら、ＭＲワクチンをやったとしても、それでマイナスが何かあるでしょうか。だから抗体が上がるわけですから、そういうことを考えると、品川区の場合は少し弾力的に抗体検査をある程度融通して、希望者にはＭＲワクチンを打つというような積極的な対策というのは、非常に進んだ対策ではないかと思うのですけれど、いかがでしょうか。","respondent":"佐藤品川区保健所保健予防課長","answer":"委員ご指摘のように、本人の利便性という点については確かに落ちるのかなというふうには思われます。ですが、今回国の方針のもとに、２分の１の助成ということで抗体検査が進んでおりますので、品川区としては国の助成、要綱に基づいた方法で制度設計をしたいと思います。","id":"exchange-037"},{"speaker":"鈴木（博）委員","kind":"質問","question":"抗体の検査をしただけで、陰性でもワクチンをしに来ない人もいるのです。やはり希望者の方もいろいろ大変で、おまけに、金額は半額になるといっても、ワクチンするだけの費用ももともと半分強ですから、やはりその辺、実際に風しんが起きたら先天性風しん症候群というのは大変なことなので、やはりその辺りは患者のことも考えて対策も考えていただければというのは、これは希望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１５ページの平塚橋のほうですけれども、上の段のほうは高齢者福祉施設運営費追加分で、これからシルバーセンターの整備費が出ている、運営費で整備費を。下は整備費で整備費として出ているので、これが何で運営費から整備費が出るのか、ちょっと文字的な疑問を教えてください。","respondent":"大串福祉計画課長","answer":"こちらにつきましては、ご案内のように西中延区営住宅の建替えに伴って、こういった床面積が確保できたことに伴っての、特別養護老人ホームの整備です。新設の施設をつくるということで、建設費というところで分けていると、こういった流れになっております。","id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今、平塚橋の土地は更地になっていますよね。そこに全てが新築されるのかなと思っていたので、改修とか改築とかとはまた違うだろうなと思うので、それでも運営費から出せるという仕組みになっているということですか。","respondent":"大串福祉計画課長","answer":"翻って、特別養護老人ホームについては、なかったものができるですので、そのような形で捉えていただければよろしいかと思います。","id":"exchange-040"}]},{"id":"topic-05","title":"の議員提出第１号議案、品川区高齢者医療入院時負担軽減支援金の支給に関する条例","agenda":"の議員提出第１号議案、品川区高齢者医療入院時負担軽減支援金の支給に関する条例","exchanges":[{"speaker":"石田（ち）副委員長","kind":"提案","question":"１、提案理由。こんなときだからこそ、高齢者の痛みを少しでも和らげるための対策が、自治体に求められています。今回の条例は、高齢者の入院時の負担を少しでも軽減するために提案するものです。そして２、条例内容です。３、の予算として、年間入院件数が平成２４年度で２万６,５８５件、広域連合のレセプトのほうで確認ができましたので、年間予算額はちょっと余裕を持って２億７,０００万円です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"確認","question":"何点か確認したいのでお聞かせください。予算のところで２億７,０００万円なのですけれど、周知の方法。品川区内の７５歳以上の方々、大体今は３万６,０００人前後いると思うのですけれど、こういう方々に対する周知の方法をどうお考えになっているかということと、それに対する予算、事務費等はどうお考えになっているのでしょうかということを、まずお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"周知のほうは、入院された方が対象ですので、入院した際に病院から、ですから病院にも周知をしていくと。多くの方が医療費、入院費で１万円を超えていくので、領収書を何枚もというよりは、一度の入院費で１万円を超えてくるので、特に新たな事務員の配置とか手間の部分では、新たなものはなくてもやっていけると考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"伊藤委員","kind":"質問","question":"事務員の配置がなくてやっていけるとおっしゃるのですけれども、病院への周知を誰がするかとか、周知の印刷物をどうつくるかとか、病院からの入院する情報をどう吸い上げていくかということについては、どうお考えですか。当然そのことだって事務費がかかると思うのですが、お考えをお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"既に実施している区に聞いたところ、こういった周知も多少はあったのですけれども、なかなか利用が伸びないので、区も工夫してチラシを配ったりとされたそうですけれども、そういったところでの手間は、普段の仕事の中でできる内容でしたということですので、品川区でも同様にやっていけるのではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"提案","question":"地方自治法上の確認を少しさせてください。ということは、品川区に当てはめてみれば、会計管理者は品川区長の命令でなければ支出をすることはできない。となると、提案者に確認したいのは、この条例を提出するに当たって濱野区長の了承を得ていたのでしょうかというのが一点と、地方自治法を見れば、その命令を濱野区長が会計管理者にする可能性があるかということについて、お聞かせください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"事前に区長に説明をということで、お話を持ちかけましたところ、副区長と企画部長に対応していただきまして、申し伝えますということで、この間、今回を含めて５回目の条例提案、同じ内容の条例提案ですけれども、内容は一応読み上げましたけれども、「同じですね」ということで、向こうにも受け取っていただけたと私たちは思っていますし、この条例が可決すれば、その後。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"提案","question":"そのときは相当品川区の職員に協力をしていただいて、綿密な打ち合わせをさせていただいて、当然区長の了承も得た上で、条例提案しました。どれだけ濱野健区長が、今回の共産党の提案を受けとめて、そして財政的な負担を理解しているかということは、非常に見えないです。だからそのことについて、説明がありましたらもう一度お聞かせいただきたい。そのことについてあわせて説明をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そして区長が拒否をしていくと、それはできる権利もあるわけですから、それは起きてしまえば起きるのだろうなということでしょうけれども、この場で議決していただいた後の話ですので、現在においては、これを議決していただきたいというのを議案提出者の願いとしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"伊藤委員","kind":"質問","question":"最後に、この２億７,０００万円、事務費も含めて３億円近いお金をどう捻出される予定ですか。そのことをお聞かせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今年度に関しては、１２月施行で３月までということで９,０００万円、そして年間ベースでは２億７,０００円というふうに見ていますけれども、区の当初予算を見ていても、財調の積立金等を見ていても、積み増しが毎年増えているというところで、その分で十分対応できていくと、区財政を圧迫するものではないというふうに考えています。今回の補正予算などを見ても、繰越金というところもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"伊藤委員","kind":"意見","question":"まとめますけれど、ご説明をいろいろいただきましたけれども、約３億円というとても大きな金額を出すに当たっては、基金があるからいいというのでは納得できないところがあります。約３億円近いお金を出すわけだから、それは相当行政側と詰めていかなければいけない。そういうさまざまな不備があるということだけ指摘させていただいて、質疑を終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと基本的なことを教えていただきたいと思います。この予算のところに年間入院件数、２万６,５８５件というのは、何回も入院していらっしゃる、あくまでも１人は１回という、どういうカウントの仕方なのかということ。それからもう一つ、条例の内容ですけれども、第２条の対象者、所得制限なしということは、所得の多い少ない関係なくという意味なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"それから所得制限は、私たち提案理由を本会議の中でも言ってきましたけれども、社会保障は誰にも公平であるべきだというふうに考えています。ですので、所得制限は設けていません。本来、医療費は無料であるべきと私たち共産党は考えていますので、お金のあるなしで差をつけるというものではないと考えて、所得制限をつけませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"山元委員","kind":"意見","question":"先ほどの入院件数に関して、１人の方が２回、３回と入院を繰り返せば２件、３件ということは、この対象となる件数は、ある意味では平等でないというか、変な言い方ですが、１年間ずっと入院している人に関しては１件とカウントする、だけれどもたまたま３ヶ月、４ヶ月で退院なさって、また再発なさってということになると、考え方としてはどうなのでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"この件数のところで、何回も繰り返し同じ方が件数を増やしているというのは、さほど多くないと聞いていましたので、これからも入院件数はさらに増えていくだろうと予測もされている中ですので、こういった件数に合わせて、ちょっと余裕を持った予算をつけました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"山元委員","kind":"提案","question":"そうすると、ご存じのようにどんどん高齢化していくということは、もっと人数的にも増えていくというと、その辺の財源が、結局は負担が大きくなるだろうなと思うのですが、その辺の先の見通しというか、ある程度計算なさってこういうご提案をしているのだろうけれども、その辺はどうでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"年間３億円というのは、私たちは問題ないと考えています。ほかの区は入院時の支援金というものを、紙おむつ代ですけれども、こういう形で出していると。私も日の出町など視察に行きましたけれども、こういった支援こそがこれからの高齢者の健康づくり、そしてさらには医療費を下げていくということにつながっていくと、その第一歩と考えていますので、先行きも見た中で、約３億円は問題ないと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"１年間通して入院していた場合ということですので、１２ヶ月。入院というのは１日で帰ることはないので１泊２日ですよね。そうすると１回の入院でも、かかった部分に実費相当額で支給をしていくので、それで退院されて、また入院されれば……。というふうに考えているのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"年間１２万円という上限ではなく、１月１万円という上限ですので、１月にかかってくる……、そうですね、１月の間に２回入院すれば、１万円です。１月の間に１回入院、でも、退院してもう１回入院となっても、１月の限度額は１万円なので、１万円です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"すみません、ちょっと私の確認不足で、前回とは変わっていないので、そういうことになってくると思います。申し訳ないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"確認","question":"ご説明いただきましたけれども、仮にこの条例が制定されたとしても、約３億円近い財源の支出の方法が明確でないということがわかりました。恐らく濱野区長もこのことに同意されていないということも確認されましたので、結果として議会としては、こういう条例を出すこと自体が私はいけないと思っていますので、反対とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"たけうち委員","kind":"意見","question":"理由としてはさまざまありますけれども、やはり高齢者のさまざまな施策を総合的に推進していく中で、考えていくことが必要だろうということと、またこの所得制限なしというところも、いろいろな考え方はあると思うのですけれど、やはり７５歳以上の方でもかなり裕福な方もいれば、また比較的若い方でもなかなか大変な方がいるという中で、所得制限なしというのもちょっと引っかかるところもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"向委員","kind":"質問","question":"他の会派からも質問が出ましたし、今、お考えも出ましたけれども、支出のそもそも予算の額をどこから捻出するのかというところで、大変疑問が湧いているのと、やはり公平性の観点から所得制限について、例えばこれが非課税世帯を除くとかそういうことは何も特になく、いろいろな所得の方がいらっしゃる、もちろん苦しい方もいらっしゃるのも存じていますけれども、そのあたりが気になるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"ぜひ通していただきたいという思いで提案はさせていただいたのですけれども、議員は議会に議案を提出することができるという権利を行使し、今回の議案の提出をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この間ずっと答弁していただいていることと同じ内容だったのですけれども、ニーズの変化や保険料に影響するというのは、もうちょっと詳しくそこをお聞かせいただきたいです。","respondent":"大串福祉計画課長","answer":"今現在、第６期の介護保険事業計画を策定中です。その中で、詳細については検討されることになろうかと思いますけれども、特別養護老人ホームですとかこういった福祉施設を建てることによって、保険料への影響といったものが出てまいります。","id":"exchange-066"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"特別養護老人ホームだけがというのは、そうだと思うのですけれども、しかしニーズとしては上がってきているなと、私たちはまちなかに出ていて感じています。今現在そうなってき始めていますよね。もうそこには１億円ぐらいの差しかありません。ですので、保険料に影響するというのであれば、こういった有料老人ホームも、今後制限をしていくというふうに考えているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それでやはり経費からすれば、入所施設が一番経費的には１人当たりの経費は多くかかっておりますので、特別養護老人ホームや老人保健施設、療養型の病床等は、どうしても１人当たりの経費がかかってくるかなと思っているところです。","id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"お金を出せば要支援からでも入れるというのが、この特定施設です。高齢者１人当たり２万８,６８５円という準備基金が、要は余っている、貯められていると。ニーズはこれからどんどん増してくると思うのですね。こういった在宅重視というふうに言われている品川区で、今後の若い世代が自分の親の面倒というか、介護をしていけるのかどうかというのは、どういうふうに受けとめられていますか。","respondent":"永尾高齢者福祉課長","answer":"ですので、総合的というのはそういうする方、される方、あとそれを支える方、それらの方々を総合的に判断してというような考えです。","id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"これだけ不安定雇用で低賃金な若者たちが、月３０万円から４０万円する有料老人ホームに待たずに入れるというのは、到底無理です。これ自体も、もう苦しくて大変だという声も生まれています。要支援の認定率は、２３区中２番目に多いです。そして要介護５の認定率が、２３区中一番低いのですね。ですので、この方たちが申込みもできなくなる、そのことは、区としてはどう考えていらっしゃるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ですので、最初から特別養護老人ホームに入るということを考えるのではなくて、在宅でいかに、介護する方も負担なく、長く引き続きできるかというところを、先に議論をするべきだと考えているところです。","id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"在宅でできるだけ長い間といいますけれど、突発的な病気だったり、脳梗塞だったり、突然倒れられた方というのは、当然利用できないわけですよね。これだけ大変な中ですから、しかし必要な人が入れるだけの特別養護老人ホームは必要だという思いで、皆さん不安を持たれて請願を出されていると思うのですけれども、この必要な方々が入れているという認識は、あるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"突発的なというお話がございましたけれども、本当に突発的で、ひとり暮らしで、もう身体的、生命的、いろいろな部分を考えても無理だということになれば、それはやはり別の判断として、区がケースワークをしながら対応方法を考えているところです。","id":"exchange-070"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この間、相談に来られた方では、８８歳の父が認知症で、今は要介護３だと。そして仕方なく品川区でない、しかも東京都でもない郊外のショートステイをほんの１ヶ月間利用するだけでとりあえず気休めだと。こういうふうに言われて、特別養護老人ホームがさらに必要だと、必要な人が入れていないという実感は、品川区にはないということでしょうか。","respondent":"永尾高齢者福祉課長","answer":"多方面で考えていかなければいけないとは思っておりますけれども、そういうことも踏まえて、今回３つの特別養護老人ホームを新たにつくるという計画を立てたものです。それで、この３つの特別養護老人ホームを建てたことにより、やはり保険料もどうしてもアップしてしまいます。","id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはりこれからさらに必要になるというのが、私たちの地域を見てのニーズだと思っているのですね。旧みやこ荘は買われたのですよね、５０億円か何か出して。これはこの間のご答弁だと、補助金が出ないので土地は買えませんという話だったのですけれども、なぜ旧みやこ荘は買ったのか。これから先はもう買えないのだということなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"上大崎の地区につきましては、区のほうの計画の中の基本圏域というのを定めておりまして、そこの地域に一つも特別養護老人ホームがないという、そういう切実な思いの中で、区といたしましても土地の購入まで踏み切ったものです。","id":"exchange-072"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"切実な思いに答えてということであれば、一件もないというのは確かにそうです。ですけれども、１件しかないというのも切実な思いになってくるのではないかと思うのですね。ですので、私はこの請願者の方々の思いで、今からでも計画をつくっていく、どこにどの土地が使えるかというのを検討していくということを進めていただきたいと思うのですが。","respondent":"大串福祉計画課長","answer":"そちらの土地、用地情報といったものについては、我々のほうでも注意深く情報収集に努め、なおかつその土地の値段ですとか、あるいは使い勝手、利用する手法の関係、こういったものをつぶさに検討しながら、考えているところです。","id":"exchange-073"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"再三言わせていただいているのですけれども、土地もあるし、財源もあると、それを使わないという、やはり心がこの品川区にはないのだなというのが、先日も一般質問でやらせていただきましたけれども、２３区最低レベルの福祉を紹介させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問・要望","question":"端的に聞きます。これからも高齢化が進んでいく、確実なことであるので、それは私ども自民党としても特別養護老人ホームのことは要望しています。ただ、財政面であるとか、今の質疑をずっと聞いていると、特別養護老人ホームだけなのですよね。","respondent":"榎本健康福祉事業部長","answer":"それともう一つは、医療と福祉の連携という形が言われていますので、そういった面でも、地域の中で総合力を発揮していかなければいけないと考えていますので、それに向けて介護保険事業計画等さまざまな手法を考えていきたいと考えています。","id":"exchange-075"},{"speaker":"伊藤委員","kind":"意見","question":"やはりさまざまな福祉施策、介護施策を総合的に展開していかないといけないと思うので、ことさら特別養護老人ホームだけを取り上げる請願については、非常に、意にそぐわないということを、この場ではお話しします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"たけうち委員","kind":"確認","question":"今、伊藤委員からもありましたけれども、この請願の方たちは、これを読むと今３つの計画がある中で、これが終わるともうつくらないのではないかみたいな、そういうふうに誤解されているのかなという節もあるのですけれども、一応確認ですけれど、財源の問題だとか、また適切な用地確保だとか、さまざまな条件によっては、今後もそういうものを検討しながら。","respondent":"大串福祉計画課長","answer":"したがいまして、今ここで何か具体的な計画ということではございませんけれども、常にそういった形で、特別養護老人ホームも視野に入れながら、物事を考えていくです。","id":"exchange-077"},{"speaker":"伊藤委員","kind":"質問・要望","question":"請願第６号、第１２号について、今日結論を出すということでお願いいたします。これから高齢化が進展することは確実なことでありますので、私どもとしても特別養護老人ホームの建設は要望しております。ただし、これは一つのメニューであって、そのほかのさまざまな介護サービスや福祉のサービスをミックスした上で、財政も配慮しながら、しっかりと品川区が対応していただくことを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"たけうち委員","kind":"意見","question":"私どもも両請願とも本日結論を出すということで。結論については、両方とも不採択と。理由につきましては、今申し上げましたとおり、区としても、特別養護老人ホームをはじめさまざまな形で高齢化を支えていくための支援をやっていく中で、ただ無責任に計画を立てることにこだわるというのは、ちょっと難しいのかなと思いますので、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"向委員","kind":"質問・要望","question":"旧みやこ荘などについても結構スピード感のある対応をしてくださったり、それ以外のところも、杜松小学校跡、平塚橋会館跡についてもそうですし、今後の区のスタンスについても、今、私たちも非常に理解をしているところですので、このまま努力を続けていっていただきたいということで、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですけれども、その姿勢ですよね。それすらも見えないから、皆さん不安で、この後はどうなのだという確認をしたいという思いで、こういった請願を出されていると思います。ですので、やはり今後、こういった法改正もどんどん進んでいってしまう中で、高齢者がさらに生きづらい、肩身の狭い思いをしないように、なぜ特別養護老人ホームかというのはやはり一番求められているし、足りないからなのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"鈴木（博）委員","kind":"意見","question":"結論を出す。総合的なバランスの中で、特別養護老人ホームの建設のほうの推進をお願いしたいと思います。不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/637101?Template=document&Id=3388#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":44350,"voices":221}},{"id":"h26-20140630-8","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"建設委員会","time":"午前１０時００分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","topics":[{"id":"topic-01","title":"第４４号議案、品川区営住宅条例の一部を改正する条例","agenda":"第４４号議案、品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"一番下のこの配付資料の最後のところ、「改正前の法により、中国残留邦人等の死亡後に支援給付を受けている配偶者については、従来どおり、単身での入居資格を有する」というところをもう少し詳しく説明していただきたいのと、あと、対象者は区内にどれくらいいらっしゃるか、推定というか現状を教えてください。","respondent":"矢木住宅担当課長","answer":"２点目ですが、現在、支援給付を受けている世帯というのは、品川区内で２８世帯、４５名いらっしゃいます。特定配偶者は１２名いらっしゃいます。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、質問させていただいた趣旨は、最初に申し上げたとおりですので、粛々と進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改正内容の(1)のところで、ほかもそうなんですが、中国残留邦人、「等」がついているんですが、この「等」について教えていただきたいのと、今の(2)の最後の後の２行のところなんですが、ちょっとわからないのは、この新しい法ができた特定配偶者と、法改正以前の配偶者について、ここの違いがあるのかどうかということを教えてください。よろしくお願いします。","respondent":"矢木住宅担当課長","answer":"要するに、お子様方ということでしょうか。次、２点目のご質問ですが、以前の配偶者の方につきましては、特に規定なくと申しましょうか、永住帰国前後を問わず保護する趣旨でございました。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと(2)の最後の２行のところが、意味がいまひとつわからないのは、この新しい法律ができる以前から配偶者の方は一定の対策がとられていたということなのか、そうじゃなかったらどうだったのかなという、法律が変わって特定配偶者という名前になって、単純に配偶者ということだと思うんですけれども、この法改正の以前でも。","respondent":"矢木住宅担当課長","answer":"ご質問へのお答えですが、以前にも一般配偶者として支援給付は受けられておりました。したがいまして、区営住宅への単身での入居資格はあったものです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、改めて法できちんと定めたという捉え方でよろしいのでしょうか。","respondent":"矢木住宅担当課長","answer":"そのように解していただいて結構かと思います。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"今ちょっと難しいそうな質問が出ていましたが、簡単に、基本にかえって、この条例に関しては、法律改正によって内容整備ということでの話なんですが、そもそもこの題名の改正について、どのような理由、どのような社会的背景があって法律が改正されたのかということだけ教えてください。","respondent":"矢木住宅担当課長","answer":"経年によって変化してきたことの中で、高齢化、かなり高齢になっていらっしゃいますが、その方々の配偶者に対しても保護するという趣旨を明確にしたものだというふうに聞いております。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"経年による法律の改正、社会状況、経済状況、その他、人口構成、もろもろの世代間構成の変化によるものということで、今、課長がおっしゃったように、中国残留邦人等ということで、主眼としては、この方たちの高齢化に伴ってこの法律が改正をされ、それに伴って条例の改正をということで、ここの部分に関しては捉えていいのでしょうか。","respondent":"矢木住宅担当課長","answer":"そのようにお捉えいただければと思います。","id":"exchange-007"}]},{"id":"topic-02","title":"第４５号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第４５号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この４団地、ここが廃止の理由、区としては契約の満了というところですが、延長はないのかどうか。オーナーの意向というものはこういうとき加味されるのか、どういうふうにしているのか教えてください。","respondent":"矢木住宅担当課長","answer":"オーナーの意向につきましてですが、それぞれのオーナーのご事情がございまして、その辺は借上期間終了後、私どもといたしましては、居住者の意思を確認した上で、居住者が住み続けたいと言った場合には、そちらに居住し続けられるように丁寧に対応しているとともに。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここの四つのうちの戸数は書いてあるんですが、空き室というのがあるのかどうか、居住状況がどうなっているのかというのを知りたいのと、あと、区民住宅全体の中で、利用がどうなっているのかも教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"エステート共栄は、２４戸中、空き室が１９戸です。ブラウネスハイム倉田が、１１戸中、９戸が空き室です。大文字ビルが、１２戸中、８戸が空き室です。嶋田ビルが、１２戸中、１１戸が空き室です。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結構あいているんですが、これは任期満了でやめていく方向にあるから入れていなくてあいているのか、どういう理由というか、原因があってこんなにあいているのかなと思うので、その辺をお聞きしたいのと、借上型区民住宅の趣旨というか、目的を改めて、どういう中身なのかを教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"こちらですが、６月に募集いたしましたとおり、空き家募集は継続して続けてまいってあります。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"意見","question":"次々に年数、２０年たっていくと、契約が終わっていくわけですけれども、こういった状況からすると、区民住宅から区としては撤退をしていくといった考えを持っているのかどうか。民間マンションへの誘導へと方針を変えていくのかどうか、その辺をお聞かせください。","respondent":"矢木住宅担当課長","answer":"民間の住宅に関して言えば、民間の住宅ストックの有効活用ということで、今年度、空き家の実態調査もしておりますし、その結果も踏まえて、また新たに区民の皆様に提供できるものがありますれば、またそれは提供していく仕組みを考えていく方向です。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"意見","question":"先ほども近隣の家賃と同じになっていくというところにおいて、魅力が薄らいでいっているというところのことであったんですけれども、やはり良質な住環境を区が援助していく、支援していくというところでの位置づけは、これからも大事であるなと思っているので、やはり家賃の問題も工夫が要るのではないか、魅力があるような支援が必要ではないかなと思っています。これは意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"確認","question":"１点だけ確認を。私が物を知らなくて申しわけないんですけれども、借上型で契約を延長したものというのは今まで一つもないし、これからも方向性としてはないということでよろしいですか。","respondent":"矢木住宅担当課長","answer":"そのとおりです。","id":"exchange-013"}]},{"id":"topic-03","title":"第４６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第４６号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"最初のご説明で、この地区計画の変更が提案されているわけですが、誰が立案して提案をしているのかという基本的なところと、区がどのように関係をしているのか、大枠のところがわからないので教えてください。","respondent":"溝口都市開発課長、鈴木建築課長","answer":"条例ではなく、まちづくりに関するご質問なので、私のほうからお答えします。この建築基準法の審査の連携を図ることで、地区計画によるまちづくりの実現を法の規制の中でより確実に担保していこうというものです。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"Ａ地区のところ、新規追加という表現をしてあるので、よくわからないんですが、建築物の容積率の最高限度、最低限度、あと、建蔽率、面積の最低限度とか、1)から8)まで書かれているわけなんですけれども、この地区計画が存在する前のここの地域の用途とか、建蔽率とか、容積率とか、この地区計画をはめていく前のときと今の状況がどのように変わっているのかというのを、まちの姿が変わっていくので。","respondent":"鈴木建築課長、溝口都市開発課長","answer":"私のほうから、従前のこの地域の都市計画、用途、容積についてご説明します。従前、商業地域、近隣商業地域、またがる両地域がかかっております。今回の地区計画の中身で行きますと、確かに建物は高くなりますが、容積率が６５０％で建蔽率のほうは、従前８０％、実際、角地ですと１００％ぐらい使えるものが、抑えていったり、また、次の制限になりますが。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"答弁の中身はわかるんですが、いろいろな工夫はしているということですよね、圧迫感がないようなまちづくりという。そういった意味で、私が聞いたのは、空間というか、そこの地域の密度が高まるということに対して、それを表現したりする手立てというのは今のところないのでしょうか。何か具体的に比較できるものがないのかどうかというのを聞きたいんですけれども。","respondent":"溝口都市開発課長","answer":"それの前段となります街並み再生方針が定まっておりまして、その中で決まったこと、または事業が起こったものを順次都市計画として定めていく、そういった中身になっておりますので、地区の中ではそれぞれ密度といいますか、建物がどういう形になっていくのか、また。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その空間の密度については、非常にあらわしにくいと、現段階においてはそういうものの表現方法はないという受けとめ方でいいのでしょうか。そこをもう１回答えていただきたいのと、あと、資料３の壁面の位置の制限、あと、その右に歩行者デッキに関する文言削減というのがあるんですけれども、壁面の位置の制限がどう変わるのか、今までもあったんですよね。なかったんですか。これが初めて。","respondent":"溝口都市開発課長","answer":"はそれぞれ事業者のほうで、それに基づく事業計画を立てていく中で最終的には決まっていくような形になりますので、都市計画にあわせて将来の事業者になります準備組合のほうでやった説明会等の中では、建物の計画等をお示ししながらやってきているというのが実情です。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"デッキの問題は、どこの場所だか具体的にイメージできるように説明をして、どう変わっていくのかというのをしてほしかったんですけれども、一つは、壁面の位置の制限なんですけれども、ここの１８ページに、具体的にかかれていますけれども、すごくさまざまな壁面の後退の仕方がかかれているんですけれども、これというのは、基本的なルールとか、何か定めがあるのでしょうか。","respondent":"溝口都市開発課長","answer":"デッキの件なんですが、今、地区間を結ぶような形での街並み再生方針の中でデッキを結んでいくという考え方があっただけで、具体的にどこというのは、今後、事業化を図っていく上で、どこにどういうものを置くというのが当時考えられて方針に入っていたと考えております。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、壁面線の後退のところが、地区のケースごと、密度の圧迫感をなくすためにどんどん後退させていくという形とか、あと、１９階建てが建設をされたときに、風害を抑えるためにこういう形にしたとか、そういうご説明もいただいたことがあるんですけれども、そういうこともかなり加味をして、詳細。","respondent":"溝口都市開発課長","answer":"壁面線の指定の考え方ですけれども、建物ありきではありませんので、あくまでも地区計画の中でそういった先ほど言われた風害の形もそうですし、周辺の圧迫感、そういったものも考慮しながら地区計画として定めていく。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問","question":"車が通っていたところが多分人の優先の道路と前に聞いたんですけれども、道路をつけ替えていくためのルールというのが、勝手に変えるわけではないと思うので、この辺の拡幅するのもいろいろあると思うんですが、新たな道路をつくったり、今ある道路を廃止していくというところのルールというか、その辺を教えてください。","respondent":"溝口都市開発課長","answer":"今回、委員ご質問の区画道路４号、６号ですとか、歩道状空地６号というのが駅に接してあります。この辺の変更につきましては、その前のパルム地区、ここでいくとＢ地区を定めたときに変更したものですから、今回のＡ地区に伴っての変更ではございません。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"道路に関しては、交通関係者と協議の上でというところにおいては、当然、交通量の調査とか、事前に行っていくのでしょうか。どういった範囲で行って、実際に影響が大きいですよね。かなり影響が大きいと思うので、その辺をどうやっているのか教えてください。","respondent":"溝口都市開発課長","answer":"範囲につきましては、当然、当地区の北側になりますが、４６号線があります。西側に２６号線、また、その南側には、ずっと下りてきますと、中原街道があります。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"住宅なので、それほど交通量の影響は少ないということなんですが、住宅が増えれば、もちろん車も増えますよね、駐車場がしっかりある建物なので。そういう調査をした結果とか、基づいてやっているということなんですけれども、その内容について、近隣の住民なり、知り得る手立てというのはあるのでしょうか。","respondent":"藤田都市環境事業部長","answer":"ちょっと話がいろいろと広がってきておりますので、一旦ちょっと整理しますが、今回お配りしている１５ページ、資料３のペーパーですけれども、改正する条例の内容ということで、今回、Ａ地区の部分での建築物の用途等の制限について規定を変更するものです。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"建築ということですけれども、やはりとても大きな建物で、今後、次々に建設が進む地域ですので、本当に地域に与える影響がとても大きい、一建築の問題だけではなく、地域全体に影響するといったところでは、地域の関心が大変高いので、やはり詳しく具体的に関連したところもお聞きしたいなと思って、いろいろ細かくお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"仮に現状の空地率を１００とするとなると、この整備によってどれぐらい向上されるのかということを教えてもらいたい。","respondent":"溝口都市開発課長","answer":"ですから、委員ご指摘のとおり、そういったことを再開発事業を進めることによって、道路率、また空地率、そういったものが上がることによって、防災性の向上、そういったものが図られるまちづくりを進めることができるというふうになっているものです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"そこで、さっきの１５ページの改正する内容ということで、僕は建設に関しては素人に近い部分があるんですけれども、建蔽率を抑制しつつ容積率を上げた、こういうことで容積率が上がったというのは、そこの部分の主眼があって、そういうような変更をしたというふうに捉えてよろしいでしょうか。","respondent":"溝口都市開発課長","answer":"委員ご指摘のとおり、まさに道路ですとか空地、そういったものを生み出すために、敷地の最低限度ですとか、建蔽率の制限を厳しくしたり、そういったものをしているものです。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"地域の憩いの場所にもなりますし、防災のときの公園、空地も必要であると思うんですけれども、莫大な税金投入がされるという意味では、開発が有効な手段という考えも一つにはあると思うんですけれども、税金投入の仕方というか、高い建物を建てなくても、区が公園をつくるという意味で、そこに税金を使っていくという考え方もあると思うんですが、再開発ありき。","respondent":"溝口都市開発課長","answer":"ですから、再開発だけがどうこうではなく、総合的にさまざまな形でまちづくりを、品川のよりよいまちづくりのために努力しているというのがまちづくりの実態だというふうに考えているものです。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"さまざまな手法で実現をしていくというのはわかるんですが、税金投入をして、駅前でポテンシャルが高いとかおっしゃるのだと思いますけれども、駅前であっても空間を確保するという意味で、区が財源を投入して公園をつくるということは不可能なのでしょうか。その辺の検討はいかがなものでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"しかしながら、非常に地価が高いということで、民間の中でも当然ながら競い合い等がありまして、当然、マンション計画だとか、いろいろな形で土地の売買があったときに、なかなか区の財源で適地に公園を設けるというのは非常に難しいというような状況にあります。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"まちづくりマスタープランや、あそこの地域のまちづくりビジョン、上位計画がありますけれども、それ自体が決して地域全体、区民全体の意見を反映されたものでもないし、意見を出したものが取り上げられずして決まっていってしまったという方向もあるので、ぜひ地域の人の声をちゃんと聞いた中身にしていただきたいなと常にこれは思っておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"私もこういうのは素人でよくわからないんですけれども、１５ページの1)番の建築物の用途の制限というところで、丸ポツの２番目の風営法に関するということはわかっているんですけれども、この１番、「１階部分を駅施設、駐車場、店舗、飲食店等以外の用途に供する建築物」とあるんですけれども、この制限について、先ほど、建物の有効性とか、そういったことが若干ご説明があったと思うんですけれども。","respondent":"溝口都市開発課長","answer":"ですから、飲食店、店舗、またそれに必要な附帯の施設ですとか、駐車場とか駐輪場、そういったもの以外のものがそこの１階部分には建てられないように制限をするというのが今回の建築物の用途の制限の一つ目の内容です。","id":"exchange-029"}]},{"id":"topic-04","title":"第４７号議案、品川区大規模災害被災地に対する支援に関する条例","agenda":"第４７号議案、品川区大規模災害被災地に対する支援に関する条例","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"個別の災害協定を結ばれているところもあると思うんですが、先ほどの１番目の質問にも関連するんですけれども、逆にこういう災害協定を結んでいない、友好関係にありながらも結んでいないところの自治体は今のところあるのかというところで、そこがもしあるのであれば、具体例を教えてください。","respondent":"鈴木防災課長","answer":"今申し上げたようなところが具体的に想定をされる自治体等に当たるものですので、あとは、被災の大きさ、状況等によっては、例えば、昨年度のタイの洪水のような。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"確認","question":"友好関係と言えば、どこの自治体とも友好関係はあるんですけれども、今のご答弁でもう一度確認なんですけれども、大体想定している、大体この都市を想定しての条例だということなのかということがもう一つと、あともう一つ、ごめんなさい、私もこの条例案を読んで、こういう条例案が、私も不勉強だったんですが、まだなかったというところで非常に驚いたというところもあります。","respondent":"鈴木防災課長","answer":"昨日もそうだったんですが、やはり突発的なあまり想定できないような大雨の災害のようなものが増えてきておりますので、できるだけ早く整理ができたのであれば、しっかりと手続等に関する規定をしまして、迅速な対応ができるようにということで。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。もう一つ、先ほど、いろいろな支援をしていく中でいろいろな蓄積があって、それがこの支援の種類というところに反映されていると思うんですけれども、今まで個別に協定を結んできたところ、この中に支援の種類というのが入っているんだと思うんですけれども、それと比べてここはかなり厚くなっているというふうに考えていいのかどうか、この整合性についてお伺いしたいと思います。","respondent":"鈴木防災課長","answer":"それに基づきまして、区のほうでも実際の支援の中で法の大きなくくりの中ではうたわれていないもの、特に義援金等の募集や贈呈につきましては、これは区民の方個人もしくは法人等の善意の行動でございまして、これは災害対策基本法にうたってあるものではございませんので。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８条のところの委任のところに、この条例の施行に関し必要な事項は区長が別に定めるとあるんですけれども、必要な事項というのはどういう内容なのかというところと、別に定めるということで規則になるのか、その辺も教えてください。","respondent":"鈴木防災課長","answer":"それから２点目の８条の別の定めの内容ですが、冒頭の説明で申し上げましたように、具体的な支援を行うときに、例えば予算であったり、物を購入したりする、その執行に関するものが出てまいります。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"支援本部の設置のところなんですが、この支援本部の設置というのはルールがあるのか、今までどんな状況の中で設置がされたのかということを教えてください。","respondent":"鈴木防災課長","answer":"ただ、一定程度の支援の規模になりますと、例えば、区だけでは対応し切れない搬送のための手段であったり、それから、大量の物資の購入等がありますので、そういう具体的な手続、それから連携に関しての調整を行う機能がこの支援本部ということになります。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"最後のところなんですが、具体的に今までどういった状況の設置をされたのか教えてください。","respondent":"鈴木防災課長","answer":"それと、最近の例であれば、本年２月の大雪の対応のときなどには本部に当たるもの、当時はまだこの条例ができておりませんので、正式な支援本部という名称ではございませんが、災害の対応本部ということで設置をしております。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"簡単に、済みません。支援本部のところなんですけれども、公益的にやらなければいけないことで本部ということなんですけれども、なぜここが支援することができる規定になっている。そこのところでできる規定に、なぜしなければならない規定からできるという要因というか、できる規定になったのはなぜかというところ。この三つを教えてください。","respondent":"鈴木防災課長","answer":"ただし、先ほど申し上げましたように、全ての自治体、どこが被災したときにも全ての自治体同士で支援するということではなくて、やはり連携のとりやすい関係性のある自治体とというのが中心になるということで、必ず支援するという言い方にはしていないというのが考え方です。","id":"exchange-036"},{"speaker":"原委員","kind":"意見","question":"背景等は、先ほど、あくつ委員のほうからも出ましたので、タイミングの件も出ました。わかりました。そこについてのお考えをまずお願いします。","respondent":"鈴木防災課長","answer":"品川区といたしましては、実際の支援を行った場合に、例えば、施設等に入居をした方の個人情報であったり、それからまた、相手方のほうで公表を望まないようなケースかあった場合に、義務規定にしてしまうと、それを公表できない部分の扱いが困難になるということで。","id":"exchange-037"},{"speaker":"原委員","kind":"意見","question":"そうしますと、もう１点ちょっと踏み込んで、この条例化される前の段階で、今まで何か、先ほど飯沼委員のときに事例を出していただいたんですけれども、そうすると、その中で、義援金にしても、支援金にしても、物品を購入して渡すにしても、やはりお金が出る問題、公金が出る問題なので、今までの段階ではオープンになってきたのか、また、今お話があったように、要請があってしていなかったのかとか。","respondent":"鈴木防災課長","answer":"これまでの支援につきましては、基本的には区のホームページ等で支援した事実については速やかにお知らせをしています。","id":"exchange-038"},{"speaker":"原委員","kind":"質問・要望","question":"もう一回、再度、要望でもいいんですけれども、もう一回お答えいただければと思うので、やはり情報公開等、それから今度は守秘義務の問題と、最近いろいろと厳しくなってきて、行政と言っても、それこそ区だけではなくて、最近は逆に警察だったり、消防だったりが、すごい苦労されているということも聞くものですから、その辺についての、微妙なところだと思いますけれども。","respondent":"鈴木防災課長","answer":"確かに区民の方からお預かりした公金を使用して、支援なり、いろいろな災害活動を行いますので、自治体としては、説明責任を求められていることはしっかりと認識しています。","id":"exchange-039"}]},{"id":"topic-05","title":"第５４号議案、専決処分の承認を求めること","agenda":"第５４号議案、専決処分の承認を求めること","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区民住宅なので、審査の段階でどのくらいの所得があって、支払能力がどうかというチェックができての入居の後なので、この方にどういう事態が起きて払えなかったのかと多分つかんでいらっしゃると思うので、そこを教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"本件のこの方につきましては、タクシー運転手をなさっていますが、やはりこの間での収入の減というようなことが主に滞納の原因だというふうに聞いてあります。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"収入の減ということで、結構高い賃料だったんですか。一番心配するのは、収入が減った、例えば本当に仕事を失ってしまったりとか、病気とか、そういうところで実際に払えないというような状況が生まれる、これだけお会いしているので、事前にいろいろ状況はつかめますよね。そういった場合に、たくさんたまる以前に対応する措置とかあるのではないかなと思うんですが、その辺はどうなんでしょうか。","respondent":"矢木住宅担当課長","answer":"こちらも活用しながらといいましょうか、それより以前に、１カ月目ぐらいは、もしかすると、人間ですので、銀行にお金が残っていなかったというようなこともあると思うので、２カ月滞納ぐらいを目途に使用者の方を区役所のほうにお呼びして、生活状況をお聞きするような。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"この連帯保証人の方というのは、ご夫婦ではないんですね。この方はどういう方なのでしょうか。","respondent":"矢木住宅担当課長","answer":"こちらの方は、被告人のお姉様です。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"なので、本当に追い詰められ、いけないことなんだけれども、やはり追い詰められるところまで行く手前で何か救済的なものはないのかと、こういうケースに当たるたびに思うんですが、いかがでしょうか。","respondent":"矢木住宅担当課長","answer":"そのために住宅担当として何ができるかということを考えましたときに、それはやはり早期の滞納のときにお話をして、生活状況をお聞きして、やはり何人かお会いした方の中には、もう本当に家族４人で七、八万しか食費とかに残らないような、要は、収入が減りまして。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、なかなか経済が低迷していて、賃金が減ったり、暮らしがなかなか大変なときなので、こういうケースもこれから増えてくると思うんですが、ぜひ本当に、追い詰めて最悪な状況にならないということがまず念頭に置いていただきたいと思います。多分十分な働きかけをされていたと思いますので、今後の対応に期待をしたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"松澤委員","kind":"質問","question":"建設委員は久しぶりなんですけれども、毎回必ずこの問題は出るんですね。今回、特に微に入り細にわたり報告していただきましてありがとうございました。ただ、このタクシーの運転手、現在もタクシーの運転手をされているのでしょうか。その点をお聞きします。","respondent":"矢木住宅担当課長","answer":"現在もなさっています。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問・要望","question":"入居する場合には、当然ながら収入状況、特に区営住宅と違って区民住宅ですから、収入がしっかり、払えるのかどうかというのを調査していると思うんです。それで払えなくなってしまった。どういう形でやっているんですか。１日おくれても民間では督促をしますけれども、指定管理者、品川区の区民住宅の場合はどういう形で督促をしているのか、そこをちょっと、一番大事なところでお聞きしたいと思います。","respondent":"矢木住宅担当課長","answer":"指定管理者の督促方法ということでご質問と捉えてよろしいでしょうか。","id":"exchange-046"},{"speaker":"松澤委員","kind":"意見","question":"やっぱりその期間が長過ぎるんです。１５日にならないと動かないというのが、そこがもう長いと思うんですね。そのやりとりの中で、本当に生活に困窮して困っている方、課長も言われましたけれども、そういう方もいらっしゃるんですね。意見でいいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"訴訟の目的の価額というところで、６８０万円余というところで、これは使用料とは異なるんだよということで、高額なほうを使うよという話になっているんですが、明け渡しを求めているという裁判だと思うんですけれども、これは今、それに臨まれるわけですから、それに対してどうこうということではなくて、先ほどほかの委員からありましたけれども、これは毎回繰り返されることだということなんですが。","respondent":"矢木住宅担当課長","answer":"この辺につきましては、全額払えという判決のほうが多いとは思いますが、やり方につきましては、やはり生活状況も勘案した分納というようなこともおそらくはやっていくのではないかと考えております。","id":"exchange-048"}]},{"id":"topic-06","title":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３５号議案、平成２６年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"予算特別委員会のときにも何回か質問させていただきましたけれども、入札不調も続いている中で、その上、単価もアップしてというところでのスライド条項の適用というような話も業者のほうから幾つかいただいていたかと思うんですけれども、今回、所管は違いますけれども、ほかのところの施設もかなりアップされているというところで、普通であれば、それはやはり公金を使うわけですから。","respondent":"矢木住宅担当課長","answer":"こちらは非常に細かくなってしまうんですが、例えば工事の中でも建築工事、電気工事、空調設備工事、給排水衛生整備工事等々ございまして、その中でも建築工事につきましては、例えば材料価格が１２.２６％アップというような、あと、電気工事につきましては。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こういう中で、その協議というのは、区のほうからそれは事業者のほうに話をするのか、それとも事業者のほうから、世の中のそういう動きで、もしくはそういう団体の中でそういう話があって協議をしなさいよという話になって話をしたのか、そういうところはどういう流れ、ちょっと所管がもしかしたら契約のほうになってしまうかもしれないんですが、わかる範囲で教えていただければと思います。","respondent":"藤田都市環境事業部長","answer":"通常のケースで考えたら、一定の上昇率であれば、区のほうからもお話しすることもありますが、基本的には業者のほうがこのままだと工事がそのまま進められないということで、ご相談いただくようなケースが多いのかなというふうに考えてあります。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ごめんなさい、プレス発表とかに載っていた図なんですけれども、前回、説明会をしますよと言って同じ図が載っていたんですけれども、具体的にどういうふうに広がるのかがちょっとわからないので教えていただきたいのと、１６３号線の整備を行う理由、なぜ整備を行うのかという基本のところを教えてください。","respondent":"稲田道路課長","answer":"は６５ｍ、このボトルネック部分を解消して、また次に進めたいというふうに考えています。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"車道のところは、今、１２ｍから１６ｍ、歩道の部分はどうなのかというのを一つお伺いしたいのと、あと、ボトルネックということだったんですけれども、今、現実的にここのところは、車の渋滞とか、困難性はどのような状況になっているのか教えてください。","respondent":"稲田道路課長","answer":"看板を設置したり、それから、信号の秒数を変えながら、なるたけ渋滞にならないように現状進めております。毎日これが続くのかですけれども、ピーク時においてはそのような状況が発生しています。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"混雑時、ピーク時に二百数十メートル渋滞しているということなんですが、交通量の混雑度を示す基準というのがあるんですが、そういった基準においてはどうなんですか。","respondent":"稲田道路課長","answer":"将来なんですけれども、これは２３年度に検討したものがございまして、今、１日７,１８４ですが７,５００台ほどになるのではないかというところで、混雑も１.０４ほどになりまして、混雑率も上がっていくという状況があります。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"大井町もこれから開発を進め、道路と開発、一体的なまちづくりをさらに進めるというところにおいて、どうなのかという疑問を持っていますけれども、ここは今回の工事は幾らぐらいかかる、総事業、今回、委託ですよね。今後どのくらいかかるのですか。","respondent":"稲田道路課長","answer":"今回、補正の債務負担の額を追加させてもらっていますが、ここに４７億４,０００万円というふうに出ております。これは影響する東急電鉄の桁の架け替えの工事ということで、それにプラスしまして道路整備工事費を約１億２,０００万円ほど、今、考えております。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点、水族館のところなんですが、指定寄附金ということだったので、中身がどういう指定になっているのかお伺いしたいのと、２,０００万円ということなんですけれども、今後どういったところに使われるのかという案があるのかどうかを教えてください。","respondent":"多並公園課長","answer":"実際、今後、議決後、水族館を運営しているサンシャインと協議しながら進めていきたいと考えています。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"２３ページの区営住宅の追加分ということなんですけれども、これはやはり金額が大きいのをこんなに安易していいのかなという気持ちもします。先ほどもお話を伺いましたけれども、建築工事の資機材が上がって労務費が上がっているというのですけれども、繰り返しになりますけれども、労務費が上がった分の補償というのはわかるんですけれども、その辺をもうちょっと詳しく説明してください。","respondent":"藤田都市環境事業部長","answer":"私どものほうとしても、安くていいものをつくるというのが基本ですが、なかなか今、それが難しいといったような実態もあります。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"説明を聞きましたのでわかりました。もう１点、施工監理委託、これも上がっているんですけれども、施工監理、これは人だけの問題ですよね。これも労務費と違って向こうへみんな施工監理で行ってしまっているからというふうには思えないんですけれども、これが上がっているのはなぜでしょうか。","respondent":"藤田都市環境事業部長","answer":"それにあわせて積算していますので、これについても区にとっていいものをつくるために必要な経費ですので、どうぞよろしくお願いいたします。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"意見","question":"反対です。１６３号線のところで、大崎、大井町を結ぶ幹線道路の整備ということは、さらなる開発を進めるための道路づくりということで、ガードの工事もまた、ここを広げるということは賛成ですけれども、さらに大崎、大井町の開発を進める観点で反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"二つの請願に共通している内容というと、高齢者の外出支援をしてほしい。必要性は他区で既に実証済みではないかと考えますが、先ほどのご説明によると、慎重であるべきだというご説明をいただいたのですが、品川区が区民のこのたび重なる要求を受けて、ぜひコミュニティーバスの運行を実現していただきたいと思うのですが、その点についてはどう受けとめていらっしゃるのか、お答えいただきたいと思います。","respondent":"中村都市計画課長","answer":"これを補完する意味で、例えばコミュニティーバスをこのバス停とバス停の間を補完するということで運行するということになると、完全に既存のバス路線と重なるということにもなります。その辺から考えまして、コミュニティーバスの導入に慎重な検討が必要といったところです。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この訴えに対して、ぜひコミュニティーバスをつくってほしいということなのですが、まず今、バス停は３００ｍで、７００ｍよりもずっとやさしいと思うのですが、鉄道の７００ｍの意味がちょっとよくわからないので、なぜ７００ｍなのかということ。やはり乗りかえの困難さもかなりあると思うのですけれども、この７００ｍ、今のご説明だと歩くのが１１分ぐらいですか。そういった待ち時間が長いと不便である。","respondent":"中村都市計画課長","answer":"ただ、これに関しましてもそれぞれ個人差もありますことから、バス路線あるいは鉄道の駅の間隔を短くするというよりも、別の方法でまた考えるというのも一つかと思います。それから、大井町駅から区役所までの距離ですけれども、およそ５００ｍと認識しています。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"年間の利用は３９３万人、うち３割が無料で利用されています。こういった状況なのですけれども、私はお話を伺って、とてもやさしい中身であると思っていますし、やはり最初のときよりも利用も増えているし、この３億円が十分活かされているという報告を受けているので、品川区の既存のバスとの住み分けの懸念は、私はやっていく中で解決していく中身であると思いますが、もう一度、いかがでしょうか。","respondent":"中村都市計画課長","answer":"ただ、内陸部のほうにつきましては、鉄道も、それからバス停も存在しているということで、おおむねやはり通常歩いていける、今、私どもは７００ｍ１５分と申し上げましたけれども、ゆっくり歩いて１５分で行けるということで、十分対応ができているのかなと考えています。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"十分対応ができていないから、この間１２回、１３回請願が出されていて、現実的には２３区中２０区で実施されて大変喜ばれている。私はもうここに必要性が十分あらわれているし、やっていける中身であると捉えています。やはりこういう視点に立って捉えていただきたいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"当然品川区でも、そういった利便性の悪い地域があれば対応はしていかなければいけないというのは当然のことですけれども、今、現状の中で申し上げますと、繰り返しになりますが、おおむねバス勢圏ですとか駅勢圏、こういったもので足りているのかなと考えています。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"高齢者の方も障害を持った方々も、また子育て世代のベビーカーを押していらっしゃるような方たちも、荷物をいっぱい持って駅まで歩く、バス停まで歩く、この大変さをやはり身近なところにコミュニティーバスがあることでとても助かるのだという請願を出しているので、私はこの必要性はぜひ認めていただきたいのですが、その辺はどうなのでしょうか。","respondent":"中村都市計画課長","answer":"その辺、既存の路線バスを廃止してまでコミュニティーバスを走らせるかというところについては、非常にリスクが伴うと思いますので、慎重な検討が必要だと考えています。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"これはやり方ではないですか。採算のところはどうなのですか。採算性について。ここのところは何もないのですけれども、港区は運営の経費と、あとバス購入の経費の補助を行っているということで、年間３億円。これはどういうところにどう路線を引いていくのか。そこがネックになるところ、ブレーキをかけるようなことはないと思うのですが、再三言っていますが、必要性については認められませんか。","respondent":"中村都市計画課長","answer":"今、ご覧になっていただいた資料の中でも、おおよそ駅とバスで市街地が網羅されているということになりますと、全く既存の路線バス等に影響がないということはないわけで、その辺は慎重な検討が必要かとは思います。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、こうやって実際にそういった利用されていらっしゃる方が切られたことで、やはり生活が変わってしまうという訴えをされているのですけれども、私はやはり本当に地域の住民の方の生活を支えるところに自治体がどれだけ頑張れるのかというのが、とても求められていると思います。財源もありますから、区民のためにどうそれを使っていくのかがやはり問われているのだと思います。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"そういった意味からしますと、１路線当たりの経費というのは、先ほど億という話もございましたけれども、そういったところで既存の路線バスと共存して採算性があるというのは非常に難しい。そういう中で、バス事業者として、先ほど委員のほうからもお話がありましたとおり、確かに民間事業者ですので、その声に一つひとつきめ細かく対応するというのはなかなか無理な部分もあると考えています。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、「慎重に検討、慎重に検討」が何年もたっているわけなのですけれども、どういうことを慎重に検討し、どう進んでいくのかというのがなければ、このたびも二つの請願が出されましたけれども、いつも同じ状況で戻されてしまうわけで、展望が見えないのですけれども、もう少し具体的に示していただかないと、区民の皆さんも決してこれでは納得できないと思うのですが、いかがでしょうか。","respondent":"藤田都市環境事業部長","answer":"バス事業者に対してもこういった地域からの声が上がっていることについてもしっかり伝えていく、それを見える形にするという意味でも、品川区地域交通検討会の意味があると考えています。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にしますけれども、今のところは、今のご答弁では民間といろいろ考えて、コミュニティーバスに限らずさまざまなところで考えていくということなのですけれども、私はもちろん民間事業者の方々と一緒に検討するのは大事ですが、やはり区がこのコミュニティーバスを、地域の小回りのきく、行きたいところに本当に気軽に行けるコミュニティーバスを願っている区民の皆さんの願いをどう受けとめて。","respondent":"藤田都市環境事業部長","answer":"そういったような民間事業者としての苦労もさまざましていますので、さまざまな面でこういったバス事業者のほうといろいろお話をする中で、よりよい地域交通網の充実を図っていきたい。そのために慎重な検討をしていきたいと考えています。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"提案","question":"今、お話に出た品川区地域交通検討会、議事録もあらあらの議事内容が公開されているのは見ました。この中で法に基づく地域公共交通会議のご提案もさせていただいたことも会派としてありますし、というよりももう少し広い形での議論をということで、品川区地域交通検討会という形で１回開催をされたということなのですけれども、方向性としてはそれでいいのかなと思っています。","respondent":"中村都市計画課長","answer":"委員ご指摘のとおり、まさに区民の利便性のための会議体と考えております。そういった意味から広く意見をお聞きすることが必要ですし、今、ご指摘のとおり検討を進めて、利便性のための会にしていきたいと考えています。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"先ほど、やはり高齢者の移動支援の件と、ここにまつわる経費、もろもろ財政、どれだけコストがかかるかということを分けて考えないと、ごちゃごちゃになってしまうと、それこそ話の論点が見えなくなってしまうと思うのです。実際、しながわ水族館の循環バスは、今、大井町からしながわ水族館までですが、これを荏原地域からということで、あれはどれぐらいの赤字が出たので廃止をしたのか教えてください。","respondent":"多並公園課長","answer":"今現在の大井町としながわ水族館の間を通っている運行バスの経費ですけれども、年間２,４００万円かかってあります。そういうところからすると、何千万円単位のかなりの赤字になっていたのではなかろうかと認識するものです。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"それと中延地域、両方請願が出ておりますけれども、この地域の特性というか、どのように行政側は考えているのか、教えていただきたいと思います。要は先ほど来、交通網が整備をされていてということで、徒歩でも駅に行けるということは伺いましたけれども、この請願項目に特化して言った場合、ここのおのおのの地域と駅の立地状況について、どのように分析をされているのか教えてください。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、大型の路線バスがなかなか入りにくいという特性があると思います。バスを運行するような場合でも大型は無理で、中型から小型で考えなければいけないという特性があろうかと認識しております。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"ですので、交通手段を得るということは大変重要なことなのですけれども、先ほど理事者がおっしゃったように、高齢者支援としての財政を圧迫しないような交通手段を得ることが大事だと思うのですけれども、さっき審議会だか会議体があったということですけれども、例えば財政を圧迫しないような交通手段、今はどのようなものをお考えになっているのか、ビジョンがあったら教えてください。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、まずご自宅などから目的地まで行きたいというニーズを区内全域の中で捉えて、そしてオーダーメード的に送り迎えをするようなワンポイントのサービスのほうが、むしろ小回りがきいていいのかなと考えています。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"私はいずれにしろこれは財政面から言えば赤字が出ることについては問題がある。しかしながら、やはりこの高齢者の支援ということでは他課との重要な密接な連携が必要だと思いますので、そこのところをしっかり念頭に置きながら、この会議体の議論を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"飯沼委員","kind":"意見","question":"財政負担の赤字を出してはならないということなのですけれども、コミュニティーバスを運行するというところだけを見れば、実際的に補助金がかかるのでお金がかかると思います。だから目の前のかかる経費だけを見るのではなく、やはり自治体が広く区民の生活全般を見たときに、どういった効果があるのかというところも踏まえて考えていかなくてはいけないと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。内容については、願意に沿いがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出すというところで、内容については願意に沿いがたいということですが、一言添えするならば、先ほど会議体としては品川区地域交通検討会でこれは検討していく。先ほどの発言の確認ですけれども、交通が不便だと感じる方々を救うということが、この前の品川区地域交通検討会の中で、事務局である区のほうからそういったご発言もありますので、そこのところを、今、民間も含めて検討されている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出します。請願項目については、願意に沿いがたいということで、不採択でお願いします。そういった中でも、お話があったように他の区でもさまざまなリスク等々ある中で、しっかりと検討していかなくてはいけないと考えています。しっかりとその有識者、また事業者、地域の方々の意見もそちらでいろいろ集約しながら、情報を収集しながら努めているものと思いますので、注視していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。意見を添えて採択です。コミュニティーバスが実現をしていけば、区民が本当に自由に安全・安心に移動ができるようになる。ぜひ保証すべきであり、民間任せにしないで、自治体が、こんなにたくさんの願いが届いている、私は税金が活かされる施策であると思いますので、もうやるしかないのではないか、すぐにでも実現をしていただきたいと思います。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"原委員","kind":"質問","question":"本日結論を出すということで、もう私事ですけれども、私自身は狭窄症等もありまして、実際に１００ｍ、２００ｍ歩くのがきついという、ですからここに書いてある願意というか思いは非常によくわかるのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新聞にも１面にでかでかと掲載されましたけれども、区はこの方々の声を聞いていますでしょうか。品川区の特定整備路線は３本ですが、このまちに住み続けたい人々を追い出すことになるわけで、このことをどう考えていらっしゃるのか、お伺いしたいと思いますけれども、行政不服審査請求の中身はお読みになられたでしょうか。そこのところをお伺いしたいと思います。","respondent":"中村都市計画課長","answer":"住み続けたい方を追い出すことにですけれども、こちらのほうも、東京都のほうも、今、こういった相談窓口などを設けて手厚く対応しているものと考えておりまして、また、区も都と連携して同じように対応していきたいと考えています。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"８５歳の女性です。とても不安です。たくさん書いてある方もいらっしゃるのですが、「２９号線計画道路の近くには、並行して国道１号線があり、品川区は２００２年に東京都に２９号線の廃止を求める意見書を提出している。今、住んでいる人が住み続けられない、納得がいかないままに追い出すことになるということ、追い出しになれば、自治体ではなくなってしまうと思うのですが、この点はいかがでしょうか。","respondent":"中村都市計画課長","answer":"その上で経済的な面、あるいは住むところがなかなか見つからないのであれば、それは一生懸命また相談窓口などで相談をして、アドバイザーの方などにも一緒に探していただかなければいけませんけれども、そういった中で。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問","question":"今、読み上げた方たちは、ほかでは暮らしていけない、ここに住み続けたいのです。品川区民なのです。調査の９１.５％、これだけの方が住み続けたいと言ってくれてうれしいとおっしゃいましたが、９１.５％の中で多数を占めるのが高齢者の皆さんです。年をとってもここの地域に住みたいという方を、結果的には追い出すのではないのですか。ここに住み続けたいと言っている人に何をしてくれるのですか。","respondent":"中村都市計画課長","answer":"今、相談窓口に関しましては、一つは不動産業者に委託をしているということで、不動産業界の中のネットワークをフルに活用して物件の情報などを広く得るようなノウハウを持った事業者であるために、こういった委託が行われたと認識をしています。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"不動産業のノウハウを持っている方が相談に乗るということなのですが、今と同じ条件で品川区に住み続けられるのでしょうか。幾ら相談に乗っていただいても、これが実現しなかったならば本当に不安ですね。この点をお答えいただきたいのと、私が今、行政不服審査請求の中身を読み上げさせていただいたのですけれども、つらい思いを受けとめていただきたいのです。その点はどうでしょうか。","respondent":"中村都市計画課長","answer":"ただ、東京都も説明会などで個別に十分に相談に乗っていきますということと同時に、こういった相談窓口も開設しているということから考えますと、やはり従来からお住まいのような環境になるべく近いものというのが皆様方のご要望でもありますでしょうから。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本人が全く納得していない、合意もしていない、なのに移っていただくのに、今よりも悪い条件のもとで、それは申しわけございませんと言って移っていただくことになるのでしょうか。犠牲をお願いするという、それが自治体なのでしょうか。まちづくりなのでしょうか。私はこんな犠牲を強いてはいけないと思いますけれども、その点はいかがでしょうか。合意の点もぜひ答えていただきたいと思います。","respondent":"中村都市計画課長","answer":"この我慢をしていただくですけれども、これは私どもは我慢というよりも、理解をしていただくような努力が必要だと考えております。ですので、理解をしていただくまでわかりやすく説明する。これは東京都も同じような回答を説明会の中でもしています。","id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これは理解できない住民の方が悪いのでしょうか。住民の声を聞かなくて、押しつけている自治体の問題ではないでしょうか。誰のためにこんな犠牲を強いるのですか。本会議の共産党の質問の中で、パンフレットに書いてあるといった説明がされたのですが、どのパンフレットのどこの部分に書かれているのか示してほしいのと、いつどのように説明をしたのか、あわせてお答えいただきたいと思います。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"いずれ東京都のほうも、今後また説明会の後にいずれは測量ですとか、あるいは補償の話になりますと、これは関係する方々には１００％必ず説明するということになろうかと思います。特定整備路線のお話ですけれども、木密地域の改善のために、燃え広がらない、燃えないまちをつくっていこう、これは皆さん共通の認識にあるのかなと考えています。","id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり再度きちんと説明をすべきである、やり直す必要があると思いますが、この点と、あと都市計画法の第１６条、公聴会の開催をやるべきである、住民の信頼回復のためにもやるべきであると思うのですが、個々の説明はやりますとおっしゃっていますけれども、求めているのは公聴会とか聴聞会、ちゃんと対等に話を聞いて、意見を聞いて、取り入れてくれるといった会を開いてほしいと言っているので。","respondent":"品川木密整備担当課長、藤田都市環境事業部長、中村都市計画課長、若林委員長","answer":"この場で、道路に来るときに火災はとまっているという説明は何度かしていると考えております。パンフレットの関係ですが、私のほうも事業概要、それから現況測量については、補助２９号線の説明会に全て行ってあります。公聴会ですけれども、こちらも皆様の意見を十分に聞くというところでは、今までの説明会もそうですけれども、今後また個別にそれぞれ対応して。項目だけでも、全部で６項目の審議をしなければいけない、委員会ですので採決をしなければいけない項目が。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"提案","question":"これは明確にお答えをいただきたいと思います。台東区も、沿線住民の理解が得られない可能性が大きいため、必要なしと今回は求めないと言って、地域住民の声を受けての区長の姿勢が、やはり本来の住民の首長である区長の姿勢であると思うのですけれども、品川区はそういった点を区民に伏せながら進めてきたというところを、区長にかわって部長、どうお考えなのですか。","respondent":"藤田都市環境事業部長","answer":"この間、品川区としては、だからといって、そのまま東京都が進めればいいということを考えているわけではなく、丁寧な説明を、特に生活再建についてはしっかりとお話を聞きながら進めるように、東京都に求めてきたところです。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にします。ほかの委員にもぜひご意見を伺いたいと思うのが、「都市計画道路補助第２９号線の計画廃止を求める意見書」というのが平成１４年、２００２年７月１２日、品川区議会から東京都知事宛てに出されました。皆さんのご意見を伺いたいので。区の方針が変わった途端、なぜ計画反対から賛成になったのか、ぜひ最後に皆さんにご意見をお伺いしたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"若林委員長","kind":"意見","question":"ただいまの飯沼委員のご発言ですが、本請願・陳情の内容の中に組み込まれているものではございませんし、あくまでも本日の請願・陳情の内容に沿って議論を進めたいと思いますので、今の委員の発言に関しては、委員長としては取り上げませんので、よろしくお願いします。ほかにご意見ございませんか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。願意に沿いがたい、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本日結論を出す点でお願いしたいと思います。採択を主張しますが、一つ意見を述べさせてください。何のための道路かわからないまま住民を追い出し、環境悪化をもたらす特定整備路線、この放射２号線、補助２８・２９号線、３路線の事業計画は計画中止を求めますので、この請願に採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"原委員","kind":"質問","question":"ですから、ここのことに関して、本日この請願・陳情等に関して出てくるとすれば、私はこれに関しては不採択でありますが、今後においては、この間１０１名が行政不服審査請求をされているということですので、そういった方向ですとか、もしくは法治国家でありますので、これはリスクを背負いますけれども訴えを起こすとか、そういうようなこともあろうかという、その意見だけを加えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]},{"id":"topic-07","title":"の４「その他」","agenda":"の４「その他」","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"６月２７日、本多健信議員の質問の中で、３項目目「空き家等の対策について」、これに対するご答弁の中で、条例案を検討されていると。現在空き家、細かく言いますと、あと空き家の調査をかけていると思うのですけれども、そことの関連性について。それを１年間かけて調査するということになっていましたけれども、その関係性についてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817105?Template=document&Id=4108#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":79165,"voices":297}},{"id":"h26-20140630-9","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"文教委員会","time":"午前１０時００分～午後３時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","topics":[{"id":"topic-01","title":"の第３７号議案、品川区奨学金貸付条例の一部を改正する条例","agenda":"の第３７号議案、品川区奨学金貸付条例の一部を改正する条例","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ、確認させていただきたいのですが、今の説明の中で、２名全ての方が亡くなられたときに債権がなくなる、放棄できるという内容とお聞きいたしましたが、本人と連帯保証人、両方が亡くなられたときには、全部放棄しますという内容でよろしいのか。そこだけ教えてください。","respondent":"福島青少年育成課長","answer":"まさにそのとおりでございまして、３人とも亡くなったときに、相続人には請求しないということにしたいと思います。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"例えば、ご本人が亡くなったら、連帯保証人に債務が移行されていくことになるのですけれども、何らかの形で一定の早い時期に、２０年もたたないうちに３人が３人ともお亡くなりになってしまった場合、もちろん何年という規定はないということですか。その辺をまとめて教えてください。","respondent":"福島青少年育成課長","answer":"全て亡くなったときということであります。ですから、何年ということはないです。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"その辺についても、もう少し考慮というか、改善されてもいいかなという気はするんですけれども、そのあたりはどうなんでしょうか。","respondent":"福島青少年育成課長","answer":"こちら、基本は連帯保証人２人ということになっていますけれども、どうしても事情で１人しか立てられない、基本的には本人と、その親プラス知り合いという形になりますけれども、立てられない場合は、公正証書をつくっていただくとか、そういう形をもって。","id":"exchange-003"},{"speaker":"須藤副委員長","kind":"質問","question":"２０年以上前にというのだけれども、相続人に返してくださいという返還の行動というのは、いつごろからやるの。１年たってからやるの。それが１点と、それから、過日ご報告いただいた、専決処分の報告資料で、１２番のところに、１２番と１３番で、全然違う人の名前の連帯保証人になっているんだけれども、これはどうなのかなと思ったんだけれども、そのあたりをちょっと教えてください。","respondent":"福島青少年育成課長","answer":"奨学金の場合は、今は違いますけれども、かつては２０年間で返還していただくという形になっていましたので、どうしても返還期間が延びてしまうということで、本人に請求していたんですけれども、本人が亡くなったということもあって、連帯保証人に新たに請求したときに。","id":"exchange-004"}]},{"id":"topic-02","title":"の第３８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例","agenda":"の第３８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"第１９条のところなんですけれども、学校休業日の１日につき８時間、それ以外、学校休業日以外は１日につき３時間というところなんですが、保育所を利用していらっしゃる家庭の皆さんには、ちょっと短いのではないかと思うのですけれども、差がありますよね。要するに、８時間、３時間ということに関して、その辺はどう移行するのか、お伺いしたいんですけれども。","respondent":"伊崎子育て支援課長","answer":"第１９条の開設時間ですが、こちらは、冒頭申し上げましたように、最低基準ですので、これを満たさなければ、放課後健全育成事業として品川区内で区長の監督下では事業ができないという最低の基準です。","id":"exchange-005"},{"speaker":"吉田委員","kind":"意見","question":"夜間預かっているような保育園もありますから、そういう意味で、３時間というのは、３時間以上という理解でよろしいのかということと、それから、夜間預かっていることもあるんですけれども、そういうことに関しての対処というか、保育園から１年生になって、小学校１年生のときに、今まで仕事をしていらした方が、引き続き子育てをするには、ちょっと間があいてしまうのかということに関して。","respondent":"伊崎子育て支援課長","answer":"こちらの条例で定めているものは、全て最低基準ですので、これより上回って実施するものを妨げるものではございません。それから、今ご指摘がございましたのは、開設時間の終了時間についてということでよろしいですか。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。本当にスムーズに行っているのかなというのは、ちょっと疑問はあるんですけれども、これから先、そこら辺も検討して、私としては要望なんですけれども、３時間以上というお話なので、臨機応変にしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ、この条例設定に基づいて、今まで行われている事業が、このことによって水準が下がることはないという前提で条例が制定されるという認識でいいのか、そこだけ確認させてください。","respondent":"伊崎子育て支援課長","answer":"この条例は、最低基準を定めるものですが、今現在、最低基準を上回って実施しているものは、それを低下させてはならないと第５条に規定していますので、そういったことはございません。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"細かい部分で、教えてください。それから、第１４条の第３項の参酌です。「必要な医薬品その他の医薬品を備えるとともに、それらの管理を適正に」とありますが、これは、どういうやり方で、今までやってきたことも含め、それぞれどういうふうにしていくのかと、その辺を教えてください。","respondent":"伊崎子育て支援課長","answer":"第４項の評価の公表につきましては、こちらは、区の事業といたしましては、毎年振り返りなど、実施についての評価はしていますが、公表という形では、児童福祉施設の中でやっているわけではございませんので、こちらにつきましては、努力規定ではありますので。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"もし違うと、答弁がなければ結構です。ごめんなさい、１つ抜けていたのが、第１６条の帳簿関係のことがあるんですが、これは、日常的に言うと、どういったルーチンで発生するものなのかというところなんです。職員の方と書いてありますけれども、お子さんのそうした対応というところの中で、この帳簿のところは、どの程度のレベルのものがあるのかなと、それをちょっと教えてください。","respondent":"伊崎子育て支援課長","answer":"この規定は、どちらかといいますと、民間事業者が実施する場合に、きちんと職員、財産、収支、利用者の処遇について帳簿、書類をそろえておきなさいという規定なんですが、当然、すまいるスクールは、区の施設ですので、職員についての管理もしておりますし、財産。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"第３８号議案というのは、法律に基づいて条例をつくるということで、国の基準を最低基準としてという規定をした条例だと理解するんですけれども、現在のすまいるスクールの中に位置づけられているという学童保育クラブ、それがどういう状況になっているのかというところを伺って、ここの条例の中で見てみたいなと思っているので、幾つか聞きたいと思います。以上、現状のところを教えてください。","respondent":"伊崎子育て支援課長","answer":"全学年通じて、前月の２０日ごろまでに翌月の出席予定表は出していただくことになっております。１・２年生につきましては、無断欠席、丸がついているのに来なかったという日につきましては、保護者のご要望によって、保護者に必ず電話をすることとしております。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"そこも含めて、１.６５だというわけですよね。子どもの命を預かっている、そういう事業ですから、やはりきちんとつかむべきだと思っているわけです。先ほどもちょっと質問が出ていましたけれども、１日の保育時間が３時間とか、８時間と出ているんですけれども、「以上」にしていないのはなぜなのかなというのが、先ほどの答弁を聞いていてもわからなかったので、そこを改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"しかし(4)番の「その他規則で定めるもの」というのは、どういうふうに読んだらいいかがわからなかったので、資格のところで一緒に教えていただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"これは、「従うべき基準」ですので、このとおり規則で定める予定ではありますが、例を申し上げますと、学校教育法の規定による大学において、社会福祉学、心理学、教育学、社会学、芸術学、もしくは体育学を専修する学科。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとその点についての認識を伺いたいと思います。それから、先ほど質問したところで答弁なかったと思うんですけれども、第１９条の開所時間と日数のところで、これは最低基準だということなんですけれども、「１日８時間」ということで、「８時間以上」としなかったのはどうしてなのかなというのを、もし理由があれば教えていただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"現状、先ほど来、課長が説明しているとおり、すまいるスクールの運営については、細かいところはいろいろ修正しつつも、保護者の要望にも応え、そして、子どもたちの健全育成にも十分機能を果たしているものだと考えていますので、まずそういう基本的な認識は。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"私は具体的なところを知りたいので、課長からの答弁を、先ほど質問した関係で、部長は総論でおっしゃったので、個別のところの答弁を伺いたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"ごめんなさい。だけど、一般的には、「以上」という言葉がついているものなんだけれども、品川区には「以上」というのをつけていないのは、どうしてなのかなという個別のことも聞きたかったので質問したんですけれども、そこも答弁はなくて、部長の話の中では、私はちょっと理解できないから、答弁してくださいと言っているんです。","respondent":"伊崎子育て支援課長","answer":"私が本文のほうを読み落としておりましたので、ご理解が難しかったかと思いますが、第１９条の条文の中に、「放課後児童健全育成事業者は、開所する時間について、次の各号に掲げる区分に応じ、それぞれ当該各号に定める時間以上を原則として」と表記してございまして。","id":"exchange-016"},{"speaker":"高橋委員","kind":"質問","question":"１つなんですけれども、第２２条の第２項に、損害賠償を事業者は行わなければならないとあるんですけれども、これは現行のすまいるスクールと同じ形なんでしょうか。","respondent":"伊崎子育て支援課長","answer":"損害賠償につきましては、今、すまいるスクールでも保険料として６５０円いただいておりまして、当然、中で起こった事故については、損害賠償の制度はとっておりますので、全く問題はございません。","id":"exchange-017"},{"speaker":"高橋委員","kind":"質問・要望","question":"費用とかではなくて、対象というか、新たに条例が定められて、いろいろな基準を区のほうで定めたので、要するに事業者がいわゆる責任を負うだけではなくて、区も負うようになるということで、契約なのか、それとも行政処分という状況が入ってきて、区のほうがやるのかという、利用者の方からすると、何か事故があったときに、すまいるスクールを運営している事業者を、言葉は悪いですけれども、訴えたり。","respondent":"伊崎子育て支援課長","answer":"こちらに規定しておりますのは、「放課後児童健全育成事業の事業者は」ということで、規定されております。当然、区の場合は、委託をしておりますが、事業主体は区です。ですので、何か事故が起きたときには、区が責任を持って対応しております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"非常に残念です。どれだけつかんでおられるか、もちろんご担当だから、もっと詳しくつかんでおられると思いますけれども、そういう状況の中で、満たされているからいいんだとはならないと思いますし、私はこの条例制定の中で、改めて学童保育クラブというのを独立した事業として行うべきだということを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"第３９号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例","agenda":"第３９号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"しかし、第２項については、間接的な保育確認義務ということなので、自治体の義務の内容とは違うということですね。それで、自治体が第２項の義務を果たしたからといって、第１項の義務が免れるわけではないと思うんですけれども、まず、この点についての区の認識を確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"この直接契約云々につきましては、確認制度、次号の第４０号議案の中で示されている内容でございまして、次の条例案の中でご審議いただく内容だと思いますけれども、国との直接契約というのが原則ですが、当分の間、市区町村が利用調整をすることという定めを置いておりますので。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"この第３９号議案も、子ども・子育て支援新制度というところなので、今のところで質問させていただきました。保育所利用に関しては、新制度でも、現在の仕組みと同じであるということ。公立でも私立でも、市町村に保育所利用の申し込みをして、保育料の徴収も市町村が行うことと国の資料でも説明されているんですけれども、その内容に違いはないかということを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"同じく、今のご質問は、第４０号議案の中で起点を置いている内容ですけれども、まず第２４条の児童福祉法の改正に伴う保育の実施責任につきましては、国の児童福祉法の改正のとおり、保育所で保育しなければならないという原則のもとに、さらに今回、家庭的保育事業と。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"なぜそんなことを言うかというと、やはり全ての子どもは等しく生活を保障され、愛護されなければいけないと児童福祉法第１条に書いてあるし、やはり平等に子どもは育つ権利があるわけですし、最低の利益が保障されなければいけないという、さまざまな規定の中で、この小規模保育、家庭的保育というものを捉えていくべきだと思いますので、その点について確認をしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長、竹田保育課長","answer":"１００％保育士というご提案でしたけれども、私どもは、既に国の説明会等でＡ型、Ｂ型、Ｃ型の保育士の割合は、それぞれ厳然に段階を違えること、割合も違えること、１つの種別ではいけないと説明を受けておりますので。認可外の保育園もすぐれた点があることをご理解いただきながら、安全・安心という共通の視点に基づいて、こういう認可外保育園も運営されていることをご説明させていただきたいと思います。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"ネットでお願いして預けたら、以前にいろいろと事故を起こした人で、そういう人だったということがわからないまま預けて、２人の兄弟のうち１人の子どもが亡くなったという、本当に痛ましい状況を解消させなければいけないということがあるので、居宅型をするのであれば、私は一定の養護施設での対応をするとか、あるいは複数の保育体制を確保するとか。","respondent":"竹田保育課長、今井制度改革・待機児童対策担当課長","answer":"先ほど、ご説明しました顔の見える保育というのは、保護者からのご意見を踏まえてご案内したものです。私ども、今、どのくらいのニーズがあるのかを含めて、関連各所と確認している途中ですので、一足飛びに、今回、居宅訪問型を実施するという計画には、まだ至っていないところです。","id":"exchange-023"},{"speaker":"南委員","kind":"確認","question":"最後に、家庭的保育事業というのは、既にもう実施しているし、品川区は拡大する方向でいますよね。そういうことをしっかり担保できるような条例にしていかなければ、つくる意味がないと思いますので、私はそういう点で、もう一度、この条例をつくるに当たって、そのあたりの品川区のベースがどういうことなのかを、ちょっと最後に確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現行、今、こういう規定を置いておりまして、事業者のほうにも、この規定で事業を進めていて、安全・安心に事業が展開できておりますので、現行の家庭的保育事業のこれらの資格要件を踏まえて、検討を進めていくという考えです。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"最低基準だから、それを上回る品川区独自の対策ということを、規則で定めるというお話なので、そこに幾らか上乗せ部分が入るのかなと期待したいと思うんですけれども、いろいろ、この条例案文を読んでみると、必ずしもそういうふうに予想ができない部分が多々あるので、私としては、一番子どもを健やかに育てるという角度で見たときに、先ほども言いましたけれども、最善の利益が確保されなければいけないし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"第４０号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例","agenda":"第４０号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"先ほど、第３９号議案のところで言った、保育の実施義務というところについて、改めて自治体の保育実施義務が維持されたということは、私としては評価していきたいと思います。しかし、第２４条の第１項と第２項の違いについて、どういうことなのかを、改めて説明をしていただきたいと思います。そのあたりのことが、実際問題、どう行われるのかということを、ちょっと説明していただきたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"手続のことですが、認定につきまして、認定と利用希望の申請という形で、２つ手続があるのではないかということですが、手続は２つですけれども、１回で手続が済むように、今、事業の手続のあり方について、国の指針なども踏まえ検討しておりますので。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"今、利用調整とおっしゃった。確かに利用調整があるわけですけれども、その利用調整というのは、いわゆる今で言う認可保育園以外のところの保育については、直接契約になるという状況になるわけですよね。そことの関係で、利用調整は、法律に触れることになるのではないかなと思うので、どう理解したらいいのかというところを聞きたかったので、そこについて、教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほどの利用調整等の考え方ですが、条文の中でも、２号認定、３号認定のお子さんにつきましては、基本的には保育の必要性が高いと認められる子どもが優先的にできるように選考するものということで、第６条の定めを申し上げました。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"それは、その条文上、正当に区がやっていいことだと考えていると判断したんですけれども、それでいいのかどうか伺います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"この第３項を受けて、運営の基準に関する条例確認制度を行っておりますので、法律の定めに従って行うものです。","id":"exchange-028"},{"speaker":"南委員","kind":"確認","question":"そういうふうに区が考えているということはわかりましたけれども、また本人が保育を申請する際に、今は第６希望まで書いていただいているけれども、そこのところに、いわゆる家庭的保育だとか、認定子ども園だとか、そういうところを記載したら、それはそれでわからなくもないんだけれども、全く個人的な契約をする、あそこの保育園に行きたいんだという希望を持っている場合に。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちらの施設の「利用調整」という言葉ですけれども、あくまでも、先ほどからご説明していますとおり、保護者の申請に基づいて、それを記載していただいた施設や事業に利用調整をするです。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"今、一生懸命、品川区は、それでも私立、企業型の保育所、認可保育園をつくっているし、来年度も何カ所かやるということは、資料でも、プレス発表でも承知していますけれども、認可保育園だから、もちろん株式会社だって認可保育園なんだけれども、いわゆる私たちがずっとこの間言ってきた、区立の認可保育園に入りたい、その希望は利用調整で家庭的保育、あるいは小規模保育。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"私が質問していることに対して、委員長が制止させるみたいな、そういうことはやっていただきたくないと思います。しているつもりです。だけれども、この中に書かれている条文は、私が思っているような内容で、そういうふうに理解していいのかどうかというところをしっかり見極めなければ、賛成も反対もできないではないですか。やめていただきたいと思います。答弁をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"利用調整と認定が違うことは知っています。書いていないものについては、利用調整の対象にはならないから、やらないということなんだけれども、一番入りたい認可保育園に入れなかった場合、言い方は悪いですけれども、窓口での水際作戦ということで、この人はこうですね、この人はここですねということはしないんでしょうということを確認したいんです。それがわかればいいです。終わりにしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"実際の入所選考の段階で、窓口等で、例えば、ここの園がどのくらいの申込者数が多かったかなどのご質問にはお答えして、対応しておりますが、この園のほうがよいという形での窓口での利用調整はいたしておりません。客観的な事実に基づいて、情報提供をしております。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"２つあって、１つは第１５条のほうで、特定教育・保育の取り扱い指針のところで、それに応じて幾つか適用していかなければいけない、現在の区の施設はあるのでしょうか。今後、それを適用する、例えば二葉保育園とか台場保育園とかは、どうなるんでしょうか。それから、第５条の重要事項についてなんですけれども、重要事項を決めて、それを説明して、同意を得ると。","respondent":"今井制度改革・待機児童対策担当課長","answer":"初めに、第１５条の特定教育・保育の取り扱い指針で、新しく幼保連携型認定子ども園の保育要領ができましたので、これは本会議でもご答弁申し上げた内容なんですけれども、品川区としましても、これまでの「のびのび育つしながわっこ」の改定を今年度中にして、来年度以降。","id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"既存の園へ８月、９月に説明会というところで、この重要事項、新しい条例をつくって、今回到達すれば、それに基づいた、その強制力はない可能性の施設だと思うんですけれども、重要事項について、新しく保護者、事業者の方に説明していくという、より利用者にとって詳しい情報を開示していくという仕組みをやっていかれるのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただし、現在も基本的には保護者の方に十分情報提供されている内容と、私どもは認識しておりますので、今後、細かく内容が決まりましたら、改めて周知するということで十分ではないかと考えております。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"第１３条と第４３条の保育料のところなんですけれども、上乗せ徴収とか、実費徴収とあるんですけれども、必要な、今現在でも、例えば行事のときの撮った写真は写真代で徴収するとか、そういうたぐいのものはあると思うんですけれども、上乗せ徴収とか、実費徴収というのは、例えばどういうことを具体的に考えたらいいのかというのを、１つ教えていただきたい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ただ、地域子ども・子育て支援事業の中で、実費徴収に伴う補助事業というものがありますので、今後、また地域子ども・子育て支援事業の中で、例えば生活保護センターを含めて。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"保育という性格からして、どうなのかなと思うんですけれども、その辺はどうでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"できないということではなくて、協議と承認が必要となります。そして、その他の施設、特に１号認定の子どもが通う幼稚園につきましては、一定の保護者の同意で可能だという規定がされているものです。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"今、説明を伺ったんですけれども、どういうものかというのは、イメージはできたんですけれども、園によって、それを特色として、いろいろな保育を付加したり、ちょっとある保育園では、これもやはり株式会社の保育園なんですけれども、品川区ではない、よその区なんですけれども、例えば体育の先生が何曜日の午前中に来てくれて、跳び箱の指導をしてくれたとか、これは別ですけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私立保育所については、市町村との協議により承認を受けることが必要と定められておりまして、区としましては、私どもとの協議の内容につきまして、今後検討していきたいと考えています。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"私は反対したいと思います。理由は、今言ったように、今までの保育とがらりと変わってしまうということと、それから、お金を出せばいろいろな保育を受けられる。これから、区の協議だということなんだけれども、協議をするということは、そういう申し入れを受け入れるということになるわけですから、やはりこういう点でも問題があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-05","title":"になります。第３５号議案、平成２６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"になります。第３５号議案、平成２６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"保育業務システムの改修のところで、磁気カードからＩＣカードへとなっています。最初の設置経費等がありますが、これは、通常のランニングコストはどのようになっていくのかが１つ。もう１点は、ＩＣカードは、さまざまな利便性はかなりわかってはきているんですが、トラブル時の対応、その管理などがどのような形で想定されているのか。この２点を教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"もう１点、トラブル対応なんですけれども、今回もそうなんですけれども、これまでですと、磁気カードでございましたので、入れて、出なかったりすることがございましたが、今度はＩＣカードですので、タッチして、それで料金を引き落とすという形になりますので。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問","question":"今のご説明で十分理解できました。あるいは今後、管理上、オンラインを含めてなっていくものなのか。そういう余力があるのかどうか。それによって、トラブルという中では、結構時間がかかったり、業者対応でないと難しい、自力では難しい面というのが、日々の流れがあるので、その辺の危機管理が必要なのかなと思ったので、質問をしました。お願いします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後、ＩＣカードということで、今、委員ご指摘のとおり、例えば登降園システムへの汎用ですとか、このＩＣカードを使って、門扉の開閉ですとか、改修等が必要になりますので、今後の課題だと考えておりますが、なるべく広い可能性を探って、検討を進めていきたいと考えています。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"保育のほうなんですけれども、認証保育所運営費等助成ということで、８７５万円計上という補正なんですが、先ほどの説明では、このプレス発表を見ますと、来年度に向けて、１園４０人ということなんですが、来年度に向けて１園４０人という理解でいいのかどうかと、それから、いつというのは来年度、どこにできるのかということについては、もう大体めどが立ちそうなんですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これは、認定という形で、今後、また一定、検討を進めていくものです。こちらのシステムは、全額国の１０分の１０の補助金でございまして、磁気カードから、全く新しいＩＣカードシステムに変更するです。","id":"exchange-041"},{"speaker":"南委員","kind":"確認","question":"ちょっとそこは確認したいと思うんです。確かに今の８時間、あるいは１１時間、延長保育になるというところでは、磁気カードを入れて、スムーズに事務処理も含めてしやすいようになっていると思っているんですけれども、今の現行制度をさらにプリペイドカードからＩＣカードへ変更するということで、新システムに移行するための補正予算ではないということなんですか。そこの確認をしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら、新制度への対応です。私の説明が不十分で申しわけありません。文教委員会の資料の一番下の参考例のところをご覧いただきたいと思います。原則、今後、保育標準時間は、開所時間１１時間まで利用の上限があります。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"新たに鮫浜小学校でもやられるということなので、そちらにも、その報告書は行くのか。予算の部分で、４つ挙がっていまして、そのうちの上３つは理解ができるんですが、最後の通信等運搬費というところが、金額は少ないんですけれども、ここはどういったものが予算化されているのか、もしわかれば教えていただければと思います。以上２点、よろしくお願いします。","respondent":"村尾学校支援担当課長","answer":"３点目、通信等運搬費につきましては、多分、いろいろなものを運ぶときに、どうしても交通手段が必要であったりということで、金額が載せてあるんだろうと考えています。","id":"exchange-043"},{"speaker":"高橋委員","kind":"質問","question":"ＩＣカードのほうなんですけれども、導入するということで、新制度に向けてということなんですが、来年の４月、現実的に、子ども・子育て新制度のどの部分でＩＣカードを使うんですか。そう言っていただければいいんですけれども、それとのかかわり等については、何かリンク等で検討されているところがあるのでしょうか。わかる範囲で、最後はもしかしたら所管が違うかもしれません。","respondent":"今井制度改革・待機児童対策担当課長","answer":"(3)にありますとおり、現状も幼稚園の預かり保育や、生活支援型オアシスルームにおいても磁気カードを使っているところですけれども、特に幼保一体施設等ありますので、保護者の利便性を考えますと、今回、新しいＩＣカードシステムに全て切りかえようと考えております。","id":"exchange-044"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、１つ目のところで、現状の生活支援型、預かり保育、幼稚園とか、現行のものに活用するという認識でよろしいんでしょうか。それから、もう一つは、区立ということですが、公設民営のところがあるんですが、そこは現行、その扱いはどうなるのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私立保育園につきましては、既にＩＣカード対応されているところが多あります。公設民営、ぷりすくーる西五反田につきましては、現行も預かり保育をやっていただいておりますけれども、単体で動かしているものですので、ぷりすくーる独自のシステムで今後も運用する予定です。","id":"exchange-045"},{"speaker":"南委員","kind":"確認","question":"いつの時点でと、開設時期が書いてはあるんですけれども、例えば予算書で言うと、児童措置費のところの私立保育園の運営経費で、開設準備金２園分というのは、ここのプレス発表で言うと、どこに当たって、いつオープンする予定なのかという、そのあたりをはっきりつかんでおきたいなと思っているので、ここに出ている部分を、ここでどういうふうに見るかというのを、説明していただけないでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちらの平成２６年度の待機児童対策につきましては、今年度中、保育ママの分ですけれども、５施設４５人という形で、４月当初から予定しておりましたが、それを２施設増やすので、７施設６９人という形で、今年度中に増やしてまいります。","id":"exchange-046"},{"speaker":"南委員","kind":"確認","question":"今、説明していただいたのは、ここを読めばわかる話なんですけれども、私立保育園が、例えば４園から６園に増えて、２９０人が４３０人に増えますよというのは、ここに書いてあるから、そのとおりでわかるんですけれども、その２園分というのが、予算書補正予算で見ると、この私立保育園経費２園分ということに相当すると見ていいんですかということで。","respondent":"今井制度改革・待機児童対策担当課長","answer":"その次の開設準備経費と助成は、事業所型３施設とありますが、年度途中に開設する２施設分ではなくて、プラス１施設、未定になっておりますが、平成２７年度に開設する小規模保育を補正で出しております。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"ちょっとお伺いしたいんですけれども、開設に当たり、全国的に保育士が不足しているというのをよく聞くんですけれども、そういう区での保育士の確保についてどのようにお考えか、お話を聞きたいと思います。","respondent":"竹田保育課長","answer":"今年２月にも開催したところですが、さらに今年度、あるいは来年度に向けて、今ハローワークとどういう形をとれば、潜在保育士、保育資格を持っていないけれども、保育に従事していない方々にお集まりいただいて、また、あるいは保育に従事する意欲を高め。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"その辺、もう少し突っ込んで、何か案があるとか、そういうものがありましたら、ただただハローワークとの話だけだと、どうなのかなと思います。数も数えていかなければ、こういうものは成り立っていかないので、潜在保育士の方もそうなんですけれども、まず保育士の確保ができないと思うので、その辺をもう少しだけ突っ込んでお聞きたしたいと思います。","respondent":"竹田保育課長","answer":"今、資格を持っていても、従事していない方につきましては、やはり現場復帰する際の不安というのがあると思いますので、現場に復帰するに当たっての不安を解消するような相談、あるいは研修等、心の不安を解消するようなものを何かご用意できないかと検討していると同時に。","id":"exchange-049"},{"speaker":"南委員","kind":"意見","question":"私は、来年度実施する子ども・子育て新システムの改修経費だということで、これについては、先ほども午前中、態度を表明したんですけれども、関連するということで、ここは反対をしたいと思います。そのほかの部分については、インクルーシブ教育も含めて、保育園の増設の待機児対策に、そういう点でも、ここは賛成するものでありますけれども、反対という態度です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"}]},{"id":"topic-06","title":"平成２６年請願第５号、認可保育園増設と保育の質の向上を新制度施行後も区の責任で行うことを求める請願","agenda":"平成２６年請願第５号、認可保育園増設と保育の質の向上を新制度施行後も区の責任で行うことを求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"先ほどの補正予算でやった、これだけの施設をつくる努力はしているけれども、来年度、あるいは今年年度途中に引き続き申請された方たちが、どのくらい入れるかというと、申し込まれる方たちの、今のところの数字はどういう状況かわからないですけれども、その辺を見て、今年６月に３カ所、認証保育所がオープンしたとか、いろいろありますけれども、そういうところで対応されていけると見込んでいるんですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後も、そのような状況も踏まえまして、ただ１点、やはり待機児童数は増えてはいるものの、実際の保育需要自体が、当初より予想は遅れているものの、いずれピークを迎えるということがありますので、そのピークの需要も踏まえながら、区としては整備に取り組んで、積極的な。","id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"それで、今年度、これからも含めて申請される方には、対応できるんですか。そういう見通しを持っているんですかと聞いたんですけれども、そこについては答弁がありませんでした。億の単位でかかることは事実です。だからつくろうとしないのか、ちょっとそこをもう一回伺いたいのと、ちょっと忘れてしまった。もう一回思い出しますけれども、とりあえずそこまで、質問をお願いしたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"やはり待機児童の根幹はゼロ歳から２歳の子ですので、やはりここに早急な対応が必要と考えておりますので、補正をいたしたところです。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そこはもっと柔軟に、区のほうで考えるべきだと思うし、いろいろな行政需要に対応していけるには、そういう柔軟性がないとだめだと思いますので、むしろそういう捉え方をして、一定の期間限定でもいいからやるべきだと思うし、そういう姿勢を持っているからこそ、私たちはいろいろ意見はあるけれども、南品川４丁目には、３０年の定期借地ということで、私立の保育園を開設してもらうように働きかけをした。","respondent":"今井制度改革・待機児童対策担当課長","answer":"子育て費用の件と、今後の柔軟な対応です。","id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"もっとしっかりとキャパを広げて当たるべきだと思うんですね。そういう穴埋め的という言い方をしたら誤解されるかもしれないけれども、一定の期間でもいいから、受け入れるためには、しっかり区がフォローしていくということを含めて、検討していただきたいと思っているんですけれども、その点についてだけ、１点だけ最後に伺いたいと思います。","respondent":"金子子ども未来事業部長","answer":"私どもとしては、先ほど申し上げたとおり、平成２２年以来、３,０００人近くの受け入れ枠の拡大をしてまいりました。これは、従前から比べると、倍以上の数字になっております。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問・要望","question":"自民党は、結論を出すということでお願いします。自民党といたしまして、今お話がありました待機児童解消については、これまでも強く行政に要望をし、それに対して、行政のほうも、先ほど説明がありましたように、さまざまな方法で応えていると考えております。そういった点から、この項目、それぞれ対処されている面、あるいは難しい面というのを総合的に判断して、願意に沿いがたいという理由になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"つる委員","kind":"質問・要望","question":"その理由は、各質疑をする中で確認をした部分と、公明党としても、当然、待機児童対策、これは強力に推進してきたところもありますし、またそれに応えて、区も今の財政状況の中で、また人口動向、人口のピーク、こうしたものも含めて、鋭意努力されながら、計画の中で実証されている、そういう認識でおります。これは、私はそういう認識ではおりませんので、これも大きな不採択の理由の１つになっております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々としても結論を出すということで、態度としては不採択であります。もう既にお話がありました、私どもも、もちろん待機児童対策というのは、ぜひともその解消に向けて取り組んでいただきたいという思いは、さんざん、ことある場面において、行政に働きかけをしてまいりました。そういったことから、不採択ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ、４番の園庭のない保育園というのが、あるところもありますけれども、民間企業の設立している保育園の大半に園庭がない。それから、小規模保育についても、先ほど午前中、私も言いましたけれども、有資格者が全員ではないという事実も、資格を持っていない方は、それを選んで仕事をされるわけですから、もちろん熱意はありますよね。ですから、そういうのをやめてくれと要求しておられる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"吉田委員","kind":"意見","question":"結論を出したいと思います。待機児童対策に関して言いますと、さまざまな方法を品川区はとっておりますけれども、先ほども出ましたが、区立、認可にこだわらず、いろいろな施策をとって、新制度導入に関して、格差についてはないのではないかと思いますので、これからも、これは重く受けとめて進めていく問題だと思いますが、その格差に関して、私のほうでは、そういう意味で不採択ということにしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"高橋委員","kind":"質問・要望","question":"結論を出すということで、願意に沿いがたいということです。不採択です。自治体の責任、区の責任としては、新制度のもとでも自治体独自の責任があり、さらに指導監督という面もありますので、その責任を果たすという面においては、今後もさまざまな問題が起きないように、しっかり進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"今の図書館長の説明の２番の(3)については、私は初めて伺ったのですが、改めて、もう少し詳しく教えていただきたいと思うんですけれども、芳水小学校の改築計画というのは、いつごろ具体的にこういうふうに文章になったのか、これからどのような日程で改築計画がされるのかというのが１つです。その辺についても伺いたいと思います。","respondent":"田村教育次長、中元品川図書館長、柏原行財政改革担当課長","answer":"庶務課長の事務取扱をしているものですから、私のほうから。２の(3)の芳水小学校についての経過をご説明します。私から２点目のご質問の、地域の住民の方への図書館の思いとの関係ですが、私どももそこのところは、先ほどのご説明でも申し上げましたが。こういった中で、品川区といたしましても、大崎図書館移転の後、どういった形がよろしいのかというのは、内部でも検討していたところですけれども。","id":"exchange-061"},{"speaker":"南委員","kind":"確認","question":"最後からいきますけれども、はっきりおっしゃらなかったんですけれども、当該施設というのは、大崎幼稚園ということで考えていいんですかというのが１つ。これは、東京都が打診してきたという話なんですけれども、東京都が大崎幼稚園の代替施設として、区の土地活用はできないかという打診を受けて、品川区としては、ではどこがいいかということで、数百メートルぐらいですかね。","respondent":"柏原行財政改革担当課長","answer":"計画道路関連のお話ですけれども、当該施設は大崎幼稚園です。大崎図書館の移転の話が、我々としては検討していた。これが１つ。そちらのほうを検討していたといったところです。それで、そういった内容についても、行財政改革特別委員会等でご報告を申し上げたところです。","id":"exchange-062"},{"speaker":"渡辺委員","kind":"質問","question":"取次サービスのことで伺いたいと思います。１５０平米で、かなりな敷地と想像はできるんですが、これまで取次サービスをした実績、大崎でもされていましたし、近隣で、近年という言い方がいいですかね。取次サービスで、かなりな区民の皆さんのニーズに応えているのではないかと、うろ覚えなんですが、かなりな数字があったかと思います。近い時期の、あるいは近い場所での実績などを、まず教えてください。","respondent":"中元品川図書館長","answer":"渡辺委員、取次サービスは、大井町と武蔵小山になります。直近で、平成２４年度１年間で、個人貸出が、大井町が７万３,９０７冊、武蔵小山が、少し少ないんですけれども、５万７,６７６冊という状況です。","id":"exchange-063"},{"speaker":"渡辺委員","kind":"確認","question":"ありがとうございました。月割りにしても、相当な数かと思われます。そういう意味では、聞き方はなんですが、大崎図書館の歴史については、十分経緯を配慮されているがゆえに、あるいは現在の利用者動向を踏まえて、大崎駅西口であり、学校の計画の中で２カ所と行き着いたのか、その確認。考え方を教えてください。","respondent":"中元品川図書館長","answer":"おっしゃるとおりです。特に大崎駅前は、今、りんかい線等も乗り入れて、大変便利な駅前の拠点となっていますので、そういうところもありますし、また学校の、もう少し駅から離れているところもありますので、逆に住宅街の方のニーズに応えられるものだと考えているところです。","id":"exchange-064"},{"speaker":"つる委員","kind":"質問","question":"１つが、請願第１０号の題名に、「実質廃館」という表現があるんですけれども、今の説明とか、議論を含めて考えると、「大崎図書館の移転について」の用紙の２の(1)を見ると、御殿山小学校の西側敷地内に移転とあるわけで、エリア的にはいわゆる大崎というエリアになるのか、名称もそうなんですが、ここは、大崎図書館の、いわゆる実質廃館に該当するのかどうか。これをちょっと教えてください。","respondent":"中元品川図書館長","answer":"あくまで移転です。廃館ではございません。","id":"exchange-065"},{"speaker":"つる委員","kind":"確認","question":"そこが１つ確認できたので、どうもいろいろお聞きしていると、あくまでも移転。１つ、その中で、まず確認したいのが、先ほどご説明の中で、口頭で「同等の面積」という表現があって、今の図書館に蔵書されている書籍のたぐいですよね。これが、基本的には全て新しいほうに、予定されているところに行くということでいいのかどうか。これを確認したいと思います。","respondent":"中元品川図書館長","answer":"全て新しいところに持っていくことができます。","id":"exchange-066"},{"speaker":"つる委員","kind":"質問","question":"多少、そうした機会を通じて、書籍の状態に応じて、いろいろな対応というのはあるんでしょうけれども、基本はそれである。そういう意味からも、書籍の蔵書のあり方もそうなんですけれども、図書館の配置の権益みたいなものというのは、図書館法といったものの中で、どういうエリアに１つずつあるという決まりは、そもそもあったのかどうか。これを教えてください。","respondent":"中元品川図書館長","answer":"特に法律上の決まりというものはございません。ただ、品川区といたしまして、方針、配置基準が、大分昔になるんですが、決めてございまして、大体５００メートル圏内に１館ぐらいを目標に、順番に館を建ててきたという経緯はあります。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問","question":"そういう意味で、どうしてもさまざまな状況、先ほど、図書館の施設そのものが３０年以上経過しているという中で、取次の場所を設けるというところにあっては、当然、私個人的には、直接書籍に触れるワンストップというんでしょうか、１カ所で書籍を見ながら、その本を借りて、その場で借りられるというのが一番美しいなとは思っているんですが、ただ、直接欲しい本、探されている本が。","respondent":"中元品川図書館長、田村教育次長","answer":"大崎駅西口の新しい１５０平米の面積ですが、駅の中ではございませんが、駅から本当に歩いてすぐの再開発ビルの中の一角を提供していただける予定になってあります。そうすると、改築した新築校には、当然、メディアセンターと学校図書館の機能を設ける予定です。ですから、そことうまく連結して、大崎図書館の取次サービスと、一般の方が来て閲覧できるスペースを確保しようと。","id":"exchange-068"},{"speaker":"南委員","kind":"質問・要望","question":"あります。ごめんなさい。改めて、大崎図書館が御殿山小学校隣に移転した場合に、何メートルぐらい離れているのかという距離を教えていただきたいと思います。それから、現在の大崎図書館の貸出数は何冊ぐらいなのか。それは、図書館としてはどういう評価をしていらっしゃるかということです。いつごろ一般図書の部分も移転することになったのか。その時期について、教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"初めに、移転先までの距離ですが、約７５０メートルです。現在の大崎図書館の貸し出しの状況ですが、個人貸出が３５万１,３８０冊です。こちらは、ビジネス支援図書館を含めての数字です。これは区内１０館の中では、平成２５年度の数字ですが、５番目になります。","id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"品川区のいろいろな図書が非常に区民の皆さんから利用が高まっているという事実は、３５万冊で５位というところですから、全体的にずっと上がっているというところはあるのかなと思うんですけれども、それにしても、わずか数年の間で、順番的には５位だけれども、冊数が増えているという事実は、地域の方々に本当に利用されている施設だということを、そこはしっかり見ておかなければいけないと思うんですね。","respondent":"中元品川図書館長、柏原行財政改革担当課長","answer":"そこを何とか対応を立てるためにも、ずっと区の中で検討してまいり、これで新しいところに行くことで、無事、現在の書庫、区全体で１００万冊の蔵書を維持できるというところで、大変移転としては前向きに捉えているところです。時期ですけれども、こちらは我々が案として検討していたですので、一定程度の流れで考えておりましたのは、昨年の秋から冬といったところです。","id":"exchange-070"},{"speaker":"南委員","kind":"意見","question":"最後にします。２７万冊と訂正されて、順番も訂正されたんですけれども、２１万冊から比較しても、数年後に６万冊増えているという、やはりそれだけ親しまれて、利用度の高い地域なんだということは事実だと思うんですね。したがって、そういうところを設備的には老朽化したり、地下のところがいろいろというところはあったんだけれども、修復をきちんとして使っていけば、できるのではないかと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる図書館に来て、本をとって、そこで読んで返すという仕組みというのは、そのまま継続というか、閲覧コーナーで可能になるのかというのを、そこだけちょっと教えてください。","respondent":"中元品川図書館長","answer":"そこで借りて、そこで読める席を用意して、また逆に、ある程度面積、配置とかが見えてまいりましたら、少し書棚とかも置ける限り用意させていただいて、その場で皆様がご興味ありそうなものをそろえたりという形で、閲覧コーナーということで考えております。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問","question":"２点、お願いします。それから、芳水小学校に区内初めてのサービスということで、私は地域とのつながりという意味で、新しい試みでいいのかなと思うんですけれども、先ほどセキュリティーもあるということもありましたが、その辺のお考えをお聞きしたい。２点、お願いします。","respondent":"中元品川図書館長","answer":"それと、また地域との芳水小学校内で図書コーナーができた場合の想定ですけれども、保幼小交流事業とかに力を入れて品川区の教育でやっているところですので、地域の小さいお子さま連れの方々に来ていただいたり、また時間帯によっては。","id":"exchange-073"},{"speaker":"渡辺委員","kind":"確認","question":"結論を出すということでお願いします。結論については、趣旨採択が望ましいと考えております。理由につきましては、ただいまの議論の中で、改めて確認できたこと。それが、まず１点です。移転の後の現在地、歴史的な経緯や地域への経緯を十分行政が理解をして、踏まえた上で、サービスコーナーや閲覧コーナー、ここに行き着いているということが、今日の確認で一番大きなところだったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"つる委員","kind":"質問・要望","question":"結論を出すということです。態度が、趣旨採択ということにします。結論の部分を先に申し上げますと、請願の最後からの１行のところです。大きい部分では、移設に反対という中で、「もしくは」という、本日お配りいただいた資料、それから、本日の議論の中で、先ほど私のほうからも質問させていただいて、確認させていただいたことも踏まえると、私としては、第８号につきましては、趣旨採択と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"石田（し）委員","kind":"意見","question":"我が会派としては、まずは結論を出す。理由としては、第８号議案を見させていただいて、本当に歴史的背景や地元の皆さんの思いというのは、十分理解させていただきました。しかし、一番最後の行に、「大崎西口に、代替えとなる施設の設立」という部分が地元から出ていまして、これについて、地元の思いというのがあらわれているのかなと思いますので、あえて趣旨の採択とさせていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"南委員","kind":"質問・要望","question":"というのは、最後のこの１文が、開発のところにオープンするということをもって、地元の方々の前段で述べておられる切々たる思いが、ここでぐっと全然異質の文章になっているので、私たちとしてはどちらをしっかり受けとめたほうがいいのかという点で悩みました。最後におっしゃっていた地下の書庫は、全取りかえだったら２,０００万円かかると。トイレなんかも、洋式が１カ所しかないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"結論を出します。態度としましては、趣旨採択で。理由といたしましては、先ほども課長のほうから老朽化が激しいということ。芳水小学校に関しては、新しい試みで、これは大変いい方向に向いていっていただいて、歴史的な図書館が地域に根づいておりますので、地域の方々との交流の場にもなっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"高橋委員","kind":"意見","question":"でも、その一方で、請願書の中には、子どもたちが放課後使っていた、あるいは地域の方が使っていたという部分があって、それについては、この請願書の最後の部分で「代替えの施設」という部分がありまして、閲覧コーナーについての取次サービスという説明をいただき、特に閲覧コーナーの中には、つくるということで、いろいろな試みがあると思うんですが、ここにも歴史的な経緯と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"渡辺委員","kind":"意見","question":"そしてまた、もう一つの大きなポイントは、現所在地に対して、歴史的なもの、あるいは地域の方々への最大限の配慮を行政が理解をし、今後の方向性を、今日現在でかなり明示されたというところから、これが大きな２つのポイントだと思います。請願項目のところも、移転に反対して、移転をしないというところ、１点のみという点から、先ほどの審議からは、願意に沿いがたく、不採択という理由になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"つる委員","kind":"確認","question":"先ほど、質問の中で確認させていただいたところが大きな理由です。「実質廃館」が請願の表題のところにあると言いましたが、品川区の方向性としては、御殿山小学校西側敷地内に移転ということで確認ができました。利用者の声というのは、なかなか移転そのものにはないかもしれませんが、それを含んだところの日常の中で行っているところも、一応確認ができました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"石田（し）委員","kind":"意見","question":"結論を出すで、態度としては、不採択ということでお願いしたいと思います。理由としては、先ほど第８号議案でもお話をいたしましたが、総合的に考えると、やはり移転もいたし方ないのかなと思います。しかしながら、その一方で地域の声も酌んで、サービスコーナー等も設置される予定ということであります。先ほども出ていました。そういったことからも不採択ということであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"南委員","kind":"意見","question":"私は採択を主張したいと思います。それで、採択を主張したいと思います。それに、議会がどういうふうにかかわっていくかということだと思いますので、「実質廃館」という言葉があまりあれかなと思ったときには、請願者に直接尋ねてみるとか、そういう質疑をする前の議員としての態度のとり方、状況の調査ということも大事なのかなと、私は思います。ちょっと意見を述べて、賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問・要望","question":"結論を出したいと思います。願意に沿いがたく、不採択とします。理由は、実質廃館ではなく、移転は仕方がない。このお嬢さんですかね、ベビーカーでいらっしゃる方も、芳水小学校の移転先に行っていただいて、次に小学校に上がるために、つながるために、１つでも、２つでもプラスにしていただいて、そういう気持ちで図書館も新たに親しんでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"高橋委員","kind":"質問","question":"結論を出すということです。不採択ということです。先ほどとちょっと重なりますが、移転に関する経緯については、議論の中でお伺いさせていただきました。問題は、その後だと思うんですが、やはり地域の方々の声を酌んだ、その後の体制をきちんとつくっていって、うまくその後に問題が起きないように努力したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"}]},{"id":"topic-07","title":"報告第１８号、専決処分の報告","agenda":"報告第１８号、専決処分の報告","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"不勉強で申しわけないんですけれども、１点、確認させていただきたいのが、督促をしに行くとき、例えば裏面でも、借りている方と、保証人といると思うんですが、まず初めに督促に行くのは、もちろん借りている方に行って、その後、その方から何もないと、保証人に行くと思うんですが、そのやり方でいいのかどうかというのを教えていただきたいと思います。","respondent":"福島青少年育成課長","answer":"そのとおりです。は本人のみです。連帯保証人に行くのは、本人からの返還がない場合です。","id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、一番最後、訴えの提起のところに、「連絡のない者に対し」ということで、これは、要は借りられていた方、また保証人、両方とも連絡がないので、訴えを起こすという理解でいいのか。その方たちというのは、例えば住所が不定というか、わからなくなっているのではなく、明らかにそこにいるのを区としては把握していて、連絡をとっているが、とれないという認識でいいのか。その辺を教えてください。","respondent":"福島青少年育成課長","answer":"ただし、この裏にもありますように、所在不明の方ですとか、裁判を起こした段階で住所が移転していることが判明したりですとか、そういうケースはありますが、それはそのときにまた調べてというもので、常に新しい住所を区としては調べているところです。","id":"exchange-087"},{"speaker":"石田（し）委員","kind":"質問","question":"これで最後にします。そうすると、３８５件のうち、品川区、もしくは近隣に住んでいない方に関しては、アクションを区としては起こしていないという認識なのか、それとも何らかの電話等で連絡をとっているのか。その辺をもう一度教えていただければと思います。","respondent":"福島青少年育成課長","answer":"１番にありますように、この３８５件につきましては、まず本人に対して督促をする。その後、返事がない場合は、連帯保証人も含めて、秋ごろに督促を実施するという形で、本人に対しては２回行っています。これについては、文書で全部行っているというものです。","id":"exchange-088"},{"speaker":"高橋委員","kind":"質問","question":"時々こういう専決の訴えの話が出てくるんですけれども、これは弁護士が督促したのが７月３１日で、５月１６日までに何らかの期限を切って、こうして専決で訴えるという、何かあらかじめルールを決めておいて、それでここで訴えを提起されたんでしょうか。","respondent":"福島青少年育成課長","answer":"去年の７月３１日に督促をしまして、それから、大体半年ぐらいを見ているんですけれども、全く返事がないもの。その中で、住所が確実にわかっている者ですとか、そういうことを懸案しまして、この１３件が訴えるのに妥当だろうということもありまして、今回、訴えてあります。","id":"exchange-089"},{"speaker":"南委員","kind":"確認","question":"今の説明を聞いていて、たしか近くは直接訪ねていくけれども、近隣の県は訪ねていかないで郵送だという説明でしたよね。ごめんなさい。それが違ったら訂正なんですけれども、確認を。","respondent":"福島青少年育成課長","answer":"品川区内および近隣には訪ねていきますけれども、それより離れているところは行けないと。行きましても、必ずしも会えるとは限りませんので、ポストに投函してくるですとか、そういう形でなかなか返事がもらえないケースも多々あります。","id":"exchange-090"},{"speaker":"南委員","kind":"質問","question":"いろいろやってもだめだから、仕方がなく弁護士なんだという話なんだけれども、それで裁判にかけて和解したという報告もいただいていますよね。やはり罪人ではないですから、そこはしっかりと理解してもらえるように、人間と人間の話し合いでしていくべきなんだろうと思うので、その辺をもう一度伺っておきたいと思います。","respondent":"福島青少年育成課長","answer":"ここにも書いてありますけれども、何度も督促をして、一切返事がない。さらに、弁護士による督促のときは、これ以上何もないと訴えますよという警告もしています。それでも一切返事がなかったということで、今回、訴えをさせていただきました。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/974009?Template=document&Id=4826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":88495,"voices":329}},{"id":"h26-20140630-5","meetingId":"h26-cm06","date":"2014年6月30日","dateIso":"2014-06-30","committee":"総務委員会","time":"午前１０時００分～午後２時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","topics":[{"id":"topic-01","title":"の順番では、(1)第３６号議案 職員の配偶者同行休業に関する条例でありますが、本日は、先に(3)第５０号議案 土地の取得","agenda":"の順番では、(1)第３６号議案 職員の配偶者同行休業に関する条例でありますが、本日は、先に(3)第５０号議案 土地の取得","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"３カ年で取得するということですけれども、具体的にこの土地を議決を経て取得しました。それからすぐ工事というのは着工するものなのか、どれぐらいであそこが整理されるのかだけお聞かせください。５０億４,９００万円の中の内訳、国やいろいろの補助金が入ると思いますけれども、その内訳だけ教えてください。","respondent":"多並公園課長、立川経理課長","answer":"ＪＴ跡地しながわ中央公園の拡張整備につきましては、まずは工期としては今年度、本日ご覧いただいた入り口から左側のほう、西側になるのですが、東急線のほうです、あちらの擁壁がかなり老朽化が激しいということで、今年度。私から、取得価格の内訳についてご説明いたします。土地代金につきましては、４９億１,０６８万８,１５０円です。残りの分が借入に係る利子の支出といたしまして、１億３,８３１万１,８５０円を予定しています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、今後３年かけて東急線のほうから工事をしていくというお話がありましたけれども、今までもヘリポートにするとか、防災公園にする、そういう計画はありましたけれども、こういう形で進めますというのは、今、コンクリートされたのか、それとも、まだスタンドパイプ用の練習場をつくってほしいと、いろいろ要求が上がっているだけに、議会であったり、住民であったり。","respondent":"立川経理課長、多並公園課長","answer":"取得価格の決定までについてご説明します。品川区では、品川区財産価格審議会に対して土地の価格についての諮問をいたしました。それが平成２５年１月３１日です。私からは、住民説明会等についてお答えします。ＪＴ跡地につきましては、昨年度、まずは７月に暫定整理をするための説明会を行いました。今のような形にするという前の説明会です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明については、区議会にも適宜報告いただきたい、そういった要望をしておきたいと思います。もう一つ、土地の購入に関する基本的な考えについて、まちづくり基本構想や、計画や、公有地活用プランや、マスタープランや、いろいろ区の計画がありますけれども、土地を購入するに至ったその経過を改めて伺いたいと思ったのです。","respondent":"河内用地担当課長","answer":"これは何かといいますと、一般会計で予算組みをいたしますと、非常に優良な土地の足は非常に速うありますので、用地を押さえることができないということで、行政の中に別法人を設けまして、それで機動的な用地買収をするという趣旨のものです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"意見","question":"わかりました。最後にもう一点だけ。当初は一括で購入しようと思ったけれども、東京都から話があって３カ年だという、その東京都はどういう事情によってそういうことになったのか。だからといって、あれは一体的な一つの大きい公園として整備していくという、そこの関係、そこをご説明いただけますか。","respondent":"多並公園課長","answer":"その際に、今回、かなり大きな金額の４９億円の土地の規模ですので、東京都といろいろ詰めた中では、各区で要望がある東京都の中で、まずは全体的に限りある予算ですけれども、その中でかなり額が大きいというところがあり、ほかの区とのバランスを見た中では。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"今の話の関連ですが、３カ年ということになりますけれども、ＪＴとの契約は実際どういう形になりますか。一括になっていたのか、３年で、いろいろなこちらの事情でなっていると思いますけれども、ここはどういうふうになっているのか教えてください。","respondent":"河内用地担当課長","answer":"お金の支払いにつきましては、ＪＴには一括して銀行にお支払いしておりますので、あとは区と品川区土地開発公社のお金の受け渡しになりますので、ＪＴは直接関連しないです。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"このかかる費用もこの価格に含まれているのか、含まれていないのか、そこら辺をまず教えてほしいと思います。それから、もう一つ教えてほしいのは、これは例えばよく学校や公園などでもあるけれども、補助金が入って取得するといったときに、何年ぐらいの拘束力というか、縛りが出てしまうのか。ほかに転用しようと思っても、できるのか、できないのか、そこら辺の部分を教えてほしいと思います。","respondent":"河内用地担当課長、多並公園課長、立川経理課長","answer":"土地の価格算定の件です。今、手持ちにある資料は、平成２６年５月１日付で同地の品川区財産価格審議会の資料がありますので、そちらでご説明します。補助金の関係ですが、この補助金自体が都市公園についてかかるものですので、前提は公園がなくならないこと、保全をかけたものが基本ですので、今。それ以外の費用ですが、あくまでもこの５０億４,９００万円につきましては、土地の取得原価プラス利息となっております。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"評価額のところはよくわからないけれども、いいです。わかりましたと言っておきます。だから、期限の、按分の年数があるはずだと思っていたのだけれども、そういう按分方式もないのでしょうか。","respondent":"多並公園課長","answer":"もし廃止する場合にも、同等の土地を隣もしくはその近くに設けなければ、要は変更ですね、そういう形しかできないということですので、その廃止自体ができないという性格の、公園となった場合ですね、そういうものの施設なので。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、私の言い方が悪かったのだけれども、そうすると、それをもし転用する場合が区の判断としてあった場合は、今言った全額を返さなければならないという理解をしておいたほうがいいのですかということです。それには返すには、按分で年数があったのではないのかと私は思っていたのが、違ったのなら違ったで、全額返せば、補助金を全額返すわけだから、それは転用はできるという理解でいいのか。","respondent":"多並公園課長","answer":"私の説明が、申しわけございません。公園を廃止というか、なくすこと自体ができません。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話だと公園で、どこか近所といってもそんなに簡単にはないのだから、そうすると、何もあそこは公園としてコンクリート、将来、半永久的にと言っていいのか、言葉の選び方は難しいけれども、公園としてしか使わないというのが区の感覚なのですかという質問です。","respondent":"桑村企画部長","answer":"実際上、３０年たってどうしても区のほうで転用せざるを得ない、それが国との間でやむを得ないものとなれば、一定の考え方がありますから、土地の値段はそういう意味では整備と違って落ちていかないという状態ですので。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"確認","question":"今の話の継続のような話になってしまいますけれども、以前、総務委員会だったか、行財政改革特別委員会だったか、何の委員会だったか忘れましたが、同じような用地の転用の話で、一旦１０年ぐらいたてば、用途変更というか、目的を変えて使うことはあり得るというような話を理事者の方に聞いたことがありますけれども、それと今のお話との整合性は、公園というものはそういう性格のものなのか。","respondent":"桑村企画部長","answer":"例えば区営住宅みたいなものを入れれば、その建物の転嫁のものがありますので、簡単にはこれも認められないと思いますけれども、建物は例えば５０年とすれば、一定の５０年という縛りがあるでしょうし、一種の広場みたいな形で入れているものについての用地でしたら。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"しながわ中央公園の拡張用地として取得するということですので、賛成はいたしますが、住民要望の強い特別養護老人ホームや、保育園や、障がい者施設など、全てを公園に充てるというのは、そういう住民要望が強いということは伝えておきたいと思います。今回、都市計画公園として強い縛りのある公共性も、もちろん空地必要時には防災的にも寄与するスペースになることは事実ですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"第３６号議案 職員の配偶者同行休業に関する条例","agenda":"第３６号議案 職員の配偶者同行休業に関する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"つまり、この理由、配偶者外国滞在事由に外国での勤務、外国での事業経営や個人が業としての活動、大学等における修学、その他もろもろありますけれども、社会的背景はどういうものを認め、保障するのが趣旨なのかというところを伺いたいと思います。それと、労働組合との交渉の結果はどうだったのか、ここも確認の上でご説明いただきたいと思います。","respondent":"堀越人事課長","answer":"そういう意味で、要望が出ていたということがあります。それから、内容を認めるのかですが、継続的な勤務ということです。家庭生活との両立を支援するとともに、中長期的な視点で人材を確保していくことを目的としているものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"最初にいわば人事課の判断になるのか、自分の上司になる課長の判断なのか、もちろんそれは区長なのかもしれませんけれども、その辺の運用のところがどういう仕組みになるのか、この制度の趣旨を活かした運用はどういう仕組みになるのか、そこも１点伺いたいと思います。","respondent":"堀越人事課長","answer":"背景、趣旨としてどうやっていくかということで、もちろんその職員の業務の内容ですとか業務分担の変更ですとかがありますので、そういうのを考えながら決めていくという形です。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"次に、承認の要件の中に「公務に支障がない」と書いてありますけれども、これはどういうところでの支障がないという、誰がどういうふうに決めていて、どういうことを想定して、この場合だったらいいとか、何かそういう規約、区としての具体的にイメージされているものがあるのかどうかをお聞きしたいと思います。","respondent":"堀越人事課長","answer":"今のところ、特に個別のケースというふうな形で出てきているわけではございませんけれども、そういった、今申し上げました業務の内容、それから業務量、責任の度合いですとか、それがその後の変更ですとか職員の配置替え等を総合的に勘案しながら決定していく、それが考え方です。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"３年過ぎて帰ってきましたという場合に、その方の対応はどういう考え方をもってするのか。それから交渉相手です。どなたにどういうふうに交渉していったらいいのか。結局、この対象者は、外国に行かれたときに働いてはいけないということなのですか。例えば、時間があったり、いろいろなところで現地の中で社会的な視野を広める意味も含めて、何かしらの就労に従事することは可能なのでしょうか。","respondent":"堀越人事課長","answer":"ただ、いろいろな部分を考えながら、できる限り努めて中長期的な人材の確保に努めたいというのが基本的な考え方ですので、戻ってきてからというところはありますけれども、そのときの３年という期間がありますので、人事異動ですので。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問","question":"２点だけ教えてください。国家公務員は平成２５年１１月にやっているけれども、どれぐらいの希望者が出てくるものなのか。では、これを品川区がやったときに、品川区は感覚として１年に１人いるという感覚なのか、何年に１人ぐらいと思っているのかという、その感覚も、この制度ができたとして、そこの感覚を教えてほしかったです。","respondent":"堀越人事課長","answer":"一つ目の考え方ですけれども、今、人事院の調査では、民間企業では導入されているところが大手企業が中心で、全体としては１％程度だと聞いています。したがいまして、公務員が導入されることで民間企業に波及効果を狙っているというのが考えられます。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"片や国家公務員のほうでこういう配偶者同行休業制度を導入していくと、民間と公務員、国家公務員との格差みたいなものがだんだん出てきてしまうのではないかという感じもするのですが、では、これは休んでいても身分を保障するというような形が果たしていいのかどうかは、非常に疑問に思うのですが、そこら辺、再度お聞きしますけれども、民間がそれほど導入していない。","respondent":"堀越人事課長","answer":"そういう考え方に基づいて、公務員が率先して行っていくという考え方、繰り返しになりますけれども、そのような考え方で、先ほどの人数的な部分ですけれども、私どもは、この休業の実際の承認が出た場合といたしましても、職員の配置替え。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"一言だけ。今、若者の話もありましたが、現在、親の介護とか看護で実際に離職している、退職している方もいるわけです。片やそういう一面があって、片やこういうふうに配偶者同行休業制度を設けるのは、何かアンバランスな気もいたしますということは申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言確認したかったのは、基本的に区としてはできるだけ認めていきたいと。これができた法律の背景の、まずは国家公務員、地方公務員から実施することで波及効果を狙っていきたいというところの思いを確認したいと思っていたのです。それを一般的に説明するのも難しいと思いつつも、そこの制度の姿勢を改めてご説明いただきたいと思います。","respondent":"堀越人事課長","answer":"今ご質問いただきましたけれども、先ほどの背景の部分でもご説明させていただきました。今まで女性の方が配偶者の外国勤務に伴って活躍の機会が制限されていたことをなくしまして、より活躍していただく機会を拡大するです。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いろいろご説明を聞いた中で、要望になると思いますが、こういった条例を制定する以上は、この条例がしっかり運用できる形をとっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"第４９号議案 荏原文化センター・図書館耐震改修および大規模改修機械設備工事請負契約","agenda":"第４９号議案 荏原文化センター・図書館耐震改修および大規模改修機械設備工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"荏原文化センターの耐震とか大規模改修がようやくやっていただけるのかという思いですが、まず、この工事に入る際に、休館という形になるのか、どういう形になるのかをまず１点お伺いします。一部はどこかでホールは使えるのだけれどもとか、部分的には開放するけれども、それとも全体を休館扱いにして、工期である来年の３月３１日まで休館扱いにするのかどうかをお聞かせください。","respondent":"安藤文化スポーツ振興課長","answer":"荏原文化センターの休館ですけれども、これは全館を休館にします。休館の期間ですけれども、８月１日から来年の７月末までということで、全館を休館にします。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問","question":"全館休館、プールも休館ということなのか、あと、休館するのであれば、ここは結構、土日は平日もいろいろな団体が使っていると思いますが、その団体の方々に対してはどういった、どこかに振り分けるというか、そういう説明もしっかりされているのかどうかを教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"真っ先に荏原文化センターには利用者懇談会という大きなものがあります。そこにも会長を初め皆様にご説明を１１月１２日にさせていただきました。そして、利用団体についてですけれども、大きく分けてプールの団体と講習室等の文化系の団体があります。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは５月２７日に入札ということで、今回、３億３,４８０万円ということですけれども、これは途中で物価がまたいろいろ、工事費が上がるかどうかはわからないですけれども、そういった場合には、すぐにでも補正予算を組んでスライド条項を適用という形でやられるのかどうなのか、これが今、一番、資材にしても一番運用の部分なのかというので、またさらに値上がりというか、高くなる可能性もあるので。","respondent":"立川経理課長","answer":"スライド条項の適用ということに関しましては、実際、工期の関係、残工事の期間とか、その辺を総合的に勘案して適用については事業者と協議したいと考えているところです。今のところは、適用の予定はございません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"この間、発表されてから、いろいろ利用者・利用団体からいろいろ意見もあり、区もいろいろ当たってきたのだというご説明が先ほどありましたけれども、工事をすれば利用ができなくなるのは当然なわけですから、利用している団体がどういうふうに個々の活動を継続できるのかを、工事がされるということとあわせて代替の措置もしっかり同時に検討して示していくことが。","respondent":"安藤文化スポーツ振興課長、立川経理課長","answer":"このような形で利用はできますよと。ですから、私どもは予定内、想定内ということで、同じような形で進んでいるです。工事契約につきましては、先ほども説明いたしましたとおり、最新の労務単価、最新の積算単価をもとにやっておりますので、いわゆる工事開始以降、例えば資材等の急激な高騰、または人件費等の大幅な改定等。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、工事内容についてですけれども、トイレの改修が含まれておりますので、ぜひ障害がある方の意見を取り入れて進めていただきたいのと、もう１点、大規模改修を機に、耳の聞こえが悪い方への磁気ループをぜひ設置していただきたいと以前から求めてきたのですけれども、いよいよ工事が始まる中で、どう検討されているのか、いないのか、伺いたいと思います。","respondent":"立川経理課長、小林施設整備課長","answer":"事業者と契約したときの契約金額は、一次下請、二次下請に対して、どういうふうに支払われているかというご質問だと思いますが、こちらとしましては、いわゆる契約の段階で契約約款等におきまして。今ご質問のあった磁気ループですが、現在、設置する考えは、今のところありません。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"労務単価のことですけれども、適正に履行されているかどうかを区はどうやって確認するのかということを伺いたいと思います。それと、今回の契約も消費税８％増分としてしているわけですけれども、下請、二次下請、末端が契約の中で、事実上、自分たちが自腹を切らざるを得ない、こういう状況になってはいけないということをどう確認するのか伺いたいと思います。","respondent":"立川経理課長、小林施設整備課長","answer":"契約された事業者の方が、一次下請、二次下請、また外注先に対してお金を支払うことは社会レベル経済のルールの中でやってもらっていることですので、直接契約の中で賃金の支払いの確認ということは。磁気ループのご質問ですけれども、今回の荏原文化センターと図書館の工事の中心は、耐震改修工事です。は耐震改修を行うのが第一にありますので、ホールの床は工事する予定はございません。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"繰り返しになりますけれども、労務単価と消費税の問題について、契約でそうあるから履行されるはずなのだというのではなくて、履行されていることをどう確認するのかと伺ったのです。もちろん契約ですから、契約どおりに従ってくださいと、それは契約ですからそうですけれども、その契約どおり労務単価や消費税の転嫁をどう確認するのかと、ここを改めて伺いたいと思います。","respondent":"中山総務部長","answer":"この辺は周知しながらきちんと、そういう点で間接的ではありますけれども、区としても見ていくという姿勢を持ってまいりますので、個別の把握をするものではありませんけれども、当然ながらこういう改定がきちんと労働者に行き渡るようにという意識を持って現場を見てまいります。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど来、最新の労務単価、積算単価というお話がずっと出るのだけれども、１年でもいいです、１年半ぐらい前でもいいです、そこからどれぐらい上がったと我々は理解する、２割とか、例えば３割だとか、大体の概算でいいです、それは個々はいろいろあるのでしょうが、大くくりで大体一つの工事で２割は上がったと思っているとか、３割は上がっている、例えば人件費だったら。","respondent":"小林施設整備課長","answer":"よって、機械物については見積もりをとっておりますので、この機械が、今言った３億３,４８０万円というのが何割アップしたのかというのは、直接は出ないのですけれども、労務単価のほうは、１年で１０％弱の上昇があったということです。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望だけしておきます。この何年間とめると。そうすると、必ず今のお話ではないけれども、これは見積もりをとって、その中でやっているから入札もある程度成立するということもあるのでしょうが、そこら辺の、今度、発注する側の政策判断が出てきてしまうわけだけれども、ここら辺はぜひ両方を見比べて、どちらがいいのか考えてやっていただきたいと、それだけは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"例えば、教育機能をもう少し持たせようと思ったならば、教育費からの支出が増えていくでしょうし、もっと違う、区民全体にとなると、また違うところでの支出が出てくるだろうということがあるので、そこを含めた全体的な考え方をお聞きしたいのですが、どうとらえてこれを改修という、ただ単に耐震しますだけではないと思っているのですけれども、そういう考え方はいかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"所管としましては、これは計画的な耐震改修工事です。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"せっかく耐震改修をするという意味においては、耐震だけではなくて、いい機会なので、３億円３,４８０万円使うわけですから、多少目的を複数の形でプラスアルファしてもいいのではないかと私は思っていて、お金を改修というだけではなくて、もう少し発展的な改修ということもせめてやるべきではないかと思っているのですが、そういう考えは全くないということでの改修なのでしょうか。","respondent":"桑村企画部長","answer":"その中で耐震をしなければならないということでありますので、どうしても今の仕様といいましょうか、やっている中身の中でのグレードアップしかできなくて、この中で例えば施設を大きくするとか、そういう検討ができないものですので、ただ、耐震をしなければ。","id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"工事の中での制約がいろいろあってということなのでしょうか。その中での、今回は改修だけれども、いろいろ考えていくよというのであれば、今回は仕方がないというか、最低限必要な部分なのかと感じているのですけれども、そうすると、この支出科目の中で総務費・教育費と出ていますけれども、これはあくまで工事概要の中でのただ単に割り振りをしたということなのでしょうか。そこを確認したい。","respondent":"桑村企画部長","answer":"全て荏原文化センターのほうは総務費、図書館は教育費で対応していますので、面積の中身の中で工事費を割っているだけですので、特にこの比率が云々という考え方はありません。今の事業をやっているお支払いしている費目をそのまま、この工事についても適用したという部分です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"要望でお願いしたいと思いますが、緊急性のあるもの、耐震は当然、やらなければならないことだと思いますが、長期にわたっての目的で近隣の施設を整理されている中で、この荏原文化センターの役割は何なのかといったときには、その意味で考えていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"この工事自体は必要な工事だと思いますので、賛成しますが、磁気ループであったり、防犯対策であったり、この工事を機にさまざまな住民から上がっている要望もぜひ反映していただきたいと、この点は要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"これはまさに品川区議会で意見書をという請願だと考えています。それは、お考えはお考えとして、もちろんそれはお考えを述べることは構わないと考えていますけれども、私としては、区議会としてこれを意見書として今議論されている中で上げていくべきではないだろうという判断をしているということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"しかも、７月１日にも閣議決定を狙っている、それを止めてほしいという中身ですから、まさに区議会としての姿勢が問われると私は思います。ですので、ぜひ他の委員にもそれぞれ憲法９条についてお考えはあると思います。その上で、品川区にもぜひ伺いたいと思いますけれども、本会議で非核平和都市品川宣言のことが引用されておりました。失礼ながら区の見解、理解を伺いたいと思います。","respondent":"江部総務課長兼危機管理室長","answer":"区としては、憲法を尊重するということ、それから平和という点につきましては、今おっしゃられた恒久平和と核兵器の廃絶ということの２点に特化して、それを目標にやってきているところですので、どの戦争がということではなく、全体としてとらえているということであって。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"本会議でも触れられておりますし、今年は３０周年でいろいろ事業もありますけれども、これは恒久平和の願いは、区は戦争反対ではないのですか。戦争反対なのですか。そこを改めて伺いたいと思います。それと集団的自衛権、また立憲主義、これをどういうふうに理解しているのか。人を殺し、殺される、その道具をつくる、製造する、核実験をしていく、何が違うのか、そこを伺いたいと思います。","respondent":"渡部委員長","answer":"すみません、先に失礼いたします。今回、この出ております請願はあくまでも品川区議会として反対の決議を行ってほしい、意見書を上げてほしいという内容です。集団的自衛権に対しましては、国の機関ですので、答えられる範囲でお願いいたします。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"答えられる範囲でとおっしゃいますけれども、集団的自衛権はどういう考えなのか、立憲主義とはどういう考えなのか、区としてそれをどう失礼ながら理解しているのかということを聞いているのであって、国がこう言っていますという意見ではなく、区のみずからの団体としての見解を伺っている範囲だということで、国の見解を聞いているわけではない。","respondent":"中山総務部長","answer":"本会議でも区長がご答弁申し上げたように、議会の場で品川区として、例えば外交であったり、戦争に関すること、そういうことについてのコメントをする立場ではないという認識の上ですけれども、先ほど総務課長が申し上げたとおり、品川区は、世界の恒久平和。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"恒久平和とは戦争反対だとは言えないということですか。さまざまな平和の思いがあるでしょう。区としても、３０年間積み上げてきた事業や子どもたちに伝えてほしい事業もあるでしょう。それを進めていた品川区が、恒久平和は戦争反対だとなぜ言えないのですか。私、そこを伺いたいと思います。立憲主義についてなぜ説明できないのですか。憲法９条もそうです。しっかりとご説明いただきたいと思います。","respondent":"渡部委員長","answer":"しかしながら、今回の決議をとるに当たっての請願内容から見ましても、区の立場ですとか、今そこで繰り入れるものではありませんので、いかがでしょう。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"繰り入れるものではないの意味がわからないです。請願は、初めに呼びかけましたけれども、みんながこれをやろうではないかと、その上で区の考えを聞いて、一体何がいけないのでしょうか。しかも、冒頭から答えがないわけですよね。ですから聞いているのです。つまり、立憲主義とは何ですか、なぜそれを答えることができないのですか、シンプルに言えばそういうことです。ということで質問しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、その違いは、要するに立憲主義とは何ですかと。我々地方自治も、憲法第８章地方自治、これに基づいて日々活動が行われているわけです。この立憲主義とは何なのかと、ここは訂正を求めるより、改めて伺いたいと思います。これは、どのような目的でいつから実施されているのか伺います。しかも、明日にも閣議決定と報道されている。感じなければ感じないで、その理由をしっかり説明してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"私がこの請願の決議を上げるに当たって必要だと思った質問です。それ以上でもそれ以下でもありません。いや、そうではないだろうという意見があれば、それはそれで、それぞれ、ご意見ですから、出していただいて、それが議会ですからいいのですけれども、私が必要だと思った意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"認めるか、認めないのか、どちらの立場に身を置くのか、区としてそこを伺います。品川区はなぜこの激励会をどのような目的で、いつから実施しているのか、品川の若者を送り出している責任をどう感じているのか、これはお答えがありませんので、答えていただきたいと思います。何らかの宣言をされておりますよね。そのことはぜひ思い出していただきたいので、具体的にどうだったのか、ぜひ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、その求めるこの請願の中身について、もっと闊達な、委員同士でも構わないのですが、それを議論すべきだと思います。委員長に求めたいのは、意見書提出を求める請願について、この中身、先ほど読んでいただきましたけれども、そこについて議論をしていくべきではないでしょうか。せっかく総務委員会にこうやって出されているのですから、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"先に、先ほどの私の質問は答弁を再度求めますので、お答えいただきたいと思います。そういう意味では、この意見書を出すことは、私は、区民の平和への思い、戦争は嫌だというその思い、それをしっかり受けるものだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"中塚委員がご意見を言うのは、先ほど私も冒頭話をしたのだけれども、これに対する意見書を出すと求める請願でありますので、これはやりますけれども、今、中塚委員がまさにいろいろ立憲主義とか、法律と立憲主義は違うというようなお話をされていたけれども、先ほど来、私は区に問う話ではないと思っているのは、我々が、議会が一般質問して、区の立場は区長が首長として答弁をしているということがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が先ほどから聞いたのは、上げるに当たって区の現在の姿勢を伺ったという範囲ですので、決して否定という、そういう思いでただ質問したわけではないということをつけ加えておきます。私は明文改憲も反対です。言うまでもありませんけれども。これは許されない。この一点でこの請願は「解釈改憲による集団的自衛権の行使容認に反対する意見書を」と求めているのだということを強く呼びかけたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"いながわ委員","kind":"意見","question":"解釈改憲はやるべきでないと思っていますので。しかしながら、この請願趣旨とか請願項目の中を見ると、私どもの政党が言っていることと多少逸脱している部分があるので、それに関しては、訂正をして提出したいという部分ではありますが、この表題にある「解釈改憲による集団的自衛権の行使容認」に対しては、意見書を提出することに賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問","question":"もしこのような集団的自衛権行使をするならば、歴代政権が４０年以上、集団的自衛権を見送ってきたわけですから、するならば、きちっと憲法を改正してやるのが本筋ではないかと私は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"いながわ委員","kind":"意見","question":"つけ足しですみません、我が政党というか、会派も含めてですけれども、あくまでも集団的自衛権について反対しているわけではなく、先ほど須貝委員にあったように、それはもう改憲をしてしっかり明記すべきだという部分を訴えておりますので。ただ、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"本間副区長を初め、区の考え方は考え方であろうと思っていますけれども、今回の請願は品川区議会としてというあり方ですから、これを考えたときに、今回、いろいろとハイスピードで行われているという部分もあり、いろいろな動きがあるというのはわかっているのですけれども、では、品川区議会はどうなのかというと、これに対して、例えば特別委員会をやるとか、何か議会運営委員会でいろいろな話が出たのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"塚本副委員長","kind":"意見","question":"今、さまざまな報道がされている中で、こういったさまざまな見解も非常に相入れないようなさまざまな見解が出ている中で、今、与党協議会で解釈をどうしていくかという議論がされている最中に、私どもの会派としては、報道ベースではありますけれども、現在行われている議論は９条の規範性というものは変えないということだと受けとめております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"もちろん、私は私の思いがありますので、ここに書かれている一つ一つの文言は、私なりにそのとおりだとは思いますけれども、表現は表現で工夫をすれば賛同できる余地があるのであれば、まずは請願項目は「解釈改憲による集団的自衛権の行使容認に対して反対の決議を」ということですから、そこで一致できるのであれば、次にこの文言を整備しつつ、明日も総務委員会がありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"石田（秀）委員","kind":"意見","question":"本日結論を出します。意見は、先ほど来、いろいろ個人的な部分も含めて考えを言わせていただいたということであります。私は、その考え方に対しては理解をしているということがあります。そういうことも含めると、私は、先ほど来言っているように、品川区議会としてこの請願に対しては賛成しかねる、不採択、それでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"先ほど述べたとおりですけれども、現在の報道によれば、憲法９条の規範性、専守防衛ということにおいては、これは変わるものではないのだということで、そういう立場において、この請願については結論を出して、不採択とさせていただきたいと、このように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"いながわ委員","kind":"意見","question":"先ほど申し上げたように、結論を出すということで、何度も恐縮ですが、解釈改憲はやるべきではないというのが政党および会派の考え方ですので、この表題に関しては賛成をして、意見書を出すという部分には賛成します。しかしながら、先ほど申し上げましたように趣旨、いろいろ中塚委員からもありましたけれども、一言一句大切だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"本日、結論を出してもらわないと、明日、閣議決定との報道もありますので、まず本日出すべきだということと、態度ですけれども、先ほどの副委員長、あえて公明党から、９条を変えるものではないという話がありましたけれども、今回のやられている解釈改憲による集団的自衛権の行使容認とは、まさに９条が禁止していた行為を認めるものだと私は思います。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"須貝委員","kind":"意見","question":"先ほど申し上げましたとおりで、うちのほうは、私自身はこの趣旨は十分理解できるので、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"本日、結論を出してください。この総務委員会で話をしていたのも二分に分かれるぐらいの内容だと思います。なので、ここで言う品川区議会としての意見書というまでには、まだまだ品川区議会の中がまとまっていないという判断をしますので、今回については不採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"確認","question":"今、中塚委員が言ったのを委員長のほうで仕切っていただかなくてはならないので、不採択が３名です。採択が２名です。今、趣旨採択という方がいたので、この方には態度をどちらかに決めてもらうか、例えば、私はそれは両方乗れないから退席するとか、何かいろいろなことはお一人に確認してからでないと、これはそれはできないと思うので、それはぜひ委員長のほうで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"須貝委員","kind":"意見","question":"わかりました。本日のこの場で決めるということならば、私の意見は先ほど申し上げたとおり、全文に対しては賛同はできないのですが、賛成、反対ということならば、賛成のほうに回します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"委員長の判断の理由を説明していただきたいと。そう判断したその心は、そこは説明していただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-04","title":"平成２５年度品川区一般会計予算繰越明許費繰越計算書","agenda":"平成２５年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"既に説明されていることかもしれないのですけれども、繰越明細で送ると言っていいのでしょうか、繰越明許というものがどういうもので、どういう根拠に基づくものなのか教えていただきたいのと、継続した工事が必要だからなのかと思いつつ、何に基づく対応なのか、もう少しご説明いただけますか。","respondent":"本城企画財政課長","answer":"これは、今回はこの議会にご報告ですが、平成２５年度の最終補正予算の段階で今の工事の見込み等、今ご説明したことをご説明して、補正予算内での措置として対応して、その結果の今回はご報告という、そういう関係です。","id":"exchange-063"}]},{"id":"topic-05","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今後、どういうタイミング、タイミングはまだわからないのでしょうか、どういう条例の改正が必要になってくるのか、どういう条例の設置が必要になってくるのか、一部改正なのか、設置なのか、関係条例の整備がどちらを指しているのかよくわからないのですけれども、今も教育委員会にかかわる、それとも区長部局にかかわるのかもわからないですけれども、変更となる条例がどういうものなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"確認","question":"よく聞いたほうがいいと思いますが、今、素直に聞いていて私の理解するところは、その部分と懇談会の部分は、所管が分かれてしまうのではないかと思っていますけれども、それは全部こちらでいいというのなら、ここでいいけれども、確かに条例はここでいいと思いますけれども、今やっている懇談会がどういう形でどうなってという話は、こちらでいいのかというのは私はわからないので、確認だけ。","respondent":"江部総務課長兼危機管理室長","answer":"条例につきましてですが、今、想定されておりますのは、懇談会は首長の下にぶら下がる関係なので、区長部局でやります。条例につきましては双方に分かれる形です。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/997792?Template=document&Id=1986#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":44694,"voices":175}}]);
